-- Blog: suma las notas del blog anterior (mujeresxmas.com, categoría "Nota de Interes") con su fecha
-- original, en la categoría "Notas de interés". No borra nada: si una nota ya existe, la deja como está.
-- Las fotos están en public/blog/<nota>/ del repo.

insert into public.blog_categories (name, slug)
values ('Notas de interés', 'notas-de-interes')
on conflict (slug) do nothing;

insert into public.blog_posts
  (title, slug, excerpt, content, content_html, reading_minutes, cover_path, cover_alt, author_name, published_at,
   category_id, status)
select v.title, v.slug, v.excerpt, v.content, v.content_html, v.reading_minutes, v.cover_path, v.cover_alt,
  v.author_name, v.published_at, (select id from public.blog_categories where slug = 'notas-de-interes'),
  'published'::public.content_status
from (values
  ('Violencia de género digital: no es virtual, es real', 'violencia-de-genero-digital-no-es-virtual-es-real', 'El hostigamiento y el acoso contra niñas y mujeres crece exponencialmente.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El hostigamiento y el acoso contra niñas y mujeres crece exponencialmente.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Internet se ha convertido en una extensión de la vida y la experiencia humana. Han surgido nuevos y variados mundos, prácticas sociales, sentimientos y relaciones, que fluyen y confluyen en ese espacio que parece intangible, pero que simultáneamente se percibe e influye en el espacio físico. En internet se habita, se reconstruyen identidades, se trazan trayectos y mapas digitales que abren incontables posibilidades que nunca se hubieran imaginado."}]},{"type":"paragraph","content":[{"type":"text","text":"El avance vertiginoso de las Tecnologías de la Información y la Comunicación (TIC), las nuevas formas de comunicación mediante las redes sociales, mensajería instantánea, la evolución de los dispositivos electrónicos, han facilitado la interacción simultánea y con ello el surgimiento de nuevas conductas ilícitas en relación con la violencia de género. Del mismo modo que hay personas que ejercen violencia de género en espacios públicos y privados de la vida física, también los entornos donde se desarrolla nuestra vida digital se utilizan para acosar, hostigar, manipular, difundir imágenes íntimas no consentidas, entre otras conductas."}]},{"type":"paragraph","content":[{"type":"text","text":"Aunque este fenómeno ha adquirido mayor relieve a lo largo de los últimos años, con frecuencia se pierde de vista que no es del todo nuevo. La violencia contra las mujeres que se observa en los espacios digitales es una extensión de la desigualdad y la discriminación de género que ha existido y existen en todos los aspectos de su vida. Esta forma de violencia se ha convertido en uno de los principales riesgos para la libertad de expresión, la privacidad y la seguridad digital de las mujeres causando graves daños a las propias víctimas y la comunidad digital."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Qué es la violencia de género digital?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Es toda forma de discriminación, acoso, explotación, incluyendo los abusos y todas las agresiones que se producen al usar redes sociales, correo electrónico, o cualquier medio dentro de las tecnologías de la información y de la comunicación."}]},{"type":"image","attrs":{"src":"/blog/violencia-de-genero-digital-no-es-virtual-es-real/violencia-de-genero-digital.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Es importante tener en cuenta que este tipo de comunicación tiene afectaciones a nivel físico, psicológico, sexual e incluso económico."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Tipos de violencia de género digital"}]},{"type":"paragraph","content":[{"type":"text","text":"Algunos tipos de violencia, que se han podido identificar: "},{"type":"text","text":"el acoso digital","marks":[{"type":"bold"}]},{"type":"text","text":", que tiene que ver con amenazas, lenguaje violento, llamadas insistentes, muy similar al acoso que se vive en el área no virtual."}]},{"type":"paragraph","content":[{"type":"text","text":"Por otra parte; la "},{"type":"text","text":"violencia sexual digital","marks":[{"type":"bold"}]},{"type":"text","text":", el tipo de ataque más frecuente es la difusión de imágenes, vídeos íntimos sin consentimiento. La difusión de información privada, conocida como "},{"type":"text","text":"doxing","marks":[{"type":"link","attrs":{"href":"https://latam.kaspersky.com/resource-center/definitions/what-is-doxing"}}]},{"type":"text","text":", consiste en divulgar datos personales con el fin de hacer daño a una persona."}]},{"type":"paragraph","content":[{"type":"text","text":"Por ejemplo, en el caso de activistas o figuras públicas que se difunda información sobre su domicilio, su familia con el fin de que personas que se oponen puedan atacarles conociendo esta información."}]},{"type":"paragraph","content":[{"type":"text","text":"El "},{"type":"text","text":"discurso de odio y expresiones discriminatorias","marks":[{"type":"bold"}]},{"type":"text","text":" suelen estar vinculadas a estereotipos, roles de género. Se incluyen los ataques xenófobos, racistas, cualquier cosa que esté vinculada a grupos que han sido históricamente discriminados por el contexto en el que se vive."}]},{"type":"paragraph","content":[{"type":"text","text":"Los "},{"type":"text","text":"ataques a la libertad de expresión ","marks":[{"type":"bold"}]},{"type":"text","text":"que pueden darse por parte del control del gobierno. Pero a veces las mismas plataformas son las que limitan los contenidos de forma automática, es decir que infringen las normas aunque no lo hagan, por ejemplo las fotografías de desnudos. El acceso no consentido a dispositivos y cuentas, puede ser tanto con hackeo o sin hackeo, es decir a través de bots o técnicas ya un poquito más complejas."}]},{"type":"paragraph","content":[{"type":"text","text":"Cuando una persona expresa: ‘yo obligo a mi pareja a entregarme sus contraseñas’, eso también es un tipo de violencia que no requiere hackeo, pero que tiene el mismo fin."}]},{"type":"paragraph","content":[{"type":"text","text":"Estos tipos de violencias digitales afectan a mujeres, niñas,","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"adolescentes y personas ","marks":[{"type":"bold"}]},{"type":"text","text":"LGBTIQ+","marks":[{"type":"link","attrs":{"href":"https://www.lavanguardia.com/vida/junior-report/20190627/463124839887/que-significan-siglas-lgbtiq.html"}},{"type":"bold"}]},{"type":"text","text":".","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Formas más evidentes de manifestación de la violencia de género digital"}]},{"type":"paragraph","content":[{"type":"text","text":"Muchas veces se resta importancia a la violencia que ocurre en el área digital. No solo porque no somos capaces de reconocerla sino también porque se ha normalizado."}]},{"type":"paragraph","content":[{"type":"text","text":"Una de las cosas que ayuda a identificar es la incomodidad. Esto ocurre en otros tipos de violencia de género porque es difícil nombrarla ya que las mujeres están acostumbradas a que ocurra. Pero cuando hay situaciones que generan cualquier tipo de incomodidad ahí se debe indagar y revisar lo que está ocurriendo."}]},{"type":"paragraph","content":[{"type":"text","text":"Otro punto importante es insistir en la importancia del consentimiento. Prácticamente todos los tipos de violencia que ocurren suceden a causa de la violación al consentimiento, como acceder a los dispositivos, la difusión de imágenes sin consentimiento."}]},{"type":"paragraph","content":[{"type":"text","text":"Es indispensable mantener abiertas estas conversaciones para que las mujeres empiecen a reconocer, pero también la gente de su entorno cercano pueda familiarizarse con lo que está ocurriendo."}]},{"type":"paragraph","content":[{"type":"text","text":"La suplantación de identidad. Esto podría derivar en otros tipos de ataque como extorsión económica o extorsión sexual, que es muy común. Por ejemplo, que una persona comente: “‘Me he creado este perfil. Tengo tus fotos. Sí, no me mandas otro video, voy a difundir estas fotos’, es sextorsión que es extorsión sexual. El simple hecho de que dupliquen la identidad de una persona es violencia."}]},{"type":"image","attrs":{"src":"/blog/violencia-de-genero-digital-no-es-virtual-es-real/genero-violencia.jpg","alt":null,"title":null}},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Medios donde más se ejerce la violencia de género digital."}]},{"type":"paragraph","content":[{"type":"text","text":"La violencia digital opera de manera combinada con otros tipos de violencias. Después de la violencia psicológica muchas veces se continua con violencia física, hasta llegar, en algunos casos a concretarse en un "},{"type":"text","text":"femicidio","marks":[{"type":"link","attrs":{"href":"https://oig.cepal.org/sites/default/files/20184_femicidio.pdf"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Con la violencia digital ocurre algo similar. Es decir, estos ataques por lo general se acompañan de otros tipos de agresiones físicas, psicológicas e impactan sobre los cuerpos de las niñas, de las mujeres, de las personas LGBTI."}]},{"type":"paragraph","content":[{"type":"text","text":"Se identifican casos más concretos. Por ejemplo, en el caso de monitoreo o acecho. Si una persona es capaz de instalar un software espía en el teléfono de la persona que desea agredir y registrar los lugares que visita, será mucho más fácil acceder al lugar donde se encuentra la persona y ejercer otro tipo de violencia, como podría ser la física."}]},{"type":"paragraph","content":[{"type":"text","text":"Recomendaciones básicas de seguridad digital","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Medidas preventivas","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Tomar medidas para reforzar la seguridad digital es la primera línea de defensa contra amenazas, ataques y actos de violencia en línea. Por supuesto, no todas las mujeres tienen las mismas prioridades o se ven amenazadas de la misma manera, y las medidas pueden variar según el caso. Es importante recordar que la ciberseguridad es un proceso personal que puede desarrollarse al propio ritmo y que se puede alcanzar con un poco de paciencia y una planificación apropiada."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Actualización de los dispositivos: ","marks":[{"type":"bold"}]},{"type":"text","text":"un dispositivo actualizado es menos vulnerable a los ciberataques."}]}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Protección frente a accesos no deseados: las contraseñas y patrones de desbloqueo deben ser secretos, ","marks":[{"type":"bold"}]},{"type":"text","text":"complejos y seguros ya que constituyen la primera barrera de seguridad para proteger la privacidad."}]}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Encriptado del contenido","marks":[{"type":"bold"}]},{"type":"text","text":": la mayoría de los sistemas operativos ofrecen la opción de cifrar el contenido del móvil de forma que para acceder a cualquier información hay que introducir una clave de seguridad."}]}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gestión de contraseñas: ","marks":[{"type":"bold"}]},{"type":"text","text":"además de no revelar a nadie las contraseñas, debe evitarse apuntarlas y utilizar una misma contraseña para todos los accesos. Para facilitar el trabajo puede utilizarse una herramienta de gestión de claves."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Denuncia la agresión a las autoridades","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Las mujeres tienen derecho a vivir una vida libre de violencia dentro y fuera de internet, y a recibir justicia cuando se vulnera este derecho. Denunciar ante las autoridades puede permitir que los actos de violencia digital queden registrados y debidamente documentados, y agilizar el retiro de contenido dañino por parte de las plataformas de internet, sobre todo en casos de ciberacoso, doxxing o distribución no consensuada de imágenes íntimas"}]},{"type":"paragraph","content":[{"type":"text","text":"A continuación, se facilitan los números de emergencia para solicitar ayuda en Argentina:"}]},{"type":"paragraph","content":[{"type":"text","text":"línea 144 / 1127716463 (WhatsApp)"}]},{"type":"paragraph","content":[{"type":"text","text":"Por su parte, a partir de lo previsto en la Convención Interamericana para Prevenir, Sancionar y Erradicar la Violencia contra la Mujer (Convención de Belém do Pará), los Estados tienen la obligación de prevenir, investigar, sancionar y reparar la violencia de género en línea cometida en contra de mujeres y las niñas con la debida diligencia."}]},{"type":"paragraph","content":[{"type":"text","text":"Si bien resta mucho por hacer para mejorar la atención y el seguimiento de la violencia digital por parte de las autoridades, lo cierto es que se han registrado avances en la región, con recientes esfuerzos de capacitación del funcionariado público e incluso con la creación en muchos países de leyes y unidades especiales de ciberseguridad. Asimismo, es importante tener presente que, aun ante conductas que pudieran resultarnos “nuevas”, los marcos jurídicos vigentes (incluso aquellos en los que no se han creado normas o no se han tipificado estos delitos) permiten encuadrar diversos actos de violencia digital contra las mujeres en leyes contra la ciberdelincuencia, leyes sobre la violencia contra la mujer, leyes penales y leyes sobre privacidad y protección de datos, así como investigarlos, enjuiciarlos y sancionarlos. Esto quizá requiera un conocimiento un poco más avanzado de conceptos y técnicas jurídicas, pero no significa que las sobrevivientes de violencia digital no puedan hacerlo si reciben la orientación debida."}]},{"type":"paragraph","content":[{"type":"text","text":". Acercamos algunas organizaciones que pueden brindar asesoría: "},{"type":"text","text":"Social TIC","marks":[{"type":"link","attrs":{"href":"https://socialtic.org/"}}]},{"type":"text","text":", "},{"type":"text","text":"Acoso online","marks":[{"type":"link","attrs":{"href":"https://acoso.online/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ver el video en YouTube","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=HSJNxIUp1yQ"}}]}]}]}'::jsonb, '<p><strong>El hostigamiento y el acoso contra niñas y mujeres crece exponencialmente.</strong></p><p>Internet se ha convertido en una extensión de la vida y la experiencia humana. Han surgido nuevos y variados mundos, prácticas sociales, sentimientos y relaciones, que fluyen y confluyen en ese espacio que parece intangible, pero que simultáneamente se percibe e influye en el espacio físico. En internet se habita, se reconstruyen identidades, se trazan trayectos y mapas digitales que abren incontables posibilidades que nunca se hubieran imaginado.</p><p>El avance vertiginoso de las Tecnologías de la Información y la Comunicación (TIC), las nuevas formas de comunicación mediante las redes sociales, mensajería instantánea, la evolución de los dispositivos electrónicos, han facilitado la interacción simultánea y con ello el surgimiento de nuevas conductas ilícitas en relación con la violencia de género. Del mismo modo que hay personas que ejercen violencia de género en espacios públicos y privados de la vida física, también los entornos donde se desarrolla nuestra vida digital se utilizan para acosar, hostigar, manipular, difundir imágenes íntimas no consentidas, entre otras conductas.</p><p>Aunque este fenómeno ha adquirido mayor relieve a lo largo de los últimos años, con frecuencia se pierde de vista que no es del todo nuevo. La violencia contra las mujeres que se observa en los espacios digitales es una extensión de la desigualdad y la discriminación de género que ha existido y existen en todos los aspectos de su vida. Esta forma de violencia se ha convertido en uno de los principales riesgos para la libertad de expresión, la privacidad y la seguridad digital de las mujeres causando graves daños a las propias víctimas y la comunidad digital.</p><p><strong>¿Qué es la violencia de género digital?</strong></p><p>Es toda forma de discriminación, acoso, explotación, incluyendo los abusos y todas las agresiones que se producen al usar redes sociales, correo electrónico, o cualquier medio dentro de las tecnologías de la información y de la comunicación.</p><img loading="lazy" src="/blog/violencia-de-genero-digital-no-es-virtual-es-real/violencia-de-genero-digital.jpg"/><p>Es importante tener en cuenta que este tipo de comunicación tiene afectaciones a nivel físico, psicológico, sexual e incluso económico.</p><h3>Tipos de violencia de género digital</h3><p>Algunos tipos de violencia, que se han podido identificar: <strong>el acoso digital</strong>, que tiene que ver con amenazas, lenguaje violento, llamadas insistentes, muy similar al acoso que se vive en el área no virtual.</p><p>Por otra parte; la <strong>violencia sexual digital</strong>, el tipo de ataque más frecuente es la difusión de imágenes, vídeos íntimos sin consentimiento. La difusión de información privada, conocida como <a target="_blank" rel="noopener noreferrer" href="https://latam.kaspersky.com/resource-center/definitions/what-is-doxing">doxing</a>, consiste en divulgar datos personales con el fin de hacer daño a una persona.</p><p>Por ejemplo, en el caso de activistas o figuras públicas que se difunda información sobre su domicilio, su familia con el fin de que personas que se oponen puedan atacarles conociendo esta información.</p><p>El <strong>discurso de odio y expresiones discriminatorias</strong> suelen estar vinculadas a estereotipos, roles de género. Se incluyen los ataques xenófobos, racistas, cualquier cosa que esté vinculada a grupos que han sido históricamente discriminados por el contexto en el que se vive.</p><p>Los <strong>ataques a la libertad de expresión </strong>que pueden darse por parte del control del gobierno. Pero a veces las mismas plataformas son las que limitan los contenidos de forma automática, es decir que infringen las normas aunque no lo hagan, por ejemplo las fotografías de desnudos. El acceso no consentido a dispositivos y cuentas, puede ser tanto con hackeo o sin hackeo, es decir a través de bots o técnicas ya un poquito más complejas.</p><p>Cuando una persona expresa: ‘yo obligo a mi pareja a entregarme sus contraseñas’, eso también es un tipo de violencia que no requiere hackeo, pero que tiene el mismo fin.</p><p><strong>Estos tipos de violencias digitales afectan a mujeres, niñas,</strong></p><p><strong>adolescentes y personas </strong><a target="_blank" rel="noopener noreferrer" href="https://www.lavanguardia.com/vida/junior-report/20190627/463124839887/que-significan-siglas-lgbtiq.html"><strong>LGBTIQ+</strong></a><strong>.</strong></p><h3>Formas más evidentes de manifestación de la violencia de género digital</h3><p>Muchas veces se resta importancia a la violencia que ocurre en el área digital. No solo porque no somos capaces de reconocerla sino también porque se ha normalizado.</p><p>Una de las cosas que ayuda a identificar es la incomodidad. Esto ocurre en otros tipos de violencia de género porque es difícil nombrarla ya que las mujeres están acostumbradas a que ocurra. Pero cuando hay situaciones que generan cualquier tipo de incomodidad ahí se debe indagar y revisar lo que está ocurriendo.</p><p>Otro punto importante es insistir en la importancia del consentimiento. Prácticamente todos los tipos de violencia que ocurren suceden a causa de la violación al consentimiento, como acceder a los dispositivos, la difusión de imágenes sin consentimiento.</p><p>Es indispensable mantener abiertas estas conversaciones para que las mujeres empiecen a reconocer, pero también la gente de su entorno cercano pueda familiarizarse con lo que está ocurriendo.</p><p>La suplantación de identidad. Esto podría derivar en otros tipos de ataque como extorsión económica o extorsión sexual, que es muy común. Por ejemplo, que una persona comente: “‘Me he creado este perfil. Tengo tus fotos. Sí, no me mandas otro video, voy a difundir estas fotos’, es sextorsión que es extorsión sexual. El simple hecho de que dupliquen la identidad de una persona es violencia.</p><img loading="lazy" src="/blog/violencia-de-genero-digital-no-es-virtual-es-real/genero-violencia.jpg"/><h3>Medios donde más se ejerce la violencia de género digital.</h3><p>La violencia digital opera de manera combinada con otros tipos de violencias. Después de la violencia psicológica muchas veces se continua con violencia física, hasta llegar, en algunos casos a concretarse en un <a target="_blank" rel="noopener noreferrer" href="https://oig.cepal.org/sites/default/files/20184_femicidio.pdf">femicidio</a>.</p><p>Con la violencia digital ocurre algo similar. Es decir, estos ataques por lo general se acompañan de otros tipos de agresiones físicas, psicológicas e impactan sobre los cuerpos de las niñas, de las mujeres, de las personas LGBTI.</p><p>Se identifican casos más concretos. Por ejemplo, en el caso de monitoreo o acecho. Si una persona es capaz de instalar un software espía en el teléfono de la persona que desea agredir y registrar los lugares que visita, será mucho más fácil acceder al lugar donde se encuentra la persona y ejercer otro tipo de violencia, como podría ser la física.</p><p><strong>Recomendaciones básicas de seguridad digital</strong></p><p><strong>Medidas preventivas</strong></p><p>Tomar medidas para reforzar la seguridad digital es la primera línea de defensa contra amenazas, ataques y actos de violencia en línea. Por supuesto, no todas las mujeres tienen las mismas prioridades o se ven amenazadas de la misma manera, y las medidas pueden variar según el caso. Es importante recordar que la ciberseguridad es un proceso personal que puede desarrollarse al propio ritmo y que se puede alcanzar con un poco de paciencia y una planificación apropiada.</p><ul><li><p><strong>Actualización de los dispositivos: </strong>un dispositivo actualizado es menos vulnerable a los ciberataques.</p></li></ul><ul><li><p><strong>Protección frente a accesos no deseados: las contraseñas y patrones de desbloqueo deben ser secretos, </strong>complejos y seguros ya que constituyen la primera barrera de seguridad para proteger la privacidad.</p></li></ul><ul><li><p><strong>Encriptado del contenido</strong>: la mayoría de los sistemas operativos ofrecen la opción de cifrar el contenido del móvil de forma que para acceder a cualquier información hay que introducir una clave de seguridad.</p></li></ul><ul><li><p><strong>Gestión de contraseñas: </strong>además de no revelar a nadie las contraseñas, debe evitarse apuntarlas y utilizar una misma contraseña para todos los accesos. Para facilitar el trabajo puede utilizarse una herramienta de gestión de claves.</p></li></ul><p><strong>Denuncia la agresión a las autoridades</strong></p><p>Las mujeres tienen derecho a vivir una vida libre de violencia dentro y fuera de internet, y a recibir justicia cuando se vulnera este derecho. Denunciar ante las autoridades puede permitir que los actos de violencia digital queden registrados y debidamente documentados, y agilizar el retiro de contenido dañino por parte de las plataformas de internet, sobre todo en casos de ciberacoso, doxxing o distribución no consensuada de imágenes íntimas</p><p>A continuación, se facilitan los números de emergencia para solicitar ayuda en Argentina:</p><p>línea 144 / 1127716463 (WhatsApp)</p><p>Por su parte, a partir de lo previsto en la Convención Interamericana para Prevenir, Sancionar y Erradicar la Violencia contra la Mujer (Convención de Belém do Pará), los Estados tienen la obligación de prevenir, investigar, sancionar y reparar la violencia de género en línea cometida en contra de mujeres y las niñas con la debida diligencia.</p><p>Si bien resta mucho por hacer para mejorar la atención y el seguimiento de la violencia digital por parte de las autoridades, lo cierto es que se han registrado avances en la región, con recientes esfuerzos de capacitación del funcionariado público e incluso con la creación en muchos países de leyes y unidades especiales de ciberseguridad. Asimismo, es importante tener presente que, aun ante conductas que pudieran resultarnos “nuevas”, los marcos jurídicos vigentes (incluso aquellos en los que no se han creado normas o no se han tipificado estos delitos) permiten encuadrar diversos actos de violencia digital contra las mujeres en leyes contra la ciberdelincuencia, leyes sobre la violencia contra la mujer, leyes penales y leyes sobre privacidad y protección de datos, así como investigarlos, enjuiciarlos y sancionarlos. Esto quizá requiera un conocimiento un poco más avanzado de conceptos y técnicas jurídicas, pero no significa que las sobrevivientes de violencia digital no puedan hacerlo si reciben la orientación debida.</p><p>. Acercamos algunas organizaciones que pueden brindar asesoría: <a target="_blank" rel="noopener noreferrer" href="https://socialtic.org/">Social TIC</a>, <a target="_blank" rel="noopener noreferrer" href="https://acoso.online/">Acoso online</a></p><p><a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v=HSJNxIUp1yQ">Ver el video en YouTube</a></p>', 8, '/blog/violencia-de-genero-digital-no-es-virtual-es-real/violencia-de-genero-digital-acoso.jpg', 'Violencia de género digital: no es virtual, es real', 'Mujeres x Más', '2022-10-11T16:45:37-03:00'::timestamptz),
  ('Venta directa: una alternativa frente a la caída del empleo', 'venta-directa-una-alternativa-frente-a-la-caida-del-empleo', 'Las compras por catálogo, redes y online bajo el modelo de venta directa se convirtieron en una forma de paliar la pérdida de empleo e ingresos. La relación entre este segmento y la baja del mercado laboral. La alta…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Las compras por catálogo, redes y online bajo el modelo de venta directa se convirtieron en una forma de paliar la "},{"type":"text","text":"pérdida de empleo e ingresos","marks":[{"type":"bold"}]},{"type":"text","text":". La relación entre este segmento y la baja del mercado laboral. La alta demanda en esta pandemia puso a prueba la capacidad real de las empresas que operan bajo este formato de comercialización de sus productos siendo la "},{"type":"text","text":"venta directa","marks":[{"type":"link","attrs":{"href":"/blog/emprendimientos-online-venta-directa"}},{"type":"bold"}]},{"type":"text","text":" ","marks":[{"type":"bold"}]},{"type":"text","text":"una alternativa frente a la caída del empleo."}]},{"type":"paragraph","content":[{"type":"text","text":"Se registra un Nro. superior a 100.000 nuevas personas que integran estas redes; un número similar a la cantidad de personas trabajadoras que dejó de ser parte del mercado de trabajo argentino en el mismo período."}]},{"type":"paragraph","content":[{"type":"text","text":"La industria de la venta directa sumó un 11% de inscripciones durante 2020 comparado con 2019. Es casi tres veces la tasa de crecimiento anual que las empresas del sector registraron entre los años previos a la Pandemia. El dato es aún más sorprendente cuando se pone la lupa sobre la cantidad de operaciones que 35 compañías del rubro recibieron de sus revendedores: 70% más entre mayo de 2012 y 2016."}]},{"type":"paragraph","content":[{"type":"text","text":"Algunas razones","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"El "},{"type":"text","text":"desequilibrio","marks":[{"type":"bold"}]},{"type":"text","text":" se da por una demanda decreciente de las empresas frente a una oferta alta, principalmente en trabajadoras "},{"type":"text","text":"mujeres","marks":[{"type":"bold"}]},{"type":"text","text":". Esa falta de puestos de trabajo genuinos y formales refleja la frustración de 1,3 millones de personas que buscaron empleo en los primeros tres meses de 2021 sin suerte."}]},{"type":"paragraph","content":[{"type":"text","text":"Y a eso se le suman 2,8 millones que no tienen otra opción que ganar dinero en la informalidad, sin aporte alguno. Las cifras oficiales del INDEC son la evidencia empírica de que la calidad laboral en la Argentina empeora con el paso del tiempo."}]},{"type":"paragraph","content":[{"type":"text","text":"La constante "},{"type":"text","text":"regulación del Estado","marks":[{"type":"bold"}]},{"type":"text","text":" en el mercado de trabajo argentino explica este fenómeno en ascenso. Cuando el Gobierno obliga al sector privado a ir en contra de las leyes de la economía no hace otra cosa que generar desequilibrios. El costo laboral no salarial se encarece con la exigencia oficial de la doble indemnización o con la prohibición de los despidos, entre otras razones."}]},{"type":"paragraph","content":[{"type":"text","text":"La demanda laboral es alta.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Las ","marks":[{"type":"bold"}]},{"type":"text","text":"mujeres","marks":[{"type":"link","attrs":{"href":"/"}},{"type":"bold"}]},{"type":"text","text":" son las que más sufrieron la pérdida de empleo en la pandemia.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Según analistas privados consultados por "},{"type":"text","text":"El Cronista","marks":[{"type":"link","attrs":{"href":"https://www.cronista.com/?utm_source=Search&utm_campaign=marca&utm_content=el_cronista&gclid=CjwKCAjw_ISWBhBkEiwAdqxb9rt-IxOTQP4FuqJkn-WLqjjGQpguLherVmmRDkguGQRHxgqYL9y6TBoCLcYQAvD_BwE"}}]},{"type":"text","text":", la tasa de desempleo que hoy es de 10,2% debería estar en 15% porque durante los 18 meses de Pandemia se amplió la brecha entre la población económicamente activa y el total de personas ocupadas. Eso es porque el avance de la asistencia monetaria del Gobierno desincentiva a que un grupo de la población salga a buscar trabajo aunque no esté ocupada."}]},{"type":"paragraph","content":[{"type":"text","text":"Pero la "},{"type":"text","text":"paradoja ","marks":[{"type":"bold"}]},{"type":"text","text":"es que esas estadísticas no capturan el fenómeno de más de un millón de personas revendedoras que son independientes (90% mujeres) que perciben ingresos mensuales como monotributistas (o incluso inscriptas en el régimen general de AFIP) a cambio de comercializar cosméticos, maquillajes, productos de belleza, artículos de cocina, filtros de agua y hasta insumos de limpieza de grandes compañías de venta directa."}]},{"type":"paragraph","content":[{"type":"text","text":"Los registros de la "},{"type":"text","text":"Cámara Argentina de Venta Directa ","marks":[{"type":"link","attrs":{"href":"https://www.cavedi.org.ar/"}}]},{"type":"text","text":"(CAVEDI) evidencian el salto en la cantidad de personas adeptas que sus 11 compañías asociadas sumaron en 2020. Son 11% más que en el año previo (918.000 mujeres y apenas 102.000 varones contra 828.000 y 92.000 en 2019). «La venta directa suele comportarse de forma contracíclica, sobre todo en momentos recesivos. Hay personas que buscan un ingreso adicional, otras que quieren ser independientes y también están las que necesitan trabajar porque no tienen otra cosa», explica Gonzalo Falcón, presidente de CAVEDI."}]},{"type":"paragraph","content":[{"type":"text","text":"Sector dominado por mujeres","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"La industria de la venta directa sigue siendo un sector dominado por las mujeres que ofrece a las empresarias oportunidades de ingresos, horarios de trabajo flexibles, capacitación y la capacidad de trabajar desde casa siendo las mujeres las "},{"type":"text","text":"impulsoras de la industria.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Las distintas Asociaciones de Venta Directa globales mantienen entre sus argumentos que este modelo de negocios empodera a las "},{"type":"text","text":"mujeres ","marks":[{"type":"bold"}]},{"type":"text","text":"empresarias al darles acceso a un modelo de negocio de bajo costo que ofrece independencia y flexibilidad, así como la oportunidad de crecer a su propio ritmo. «"},{"type":"text","text":"Las mujeres tienen éxito en la venta directa porque el modelo complementa sus valores y su naturaleza innata para establecer conexiones significativas con los demás, ya que en el núcleo de la venta directa está la creación de redes y son estas conexiones significativas las que las mujeres forjan con sus comunidades a través de su naturaleza solidaria","marks":[{"type":"italic"}]},{"type":"text","text":"«, expresa Lise de Kock, directora de relaciones públicas y marketing de la Asociación de Venta Directa (DSA) de Sudáfrica y uno de los países más afectados por las desigualdades laborales entre hombres y mujeres."}]},{"type":"paragraph","content":[{"type":"text","text":"«"},{"type":"text","text":"Las mujeres son, sin duda, los impulsores de la industria para la venta directa como consumidoras y empresarias","marks":[{"type":"italic"}]},{"type":"text","text":"«, dice de Kock."}]},{"type":"paragraph","content":[{"type":"text","text":"Venta online, redes sociales y mercado.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"El mercado laboral luego de la pandemia se transformó y mutó hacia la venta online y las redes sociales. «Este tipo de actividad que realizan las mujeres es una salida laboral para ellas en contexto de pandemia. El cierre de la presencialidad en escuelas, por ejemplo, limitó sus tiempos para salir del hogar lo que les redujo la posibilidad de inserción o continuidad en el mercado de trabajo tradicional. Se triplicaron las horas que destinan a tareas domésticas y de cuidado, lo que aumentó notablemente la brecha de género en el ámbito laboral», explica Anabel Chiara, economista de la subsecretaría de empleo del Gobierno de la Ciudad de Buenos Aires."}]},{"type":"paragraph","content":[{"type":"text","text":"La tasa de desempleo y de inactividad entre mujeres viene subiendo a un ritmo mayor en los últimos años. «Si bien la tasa de desempleo se contrajo en el primer trimestre del año, para las mujeres la realidad fue diferente. Aumentó un punto por año con una peor dinámica en la franja de menores de 30. Cuatro de esas jóvenes en edad de trabajar no consiguen empleo. Es el único segmento en el que la tasa de actividad cayó por cuarto trimestre consecutivo», agrega Chiara."}]},{"type":"paragraph","content":[{"type":"text","text":"Datos reales","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Empresas como "},{"type":"text","text":"Natura, Avón y Essen ","marks":[{"type":"bold"}]},{"type":"text","text":"están capitalizando la falta de oportunidades laborales para las mujeres. La fabricante local de cacerolas de aluminio fundido fue la primera en registrar un boom de oferta de trabajo en plena cuarenta. «Tuvimos que cerrar la incorporación de personas emprendedoras durante seis meses para evitar que la "},{"type":"text","text":"alta demanda","marks":[{"type":"bold"}]},{"type":"text","text":" nos llevara a un"},{"type":"text","text":" quiebre de stock","marks":[{"type":"bold"}]},{"type":"text","text":". En los primeros 10 días de mayo de 2020 se inscribió la misma cantidad de revendedoras que en todo 2019″, cuenta Agustín Jorge, CEO y gerente general de Essen, compañía oriunda de Venado Tuerto."}]},{"type":"paragraph","content":[{"type":"text","text":"Así como hubo mujeres que optaron por vender ollas en redes sociales para ocupar su tiempo libre y buscar una alternativa que les diera más independencia; otras eligieron hacer lo mismo con cosméticos, maquillaje, esmaltes de uñas y cremas corporales. Con 230.000 revendedoras en todo el país, Natura vio crecer su tasa de revendedores al ritmo de la digitalización."}]},{"type":"paragraph","content":[{"type":"text","text":"En Natura, por ejemplo, las consultas se duplicaron cuando comenzó la pandemia. «Estaban en el orden de las 50.000 al año y en 2020 fueron de 100.000», agrega Marcelo."}]},{"type":"paragraph","content":[{"type":"text","text":"Su colega, Rolando Castro, gerente general de Avon para mercados del Sur, coincide. «Nuestros colaboradores crecieron 24% en el último semestre del año pasado. Pasamos por dos etapas diferentes: un primer semestre limitado por la cuarentena y un segundo con un boom de ventas que nos generó dificultades de abastecimiento, incluso a pesar de que se produce todo en el país», cuenta el representante del negocio en la Argentina, Chile y Uruguay. Sin embargo, en 2021 se observa un amesetamiento después de los sorprendentes números de 2020."}]},{"type":"paragraph","content":[{"type":"text","text":"La caída del poder adquisitivo que generó el aumento de la inflación hizo más visible aún la falta de empleo. Eso explica el amesetamiento en el consumo de este año y la razón adicional para que más familias busquen ingresos nuevos."}]},{"type":"paragraph","content":[{"type":"text","text":"«Hay emprendedores que buscan un segundo ingreso, aunque trabajan en relación de dependencia», describe el CEO de Essen. Lo mismo ocurre con los revendedores de Avon y Natura. «El año pasado el 40% del gasto que se hacía afuera migró al hogar y ahí ganaron las ventas por catálogo o que se empezaron a hacer online y en las redes sociales», explica Castro. La ejecutiva de Natura asiente y agrega que «el incremento se agilizó con la digitalización» a pesar de que en 2021 todo volvió a los niveles del 2019 por la caída del salario real."}]},{"type":"paragraph","content":[{"type":"text","text":"Más operaciones","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Los datos que reflejan esta "},{"type":"text","text":"tendencia ","marks":[{"type":"bold"}]},{"type":"text","text":"los ven las operadoras de gestión de pago con nitidez. «Pago Fácil» le da servicio a más de 35 empresas de venta directa en todo el país. En mayo de 2021 procesaron 54% más de pagos de revendedores a filiales de Avon, Natura, Tupperware, Tsu, Swiss Just, entre otras marcas», cuenta Andrés Uranga, director de negocios de Pago Fácil. Sin el sesgo estadístico que generan los meses de cuarentena en 2020, el "},{"type":"text","text":"crecimiento ","marks":[{"type":"bold"}]},{"type":"text","text":"en los últimos dos años fue del 30% (2021-2019) y en los últimos cuatro, de 70% (2021-2016)."}]},{"type":"paragraph","content":[{"type":"text","text":"Las consecuencias de la intervención estatal en el mercado de trabajo están a la vista: un desempleo de dos dígitos registrado en el primer trimestre del año con un visible aumento del empleo informal y del subempleo, que estaba en 14% de los ocupados a fines de 2019 y cerró 2020 en 17%."}]},{"type":"paragraph","content":[{"type":"text","text":"Recomendaciones de MujeresxMas","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Curso redes sociales"}]},{"type":"paragraph","content":[{"type":"text","text":"Curso “Cómo mostrar tu trabajo y disfrutarlo”"}]},{"type":"paragraph","content":[{"type":"text","text":"Curso redes sociales"}]}]}'::jsonb, '<p>Las compras por catálogo, redes y online bajo el modelo de venta directa se convirtieron en una forma de paliar la <strong>pérdida de empleo e ingresos</strong>. La relación entre este segmento y la baja del mercado laboral. La alta demanda en esta pandemia puso a prueba la capacidad real de las empresas que operan bajo este formato de comercialización de sus productos siendo la <a href="/blog/emprendimientos-online-venta-directa"><strong>venta directa</strong></a><strong> </strong>una alternativa frente a la caída del empleo.</p><p>Se registra un Nro. superior a 100.000 nuevas personas que integran estas redes; un número similar a la cantidad de personas trabajadoras que dejó de ser parte del mercado de trabajo argentino en el mismo período.</p><p>La industria de la venta directa sumó un 11% de inscripciones durante 2020 comparado con 2019. Es casi tres veces la tasa de crecimiento anual que las empresas del sector registraron entre los años previos a la Pandemia. El dato es aún más sorprendente cuando se pone la lupa sobre la cantidad de operaciones que 35 compañías del rubro recibieron de sus revendedores: 70% más entre mayo de 2012 y 2016.</p><p><strong>Algunas razones</strong></p><p>El <strong>desequilibrio</strong> se da por una demanda decreciente de las empresas frente a una oferta alta, principalmente en trabajadoras <strong>mujeres</strong>. Esa falta de puestos de trabajo genuinos y formales refleja la frustración de 1,3 millones de personas que buscaron empleo en los primeros tres meses de 2021 sin suerte.</p><p>Y a eso se le suman 2,8 millones que no tienen otra opción que ganar dinero en la informalidad, sin aporte alguno. Las cifras oficiales del INDEC son la evidencia empírica de que la calidad laboral en la Argentina empeora con el paso del tiempo.</p><p>La constante <strong>regulación del Estado</strong> en el mercado de trabajo argentino explica este fenómeno en ascenso. Cuando el Gobierno obliga al sector privado a ir en contra de las leyes de la economía no hace otra cosa que generar desequilibrios. El costo laboral no salarial se encarece con la exigencia oficial de la doble indemnización o con la prohibición de los despidos, entre otras razones.</p><p><strong>La demanda laboral es alta.</strong></p><p><strong>Las </strong><a href="/"><strong>mujeres</strong></a><strong> son las que más sufrieron la pérdida de empleo en la pandemia.</strong></p><p>Según analistas privados consultados por <a target="_blank" rel="noopener noreferrer" href="https://www.cronista.com/?utm_source=Search&amp;utm_campaign=marca&amp;utm_content=el_cronista&amp;gclid=CjwKCAjw_ISWBhBkEiwAdqxb9rt-IxOTQP4FuqJkn-WLqjjGQpguLherVmmRDkguGQRHxgqYL9y6TBoCLcYQAvD_BwE">El Cronista</a>, la tasa de desempleo que hoy es de 10,2% debería estar en 15% porque durante los 18 meses de Pandemia se amplió la brecha entre la población económicamente activa y el total de personas ocupadas. Eso es porque el avance de la asistencia monetaria del Gobierno desincentiva a que un grupo de la población salga a buscar trabajo aunque no esté ocupada.</p><p>Pero la <strong>paradoja </strong>es que esas estadísticas no capturan el fenómeno de más de un millón de personas revendedoras que son independientes (90% mujeres) que perciben ingresos mensuales como monotributistas (o incluso inscriptas en el régimen general de AFIP) a cambio de comercializar cosméticos, maquillajes, productos de belleza, artículos de cocina, filtros de agua y hasta insumos de limpieza de grandes compañías de venta directa.</p><p>Los registros de la <a target="_blank" rel="noopener noreferrer" href="https://www.cavedi.org.ar/">Cámara Argentina de Venta Directa </a>(CAVEDI) evidencian el salto en la cantidad de personas adeptas que sus 11 compañías asociadas sumaron en 2020. Son 11% más que en el año previo (918.000 mujeres y apenas 102.000 varones contra 828.000 y 92.000 en 2019). «La venta directa suele comportarse de forma contracíclica, sobre todo en momentos recesivos. Hay personas que buscan un ingreso adicional, otras que quieren ser independientes y también están las que necesitan trabajar porque no tienen otra cosa», explica Gonzalo Falcón, presidente de CAVEDI.</p><p><strong>Sector dominado por mujeres</strong></p><p>La industria de la venta directa sigue siendo un sector dominado por las mujeres que ofrece a las empresarias oportunidades de ingresos, horarios de trabajo flexibles, capacitación y la capacidad de trabajar desde casa siendo las mujeres las <strong>impulsoras de la industria.</strong></p><p>Las distintas Asociaciones de Venta Directa globales mantienen entre sus argumentos que este modelo de negocios empodera a las <strong>mujeres </strong>empresarias al darles acceso a un modelo de negocio de bajo costo que ofrece independencia y flexibilidad, así como la oportunidad de crecer a su propio ritmo. «<em>Las mujeres tienen éxito en la venta directa porque el modelo complementa sus valores y su naturaleza innata para establecer conexiones significativas con los demás, ya que en el núcleo de la venta directa está la creación de redes y son estas conexiones significativas las que las mujeres forjan con sus comunidades a través de su naturaleza solidaria</em>«, expresa Lise de Kock, directora de relaciones públicas y marketing de la Asociación de Venta Directa (DSA) de Sudáfrica y uno de los países más afectados por las desigualdades laborales entre hombres y mujeres.</p><p>«<em>Las mujeres son, sin duda, los impulsores de la industria para la venta directa como consumidoras y empresarias</em>«, dice de Kock.</p><p><strong>Venta online, redes sociales y mercado.</strong></p><p>El mercado laboral luego de la pandemia se transformó y mutó hacia la venta online y las redes sociales. «Este tipo de actividad que realizan las mujeres es una salida laboral para ellas en contexto de pandemia. El cierre de la presencialidad en escuelas, por ejemplo, limitó sus tiempos para salir del hogar lo que les redujo la posibilidad de inserción o continuidad en el mercado de trabajo tradicional. Se triplicaron las horas que destinan a tareas domésticas y de cuidado, lo que aumentó notablemente la brecha de género en el ámbito laboral», explica Anabel Chiara, economista de la subsecretaría de empleo del Gobierno de la Ciudad de Buenos Aires.</p><p>La tasa de desempleo y de inactividad entre mujeres viene subiendo a un ritmo mayor en los últimos años. «Si bien la tasa de desempleo se contrajo en el primer trimestre del año, para las mujeres la realidad fue diferente. Aumentó un punto por año con una peor dinámica en la franja de menores de 30. Cuatro de esas jóvenes en edad de trabajar no consiguen empleo. Es el único segmento en el que la tasa de actividad cayó por cuarto trimestre consecutivo», agrega Chiara.</p><p><strong>Datos reales</strong></p><p>Empresas como <strong>Natura, Avón y Essen </strong>están capitalizando la falta de oportunidades laborales para las mujeres. La fabricante local de cacerolas de aluminio fundido fue la primera en registrar un boom de oferta de trabajo en plena cuarenta. «Tuvimos que cerrar la incorporación de personas emprendedoras durante seis meses para evitar que la <strong>alta demanda</strong> nos llevara a un<strong> quiebre de stock</strong>. En los primeros 10 días de mayo de 2020 se inscribió la misma cantidad de revendedoras que en todo 2019″, cuenta Agustín Jorge, CEO y gerente general de Essen, compañía oriunda de Venado Tuerto.</p><p>Así como hubo mujeres que optaron por vender ollas en redes sociales para ocupar su tiempo libre y buscar una alternativa que les diera más independencia; otras eligieron hacer lo mismo con cosméticos, maquillaje, esmaltes de uñas y cremas corporales. Con 230.000 revendedoras en todo el país, Natura vio crecer su tasa de revendedores al ritmo de la digitalización.</p><p>En Natura, por ejemplo, las consultas se duplicaron cuando comenzó la pandemia. «Estaban en el orden de las 50.000 al año y en 2020 fueron de 100.000», agrega Marcelo.</p><p>Su colega, Rolando Castro, gerente general de Avon para mercados del Sur, coincide. «Nuestros colaboradores crecieron 24% en el último semestre del año pasado. Pasamos por dos etapas diferentes: un primer semestre limitado por la cuarentena y un segundo con un boom de ventas que nos generó dificultades de abastecimiento, incluso a pesar de que se produce todo en el país», cuenta el representante del negocio en la Argentina, Chile y Uruguay. Sin embargo, en 2021 se observa un amesetamiento después de los sorprendentes números de 2020.</p><p>La caída del poder adquisitivo que generó el aumento de la inflación hizo más visible aún la falta de empleo. Eso explica el amesetamiento en el consumo de este año y la razón adicional para que más familias busquen ingresos nuevos.</p><p>«Hay emprendedores que buscan un segundo ingreso, aunque trabajan en relación de dependencia», describe el CEO de Essen. Lo mismo ocurre con los revendedores de Avon y Natura. «El año pasado el 40% del gasto que se hacía afuera migró al hogar y ahí ganaron las ventas por catálogo o que se empezaron a hacer online y en las redes sociales», explica Castro. La ejecutiva de Natura asiente y agrega que «el incremento se agilizó con la digitalización» a pesar de que en 2021 todo volvió a los niveles del 2019 por la caída del salario real.</p><p><strong>Más operaciones</strong></p><p>Los datos que reflejan esta <strong>tendencia </strong>los ven las operadoras de gestión de pago con nitidez. «Pago Fácil» le da servicio a más de 35 empresas de venta directa en todo el país. En mayo de 2021 procesaron 54% más de pagos de revendedores a filiales de Avon, Natura, Tupperware, Tsu, Swiss Just, entre otras marcas», cuenta Andrés Uranga, director de negocios de Pago Fácil. Sin el sesgo estadístico que generan los meses de cuarentena en 2020, el <strong>crecimiento </strong>en los últimos dos años fue del 30% (2021-2019) y en los últimos cuatro, de 70% (2021-2016).</p><p>Las consecuencias de la intervención estatal en el mercado de trabajo están a la vista: un desempleo de dos dígitos registrado en el primer trimestre del año con un visible aumento del empleo informal y del subempleo, que estaba en 14% de los ocupados a fines de 2019 y cerró 2020 en 17%.</p><p><strong>Recomendaciones de MujeresxMas</strong></p><p>Curso redes sociales</p><p>Curso “Cómo mostrar tu trabajo y disfrutarlo”</p><p>Curso redes sociales</p>', 8, '/blog/venta-directa-una-alternativa-frente-a-la-caida-del-empleo/venta-directa-una-alternativa-frente-a-la-caida-del-empleo.jpg', 'Venta directa: una alternativa frente a la caída del empleo', 'Mujeres x Más', '2022-07-06T15:50:39-03:00'::timestamptz),
  ('Verdadero o falso: ¿El crecimiento de blockchain es igual al de internet?', 'verdadero-o-falso-el-crecimiento-de-blockchain-es-igual-al-de-internet', 'Tanto blockchain como Internet tuvieron una proporción similar de partidarios y detractores. Pero al final, Internet condujo a lo que hoy es la era de la información.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Si pensabas que esta afirmación es cierta, ¡tienes razón!"}]},{"type":"paragraph","content":[{"type":"text","text":"Tanto "},{"type":"text","text":"blockchain","marks":[{"type":"bold"}]},{"type":"text","text":" como Internet tuvieron una proporción similar de partidarios y detractores. Pero al final, Internet condujo a lo que hoy es la era de la información."}]},{"type":"paragraph","content":[{"type":"text","text":"Ginni Rometty","marks":[{"type":"bold"}]},{"type":"text","text":", directora ejecutiva de IBM (2012 – 2020), a menudo dice que «blockchain hará por las transacciones lo que Internet hizo por la información»."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Qué significa esto? Significa que "},{"type":"text","text":"blockchain es más que datos transaccionales","marks":[{"type":"bold"}]},{"type":"text","text":". A medida que la tecnología madure, es probable que blockchain siga los mismos paralelismos con las primeras fases de Internet, pero a un ritmo mucho más rápido, y se conecte con otros sistemas, servicios y análisis. Esto será de la misma manera que Internet creció para conectarse con análisis y datos, inteligencia artificial y tecnologías cognitivas, e Internet de las cosas (IoT)."}]},{"type":"paragraph","content":[{"type":"text","text":"Blockchain","marks":[{"type":"bold"}]},{"type":"text","text":" se hizo popular por primera vez como la "},{"type":"text","text":"tecnología detrás de la criptomoneda","marks":[{"type":"bold"}]},{"type":"text","text":", Bitcoin."}]},{"type":"image","attrs":{"src":"/blog/verdadero-o-falso-el-crecimiento-de-blockchain-es-igual-al-de-internet/blockchain.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Bitcoin ","marks":[{"type":"bold"}]},{"type":"text","text":"ofrece "},{"type":"text","text":"una forma de transferir efectivo digital o electrónico","marks":[{"type":"bold"}]},{"type":"text","text":" directamente entre individuos. Tampoco se trata de PayPal o tarjetas de crédito. Con Bitcoin, ahora se pueden realizar "},{"type":"text","text":"pagos con un alto nivel de confianza a extraños","marks":[{"type":"bold"}]},{"type":"text","text":", sin necesidad de que una autoridad central como un banco o el gobierno autorice la transacción."}]},{"type":"paragraph","content":[{"type":"text","text":"Pero blockchain es y se ha convertido en mucho más que una criptomoneda, que descubrirá a medida que avance en este aprendizaje."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"¿Cómo funciona el blockchain?"}]},{"type":"paragraph","content":[{"type":"text","text":"Para responder eso, comencemos por desglosar la definición de blockchain. Si una cadena de bloques es una «cadena de bloques», ¿qué es un bloque?"}]},{"type":"paragraph","content":[{"type":"text","text":"Un bloque es un grupo de "},{"type":"text","text":"transacciones que se mantienen en orden cronológico y se codifican en una cadena de bloques","marks":[{"type":"bold"}]},{"type":"text","text":". Cada computadora que ejecuta código para una cadena de bloques determinada tiene los datos que contienen todas las transacciones que han tenido lugar en la cadena de bloques."}]},{"type":"paragraph","content":[{"type":"text","text":"Se escriben o extraen nuevos bloques cuando se realizan nuevas transacciones. Una vez que los bloques se escriben en la cadena de bloques, esos registros no se pueden borrar ni cambiar fácilmente."}]},{"type":"paragraph","content":[{"type":"text","text":"La siguiente imagen describe los pasos para construir una cadena de bloques:","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seguimiento de activos digitales"}]},{"type":"paragraph","content":[{"type":"text","text":"Blockchain rastrea el movimiento de valor o activos digitales desde el punto A al punto B","marks":[{"type":"bold"}]},{"type":"text","text":" utilizando tecnología de contabilidad distribuida. Esto significa que los registros de blockchain se distribuyen entre todas las computadoras que ejecutan su software. (Nota: ¡Este concepto también se introdujo en los dos videos en el tema explicado de Blockchain si necesita revisarlo!)"}]},{"type":"paragraph","content":[{"type":"text","text":"Las siguientes secciones resumen algunos malentendidos comunes sobre blockchain."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"¿Cuál es la diferencia entre la tecnología de contabilidad distribuida y una base de datos?"}]},{"type":"paragraph","content":[{"type":"text","text":"La principal diferencia entre una cadena de bloques y una base de datos es "},{"type":"text","text":"la descentralización","marks":[{"type":"bold"}]},{"type":"text","text":". Los registros en una cadena de bloques "},{"type":"text","text":"no se guardan en ninguna ubicación central única","marks":[{"type":"bold"}]},{"type":"text","text":"; "},{"type":"text","text":"se comparten entre computadoras simultáneamente","marks":[{"type":"bold"}]},{"type":"text","text":". Cada participante en una cadena de bloques tiene una copia segura de todos los registros y todos los cambios para que cualquiera pueda ver el registro de auditoría de los datos; "},{"type":"text","text":"no es necesario que un tercero ","marks":[{"type":"bold"}]},{"type":"text","text":"central de confianza audite las transacciones y se asegure de que todo sea correcto."}]},{"type":"paragraph","content":[{"type":"text","text":"La tecnología "},{"type":"text","text":"Blockchain","marks":[{"type":"bold"}]},{"type":"text","text":" requiere que todos los nodos de la red formen consenso. Esto significa que cuando las transacciones se transmiten a la red (por ejemplo, cuando su amigo le envía un bitcoin), la red debe validar estas transacciones."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"¿Hay diferentes tipos de cadenas de bloques?"}]},{"type":"paragraph","content":[{"type":"text","text":"Generalmente, las cadenas de bloques entran en la categoría de abiertas (públicas) o cerradas (privadas). La principal distinción entre ellos está relacionada con quién puede participar en la red, ejecutar el protocolo de consenso y mantener el libro mayor compartido."}]},{"type":"paragraph","content":[{"type":"text","text":"Cadenas de bloques públicas","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Distribuya la confianza y el poder entre todos los participantes de la red, lo que significa que cualquiera puede unirse y participar en ella. Bitcoin es una de las mayores redes públicas de blockchain en producción en la actualidad."}]},{"type":"paragraph","content":[{"type":"text","text":"Cadenas de bloques privadas","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Operan en un entorno «confiable» y se consideran más seguros."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Bitcoin es lo mismo que blockchain?","marks":[{"type":"bold"},{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"En caso de que te lo hayas perdido en los temas anteriores, Bitcoin, una moneda electrónica o criptomoneda, no es igual a blockchain. Bitcoin utiliza la tecnología de cadena de bloques como su libro mayor de transacciones para realizar un seguimiento de todas las transacciones de Bitcoin que han tenido lugar."}]},{"type":"paragraph","content":[{"type":"text","text":"Si querés conocer más de este tema te invitamos a ver este video"}]},{"type":"paragraph","content":[{"type":"text","text":"Ver el video en YouTube","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=r43LhSUUGTQ"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Si querés aprender más, podes ingresar a nuestros cursos y explorar todo el mundo del blockchain https://mujeresxmas.com/captaciones-online/"}]}]}'::jsonb, '<p>Si pensabas que esta afirmación es cierta, ¡tienes razón!</p><p>Tanto <strong>blockchain</strong> como Internet tuvieron una proporción similar de partidarios y detractores. Pero al final, Internet condujo a lo que hoy es la era de la información.</p><p><strong>Ginni Rometty</strong>, directora ejecutiva de IBM (2012 – 2020), a menudo dice que «blockchain hará por las transacciones lo que Internet hizo por la información».</p><p>¿Qué significa esto? Significa que <strong>blockchain es más que datos transaccionales</strong>. A medida que la tecnología madure, es probable que blockchain siga los mismos paralelismos con las primeras fases de Internet, pero a un ritmo mucho más rápido, y se conecte con otros sistemas, servicios y análisis. Esto será de la misma manera que Internet creció para conectarse con análisis y datos, inteligencia artificial y tecnologías cognitivas, e Internet de las cosas (IoT).</p><p><strong>Blockchain</strong> se hizo popular por primera vez como la <strong>tecnología detrás de la criptomoneda</strong>, Bitcoin.</p><img loading="lazy" src="/blog/verdadero-o-falso-el-crecimiento-de-blockchain-es-igual-al-de-internet/blockchain.png"/><p><strong>Bitcoin </strong>ofrece <strong>una forma de transferir efectivo digital o electrónico</strong> directamente entre individuos. Tampoco se trata de PayPal o tarjetas de crédito. Con Bitcoin, ahora se pueden realizar <strong>pagos con un alto nivel de confianza a extraños</strong>, sin necesidad de que una autoridad central como un banco o el gobierno autorice la transacción.</p><p>Pero blockchain es y se ha convertido en mucho más que una criptomoneda, que descubrirá a medida que avance en este aprendizaje.</p><h3>¿Cómo funciona el blockchain?</h3><p>Para responder eso, comencemos por desglosar la definición de blockchain. Si una cadena de bloques es una «cadena de bloques», ¿qué es un bloque?</p><p>Un bloque es un grupo de <strong>transacciones que se mantienen en orden cronológico y se codifican en una cadena de bloques</strong>. Cada computadora que ejecuta código para una cadena de bloques determinada tiene los datos que contienen todas las transacciones que han tenido lugar en la cadena de bloques.</p><p>Se escriben o extraen nuevos bloques cuando se realizan nuevas transacciones. Una vez que los bloques se escriben en la cadena de bloques, esos registros no se pueden borrar ni cambiar fácilmente.</p><p><strong>La siguiente imagen describe los pasos para construir una cadena de bloques:</strong></p><p>Seguimiento de activos digitales</p><p><strong>Blockchain rastrea el movimiento de valor o activos digitales desde el punto A al punto B</strong> utilizando tecnología de contabilidad distribuida. Esto significa que los registros de blockchain se distribuyen entre todas las computadoras que ejecutan su software. (Nota: ¡Este concepto también se introdujo en los dos videos en el tema explicado de Blockchain si necesita revisarlo!)</p><p>Las siguientes secciones resumen algunos malentendidos comunes sobre blockchain.</p><h3>¿Cuál es la diferencia entre la tecnología de contabilidad distribuida y una base de datos?</h3><p>La principal diferencia entre una cadena de bloques y una base de datos es <strong>la descentralización</strong>. Los registros en una cadena de bloques <strong>no se guardan en ninguna ubicación central única</strong>; <strong>se comparten entre computadoras simultáneamente</strong>. Cada participante en una cadena de bloques tiene una copia segura de todos los registros y todos los cambios para que cualquiera pueda ver el registro de auditoría de los datos; <strong>no es necesario que un tercero </strong>central de confianza audite las transacciones y se asegure de que todo sea correcto.</p><p>La tecnología <strong>Blockchain</strong> requiere que todos los nodos de la red formen consenso. Esto significa que cuando las transacciones se transmiten a la red (por ejemplo, cuando su amigo le envía un bitcoin), la red debe validar estas transacciones.</p><h3>¿Hay diferentes tipos de cadenas de bloques?</h3><p>Generalmente, las cadenas de bloques entran en la categoría de abiertas (públicas) o cerradas (privadas). La principal distinción entre ellos está relacionada con quién puede participar en la red, ejecutar el protocolo de consenso y mantener el libro mayor compartido.</p><p><strong>Cadenas de bloques públicas</strong></p><p>Distribuya la confianza y el poder entre todos los participantes de la red, lo que significa que cualquiera puede unirse y participar en ella. Bitcoin es una de las mayores redes públicas de blockchain en producción en la actualidad.</p><p><strong>Cadenas de bloques privadas</strong></p><p>Operan en un entorno «confiable» y se consideran más seguros.</p><p><strong><em>¿Bitcoin es lo mismo que blockchain?</em></strong></p><p>En caso de que te lo hayas perdido en los temas anteriores, Bitcoin, una moneda electrónica o criptomoneda, no es igual a blockchain. Bitcoin utiliza la tecnología de cadena de bloques como su libro mayor de transacciones para realizar un seguimiento de todas las transacciones de Bitcoin que han tenido lugar.</p><p>Si querés conocer más de este tema te invitamos a ver este video</p><p><a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v=r43LhSUUGTQ">Ver el video en YouTube</a></p><p>Si querés aprender más, podes ingresar a nuestros cursos y explorar todo el mundo del blockchain https://mujeresxmas.com/captaciones-online/</p>', 4, '/blog/verdadero-o-falso-el-crecimiento-de-blockchain-es-igual-al-de-internet/blockchain.jpg', 'Verdadero o falso: ¿El crecimiento de blockchain es igual al de internet?', 'Mujeres x Más', '2022-06-07T15:37:01-03:00'::timestamptz),
  ('Tu marca eres tu', 'tu-marca-eres-tu', 'Hace unos años pasé por una experiencia personal que me llevó a conocer y volcarme en el maravilloso mundo de las emociones, conectar conmigo misma, con mi esencia. Lo más importante fue que lo llevé al terreno…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hace unos años pasé por una experiencia personal que me llevó a conocer y volcarme en el maravilloso mundo de las emociones, conectar conmigo misma, con mi esencia. Lo más importante fue que lo llevé al terreno profesional, uniendo mi preparación profesional y mi experiencia en marketing estratégico, branding, e "},{"type":"text","text":"INTELIGENCIA EMOCIONAL.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Actualmente trabajo con emprendedores y profesionales, que buscan posicionarse exitosamente en su campo, llevando un único mensaje. “"},{"type":"text","text":"Encuentra tu esencia, se autentico/a, y se original, porque TU MARCA ERES TU”.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Y con el objetivo de llevar ese mensaje a la mayor cantidad de personas, he creado el evento: TU MARCA ERES TU, imagen de mujer, que tiene como propósito empoderar a las mujeres emprendedoras que buscan ser exitosas con sus emprendimientos, aportándoles herramientas esenciales para lograrlo."}]},{"type":"paragraph","content":[{"type":"text","text":"Mi mensaje es:"}]},{"type":"paragraph","content":[{"type":"text","text":"Puedes trabajar bastante para crear ese/a profesional de éxito que anhelas ser, estudiando, obteniendo cantidad de títulos, invirtiendo en masterados, pero si no conectas con tu esencia, no conectarás con el mundo que está allí esperando por lo que puedas aportar, entonces será un fracaso. Estamos en un entorno cada día más competitivo, donde es esencial poder diferenciarte, conociéndote y conociendo el mercado, saber lo que esperan y tener claro tu propuesta de valor. Esto te permitirá trabajar estratégicamente para generar esa visibilidad que necesitas y alinear tu imagen con lo que deseas proyectar, porque cuando te recuerden en el ámbito laboral, profesional, o empresarial, tu nombre irá asociado a una experiencia con esa o esas personas y a eso llamamos reputación."}]},{"type":"paragraph","content":[{"type":"text","text":"Mi objetivo con este artículo es "},{"type":"text","text":"compartir mi experiencia","marks":[{"type":"bold"}]},{"type":"text","text":" personal contigo, demostrando que, independientemente del sector en el que te desarrolles, puedes posicionarte como un profesional de éxito al crear una marca personal sólida, coherente, humana, auténtica, creíble y lo más importante, convertirte en un referente en tu sector."}]},{"type":"paragraph","content":[{"type":"text","text":"A continuación, algunos puntos importantes:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Mi súper Marca, YO:","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"¿Te has preguntado qué lugar ocupas en la mente de los demás, qué es lo que la gente dice de ti cuando no estás?"}]},{"type":"paragraph","content":[{"type":"text","text":"Aunque no lo creas, esa es la forma en que nos posicionamos con nuestra marca personal, cada experiencia con los demás, son huellas que vamos dejando. Como nos recuerdan, como nos ven y que sentimientos asocian a la experiencia de conocerte, es tu reputación, esta se convierte en tu posicionamiento."}]},{"type":"paragraph","content":[{"type":"text","text":"Es por ello por lo que, si deseas tener éxito, debes trabajar, desarrollar el producto más importante que tienes: Tú mismo."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Te has preguntado quién eres, cuáles son tus habilidades, que es lo que te apasiona hacer, cuál es tu talento?"}]},{"type":"paragraph","content":[{"type":"text","text":"Para responder estas preguntas es ideal que puedas realizar tu FODA (fortalezas, oportunidades, debilidades y amenazas), describe cuáles son tus fortalezas y tus debilidades, y de qué manera son percibidos por tu entorno, para saber si estas alineado con tus objetivos."}]},{"type":"paragraph","content":[{"type":"text","text":"Para llegar a ese punto, es más que importante tener un nivel de autoconocimiento elevado, entender el concepto que tienes de ti mismo, tu nivel de autoestima, y la forma en que te comparas con tu entorno, porque es la forma en que te proyectas al mundo y te perciben emocionalmente los demás."}]},{"type":"paragraph","content":[{"type":"text","text":"Tus fortalezas son el trampolín que necesitas para subir a la cima de tus sueños, tus debilidades, las que pueden jugar en contra de tu posicionamiento, pero las puedes superar."}]},{"type":"image","attrs":{"src":"/blog/tu-marca-eres-tu/nota-imagen-para-banner-principal.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Es importante poder obtener una medición a través de un estudio para evaluar tu posicionamiento actual y con base en esto trabajar en estrategias que te permitan alinear tu imagen y tu reputación, con tus objetivos."}]},{"type":"paragraph","content":[{"type":"text","text":"El secreto está en identificar tu esencia, reconocer tus fortalezas y potenciarlas. Desarrollar un producto de calidad, único y duradero, TU SÚPER marca: YO"}]},{"type":"paragraph","content":[{"type":"text","text":"2. Tu imagen externa:","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hay un dicho que dice, no solo debo ser, si no parecer, al crear visibilidad, estas creando el primer impacto, y los juicios de valor, es por ello que tu imagen externa debe ser coherente con el mensaje que deseas transmitir, como defines tu estilo, los colores, hablan de ti. Necesitas trabajar en elegir un estilo que te permita transmitir a nivel profesional todos los matices de tu personalidad y así generar el valor a tu marca."}]},{"type":"paragraph","content":[{"type":"text","text":"Esto abarca las fotos de tu web, de tus redes sociales, que reflejan cómo te vistes, como te presentas a un evento, tu vestuario elegido, para grabar tus vídeos, en tus visitas a clientes, cuál es tu vestuario al momento de impartir una ponencia"}]},{"type":"paragraph","content":[{"type":"text","text":"El mejor talento eres tú, pero exprésalo con actitud y apariencia."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Crea tu ventaja competitiva:","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cuando puedes definir tu valor, puedes trabajar en tu ventaja competitiva, que es aquello que te hace único e irrepetible y que debe ser recibido por tu entorno con un valor positivo, auténtico y único. Es de la forma en que el mercado te va a reconocer, pero que esto sea un éxito depende de la estrategia de comunicación que realices."}]},{"type":"paragraph","content":[{"type":"text","text":"Recuerda que quien tiene magia no necesita trucos"}]},{"type":"image","attrs":{"src":"/blog/tu-marca-eres-tu/imagen-adicional-para-la-nota-.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"4. Estrategia de comunicación y promoción:","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cuando ya tienes claro tu objetivo, podrás definir tu imagen, tu leguaje y que redes son útiles para poder generar esa visibilidad que necesitas."}]},{"type":"paragraph","content":[{"type":"text","text":"Recuerda que hoy en día, a través de las redes, llegas a un público mucho más grande y de manera directa, que otros medios de comunicación, por lo que es importante, todo lo que expresas, y lo que posteas, para la imagen y la reputación que deseas construir."}]},{"type":"paragraph","content":[{"type":"text","text":"5- Construye relaciones duraderas:","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Relaciones sólidas con tus pares, con tus clientes, con tus admiradores, ellos serán quienes van a promover tus fortalezas y generar el valor a tu marca."}]},{"type":"paragraph","content":[{"type":"text","text":"Acude a eventos de tu sector, practica el "},{"type":"text","text":"networking","marks":[{"type":"bold"}]},{"type":"text","text":", para construir una red de profesionales donde te actualizas constantemente y estas en vidriera."}]},{"type":"paragraph","content":[{"type":"text","text":"Cuando hablamos de construir relaciones, hablamos de superar expectativas, de dejar huellas emocionales."}]},{"type":"paragraph","content":[{"type":"text","text":"El secreto del éxito de una marca personal, para mi está en la sencillez , la coherencia y la magia de dar lo que tienes, con autenticidad, con emociones positivas, con amor, eso asegura que darás dar lo mejor que tienes, es lo que de verdad vale la pena y deja huellas profundas."}]},{"type":"paragraph","content":[{"type":"text","text":"porque TU MARCA ERES TU."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"MARÍA LETICIA CENTURION PLATE"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Asunción – Paraguay"}]},{"type":"paragraph","content":[{"type":"text","text":"Alegre, apasionada, desafiante, con fe y confianza, en mí misma. Viene de una familia que se caracterizó por los valores de amor y solidaridad."}]},{"type":"paragraph","content":[{"type":"text","text":"Productora y conductora del Programa ENTRE NOSOTRAS, un espacio para visibilizar el trabajo de mujeres con su trayectoria."}]},{"type":"paragraph","content":[{"type":"text","text":"Creadora del evento TU MARCA ERES TU, imagen de mujer, y Branding personal."}]},{"type":"paragraph","content":[{"type":"text","text":"Su mayor objetivo es empoderar a las mujeres a través de la educación emocional, y mejorando su autoestima, para que tengan mayor oportunidad de alcanzar sus metas y sueños, transformarse en líderes y puedan aportar al mundo un liderazgo más empático, generando paz e igualdad de condiciones para todos."}]},{"type":"paragraph","content":[{"type":"text","text":"Lic. Marketing y en Administración de empresas., Profesora Universitaria, con diplomado en pedagogía por competencias."}]},{"type":"paragraph","content":[{"type":"text","text":"Presidente de ODM PARAGUAY, CEO E.M. CONSULTORES & ASOCIADOS S.A, embajadora de la Red Global de Mentores. Asesora empresarial. Manager coach., integrante de CAINEM, conferencista internacional"}]},{"type":"paragraph","content":[{"type":"text","text":"Y por sobre todo una mujer que va por más."}]},{"type":"paragraph","content":[{"type":"text","text":"INSTAGRAM","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/leticia_centurion_coach/"}}]},{"type":"text","text":" | "},{"type":"text","text":" LINKEDIN","marks":[{"type":"link","attrs":{"href":"https://www.linkedin.com/in/leticiacenturionplate/"}}]},{"type":"text","text":" | "},{"type":"text","text":"FACEBOOK","marks":[{"type":"link","attrs":{"href":"https://www.facebook.com/leticia.centurionconferencistainter/"}}]}]}]}'::jsonb, '<p>Hace unos años pasé por una experiencia personal que me llevó a conocer y volcarme en el maravilloso mundo de las emociones, conectar conmigo misma, con mi esencia. Lo más importante fue que lo llevé al terreno profesional, uniendo mi preparación profesional y mi experiencia en marketing estratégico, branding, e <strong>INTELIGENCIA EMOCIONAL.</strong></p><p>Actualmente trabajo con emprendedores y profesionales, que buscan posicionarse exitosamente en su campo, llevando un único mensaje. “<strong>Encuentra tu esencia, se autentico/a, y se original, porque TU MARCA ERES TU”.</strong></p><p>Y con el objetivo de llevar ese mensaje a la mayor cantidad de personas, he creado el evento: TU MARCA ERES TU, imagen de mujer, que tiene como propósito empoderar a las mujeres emprendedoras que buscan ser exitosas con sus emprendimientos, aportándoles herramientas esenciales para lograrlo.</p><p>Mi mensaje es:</p><p>Puedes trabajar bastante para crear ese/a profesional de éxito que anhelas ser, estudiando, obteniendo cantidad de títulos, invirtiendo en masterados, pero si no conectas con tu esencia, no conectarás con el mundo que está allí esperando por lo que puedas aportar, entonces será un fracaso. Estamos en un entorno cada día más competitivo, donde es esencial poder diferenciarte, conociéndote y conociendo el mercado, saber lo que esperan y tener claro tu propuesta de valor. Esto te permitirá trabajar estratégicamente para generar esa visibilidad que necesitas y alinear tu imagen con lo que deseas proyectar, porque cuando te recuerden en el ámbito laboral, profesional, o empresarial, tu nombre irá asociado a una experiencia con esa o esas personas y a eso llamamos reputación.</p><p>Mi objetivo con este artículo es <strong>compartir mi experiencia</strong> personal contigo, demostrando que, independientemente del sector en el que te desarrolles, puedes posicionarte como un profesional de éxito al crear una marca personal sólida, coherente, humana, auténtica, creíble y lo más importante, convertirte en un referente en tu sector.</p><p>A continuación, algunos puntos importantes:</p><p><strong>1. Mi súper Marca, YO:</strong></p><p>¿Te has preguntado qué lugar ocupas en la mente de los demás, qué es lo que la gente dice de ti cuando no estás?</p><p>Aunque no lo creas, esa es la forma en que nos posicionamos con nuestra marca personal, cada experiencia con los demás, son huellas que vamos dejando. Como nos recuerdan, como nos ven y que sentimientos asocian a la experiencia de conocerte, es tu reputación, esta se convierte en tu posicionamiento.</p><p>Es por ello por lo que, si deseas tener éxito, debes trabajar, desarrollar el producto más importante que tienes: Tú mismo.</p><p>¿Te has preguntado quién eres, cuáles son tus habilidades, que es lo que te apasiona hacer, cuál es tu talento?</p><p>Para responder estas preguntas es ideal que puedas realizar tu FODA (fortalezas, oportunidades, debilidades y amenazas), describe cuáles son tus fortalezas y tus debilidades, y de qué manera son percibidos por tu entorno, para saber si estas alineado con tus objetivos.</p><p>Para llegar a ese punto, es más que importante tener un nivel de autoconocimiento elevado, entender el concepto que tienes de ti mismo, tu nivel de autoestima, y la forma en que te comparas con tu entorno, porque es la forma en que te proyectas al mundo y te perciben emocionalmente los demás.</p><p>Tus fortalezas son el trampolín que necesitas para subir a la cima de tus sueños, tus debilidades, las que pueden jugar en contra de tu posicionamiento, pero las puedes superar.</p><img loading="lazy" src="/blog/tu-marca-eres-tu/nota-imagen-para-banner-principal.jpg"/><p>Es importante poder obtener una medición a través de un estudio para evaluar tu posicionamiento actual y con base en esto trabajar en estrategias que te permitan alinear tu imagen y tu reputación, con tus objetivos.</p><p>El secreto está en identificar tu esencia, reconocer tus fortalezas y potenciarlas. Desarrollar un producto de calidad, único y duradero, TU SÚPER marca: YO</p><p><strong>2. Tu imagen externa:</strong></p><p>Hay un dicho que dice, no solo debo ser, si no parecer, al crear visibilidad, estas creando el primer impacto, y los juicios de valor, es por ello que tu imagen externa debe ser coherente con el mensaje que deseas transmitir, como defines tu estilo, los colores, hablan de ti. Necesitas trabajar en elegir un estilo que te permita transmitir a nivel profesional todos los matices de tu personalidad y así generar el valor a tu marca.</p><p>Esto abarca las fotos de tu web, de tus redes sociales, que reflejan cómo te vistes, como te presentas a un evento, tu vestuario elegido, para grabar tus vídeos, en tus visitas a clientes, cuál es tu vestuario al momento de impartir una ponencia</p><p>El mejor talento eres tú, pero exprésalo con actitud y apariencia.</p><p><strong>3. Crea tu ventaja competitiva:</strong></p><p>Cuando puedes definir tu valor, puedes trabajar en tu ventaja competitiva, que es aquello que te hace único e irrepetible y que debe ser recibido por tu entorno con un valor positivo, auténtico y único. Es de la forma en que el mercado te va a reconocer, pero que esto sea un éxito depende de la estrategia de comunicación que realices.</p><p>Recuerda que quien tiene magia no necesita trucos</p><img loading="lazy" src="/blog/tu-marca-eres-tu/imagen-adicional-para-la-nota-.jpg"/><p><strong>4. Estrategia de comunicación y promoción:</strong></p><p>Cuando ya tienes claro tu objetivo, podrás definir tu imagen, tu leguaje y que redes son útiles para poder generar esa visibilidad que necesitas.</p><p>Recuerda que hoy en día, a través de las redes, llegas a un público mucho más grande y de manera directa, que otros medios de comunicación, por lo que es importante, todo lo que expresas, y lo que posteas, para la imagen y la reputación que deseas construir.</p><p><strong>5- Construye relaciones duraderas:</strong></p><p>Relaciones sólidas con tus pares, con tus clientes, con tus admiradores, ellos serán quienes van a promover tus fortalezas y generar el valor a tu marca.</p><p>Acude a eventos de tu sector, practica el <strong>networking</strong>, para construir una red de profesionales donde te actualizas constantemente y estas en vidriera.</p><p>Cuando hablamos de construir relaciones, hablamos de superar expectativas, de dejar huellas emocionales.</p><p>El secreto del éxito de una marca personal, para mi está en la sencillez , la coherencia y la magia de dar lo que tienes, con autenticidad, con emociones positivas, con amor, eso asegura que darás dar lo mejor que tienes, es lo que de verdad vale la pena y deja huellas profundas.</p><p>porque TU MARCA ERES TU.</p><h2>MARÍA LETICIA CENTURION PLATE</h2><h3>Asunción – Paraguay</h3><p>Alegre, apasionada, desafiante, con fe y confianza, en mí misma. Viene de una familia que se caracterizó por los valores de amor y solidaridad.</p><p>Productora y conductora del Programa ENTRE NOSOTRAS, un espacio para visibilizar el trabajo de mujeres con su trayectoria.</p><p>Creadora del evento TU MARCA ERES TU, imagen de mujer, y Branding personal.</p><p>Su mayor objetivo es empoderar a las mujeres a través de la educación emocional, y mejorando su autoestima, para que tengan mayor oportunidad de alcanzar sus metas y sueños, transformarse en líderes y puedan aportar al mundo un liderazgo más empático, generando paz e igualdad de condiciones para todos.</p><p>Lic. Marketing y en Administración de empresas., Profesora Universitaria, con diplomado en pedagogía por competencias.</p><p>Presidente de ODM PARAGUAY, CEO E.M. CONSULTORES &amp; ASOCIADOS S.A, embajadora de la Red Global de Mentores. Asesora empresarial. Manager coach., integrante de CAINEM, conferencista internacional</p><p>Y por sobre todo una mujer que va por más.</p><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/leticia_centurion_coach/">INSTAGRAM</a> | <a target="_blank" rel="noopener noreferrer" href="https://www.linkedin.com/in/leticiacenturionplate/"> LINKEDIN</a> | <a target="_blank" rel="noopener noreferrer" href="https://www.facebook.com/leticia.centurionconferencistainter/">FACEBOOK</a></p>', 6, '/blog/tu-marca-eres-tu/tu-marca-eres-tu.jpg', 'Tu marca eres tu', 'Mujeres x Más', '2022-05-04T18:16:18-03:00'::timestamptz),
  ('Día internacional de lucha contra el Maltrato Infantil', 'dia-internacional-de-lucha-contra-el-maltrato-infantil', 'Según datos del Ministerio de Justicia y Derechos Humanos de la Nación, en 2020 se registró un aumento del 20% de los llamados a la línea 137 por violencias intrafamiliares y/o sexuales respecto del año anterior…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Números que castigan el alma – VIDAS MALTRATADAS","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Según datos del Ministerio de Justicia y Derechos Humanos de la Nación, en 2020 se registró un aumento del 20% de los llamados a la línea 137 por violencias intrafamiliares y/o sexuales respecto del año anterior. Según los datos publicados, la violencia familiar aumentó un 28% y los abusos sexuales, un 13%."}]},{"type":"paragraph","content":[{"type":"text","text":"Las estadísticas indican que el 80% de los casos de maltrato y abuso hacia niñas, niños y adolescentes (NNyA) se llevan a cabo en contextos intrafamiliares o ámbitos de cercanía."}]},{"type":"paragraph","content":[{"type":"text","text":"En nuestro país 7 de cada 10 niños reciben algún tipo de maltrato. De acuerdo a datos aportados por UNICEF, el 54,4% de los chicos y chicas son víctimas de castigo físico, un 62,5% de agresión verbal y un 72,9% de cualquier otra práctica de disciplina infantil violenta (UNICEF ARG)"}]},{"type":"paragraph","content":[{"type":"text","text":"¿Qué se considera como maltrato infantil?"}]},{"type":"paragraph","content":[{"type":"text","text":"El maltrato infantil se define como los abusos y la desatención de que son objeto los menores de 18 años, e incluye todos los tipos de maltrato físico o psicológico, abuso sexual, desatención, negligencia y explotación comercial o de otro tipo que causen o puedan causar un daño a la salud, desarrollo o dignidad del individuo."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Cuáles son los tipos de maltrato?"}]},{"type":"paragraph","content":[{"type":"text","text":"El maltrato físico, el psicológico y los abusos sexuales son los tipos de maltratos más conocidos. El maltrato físico ocurre cuando alguien lesiona el cuerpo de otra persona."}]},{"type":"paragraph","content":[{"type":"text","text":"Trabajemos para que las únicas lágrimas que conozcan los niños SEAN DE ALEGRIA","marks":[{"type":"bold"}]}]},{"type":"image","attrs":{"src":"/blog/dia-internacional-de-lucha-contra-el-maltrato-infantil/dia-internacional-de-lucha-contra-el-maltrato-infantil-1-1.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Links de interés","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"https://www.argentina.gob.ar/noticias/el-ministerio-de-justicia-y-unicef-presentan-un-informe-sobre-las-violencias-que-padecen","marks":[{"type":"link","attrs":{"href":"https://www.argentina.gob.ar/noticias/el-ministerio-de-justicia-y-unicef-presentan-un-informe-sobre-las-violencias-que-padecen"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"https://www.unicef.org/","marks":[{"type":"link","attrs":{"href":"https://www.unicef.org/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"mujeres x mas","marks":[{"type":"link","attrs":{"href":"/"}}]}]}]}'::jsonb, '<p><strong>Números que castigan el alma – VIDAS MALTRATADAS</strong></p><p>Según datos del Ministerio de Justicia y Derechos Humanos de la Nación, en 2020 se registró un aumento del 20% de los llamados a la línea 137 por violencias intrafamiliares y/o sexuales respecto del año anterior. Según los datos publicados, la violencia familiar aumentó un 28% y los abusos sexuales, un 13%.</p><p>Las estadísticas indican que el 80% de los casos de maltrato y abuso hacia niñas, niños y adolescentes (NNyA) se llevan a cabo en contextos intrafamiliares o ámbitos de cercanía.</p><p>En nuestro país 7 de cada 10 niños reciben algún tipo de maltrato. De acuerdo a datos aportados por UNICEF, el 54,4% de los chicos y chicas son víctimas de castigo físico, un 62,5% de agresión verbal y un 72,9% de cualquier otra práctica de disciplina infantil violenta (UNICEF ARG)</p><p>¿Qué se considera como maltrato infantil?</p><p>El maltrato infantil se define como los abusos y la desatención de que son objeto los menores de 18 años, e incluye todos los tipos de maltrato físico o psicológico, abuso sexual, desatención, negligencia y explotación comercial o de otro tipo que causen o puedan causar un daño a la salud, desarrollo o dignidad del individuo.</p><p>¿Cuáles son los tipos de maltrato?</p><p>El maltrato físico, el psicológico y los abusos sexuales son los tipos de maltratos más conocidos. El maltrato físico ocurre cuando alguien lesiona el cuerpo de otra persona.</p><p><strong>Trabajemos para que las únicas lágrimas que conozcan los niños SEAN DE ALEGRIA</strong></p><img loading="lazy" src="/blog/dia-internacional-de-lucha-contra-el-maltrato-infantil/dia-internacional-de-lucha-contra-el-maltrato-infantil-1-1.jpg"/><p><strong>Links de interés</strong></p><p><a target="_blank" rel="noopener noreferrer" href="https://www.argentina.gob.ar/noticias/el-ministerio-de-justicia-y-unicef-presentan-un-informe-sobre-las-violencias-que-padecen">https://www.argentina.gob.ar/noticias/el-ministerio-de-justicia-y-unicef-presentan-un-informe-sobre-las-violencias-que-padecen</a></p><p><a target="_blank" rel="noopener noreferrer" href="https://www.unicef.org/">https://www.unicef.org/</a></p><p><a href="/">mujeres x mas</a></p>', 1, '/blog/dia-internacional-de-lucha-contra-el-maltrato-infantil/dia-internacional-de-lucha-contra-el-maltrato-infantil-1.jpg', 'Día internacional de lucha contra el Maltrato Infantil', 'Mujeres x Más', '2022-04-20T20:19:11-03:00'::timestamptz),
  ('Emprendimiento femenino en Latinoamérica: un panorama lleno de resiliencia', 'emprendimiento-un-panorama-lleno-de-resiliencia', 'Una característica común de las mujeres emprendedoras es la resiliencia, la capacidad de adaptarse a las situaciones y seguir adelante a pesar de los obstáculos', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Una característica común de las "},{"type":"text","text":"mujeres emprendedoras","marks":[{"type":"bold"}]},{"type":"text","text":" es la resiliencia, la capacidad de adaptarse a las situaciones y seguir adelante a pesar de los obstáculos"}]},{"type":"paragraph","content":[{"type":"text","text":"¿El empoderamiento femenino está de moda? Este término se escucha cada vez más en distintos foros, pero lo cierto es que por más "},{"type":"text","text":"empoderadas","marks":[{"type":"bold"}]},{"type":"text","text":" que estemos, la brecha de género en el mundo del emprendimiento es una realidad con la que todas las mujeres emprendedoras debemos seguir lidiando en nuestro día a día."}]},{"type":"paragraph","content":[{"type":"text","text":"Latinoamérica ha sido identificada como la región con "},{"type":"text","text":"mayor porcentaje de emprendimiento","marks":[{"type":"bold"}]},{"type":"text","text":" femenino en el mundo, principalmente con participación de mujeres de entre 45 y 64 años, según el informe del Global Entrepreneurship Monitor (GEM). Según dicho reporte, los 10 países con mayor porcentaje de mujeres emprendedoras en el mundo son Angola, Chile, Colombia, Brasil, Canadá, Estados Unidos, India, Argentina, España y Francia. Sin embargo, en todas las regiones del planeta, excepto Norteamérica, "},{"type":"text","text":"el porcentaje de mujeres que acceden a servicios financieros al iniciar su negocio es notablemente menor que el de los hombres.","marks":[{"type":"bold"}]}]},{"type":"image","attrs":{"src":"/blog/emprendimiento-un-panorama-lleno-de-resiliencia/emprendimiento-femenino-en-latinoamerica-2.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"A pesar de la dificultad que actualmente enfrentan para acceder al financiamiento formal, la proporción de unicornios (empresas privadas valoradas en más de USD 1000 millones) liderados por mujeres, se ha duplicado en los últimos 5 años. Actualmente, 21% de los unicornios en el mundo son liderados por mujeres."}]},{"type":"paragraph","content":[{"type":"text","text":"Entonces, ¿qué características de las mujeres hacen que sigan sacando adelante a sus emprendimientos contra todo pronóstico? En el libro “Emprendimiento y Liderazgo Femenino en el Perú”, 13 mujeres emprendedoras cuentan la historia de sus emprendimientos, así como todos los obstáculos que tuvieron que superar para triunfar en el mundo de los negocios. "},{"type":"text","text":"Un común denominador en la experiencia de cada una de estas mujeres es la resiliencia","marks":[{"type":"bold"}]},{"type":"text","text":". Como emprendedoras, han tenido que perseverar en su misión, y aprender a adaptarse a cada situación, para poder superar las dificultades y seguir adelante."}]},{"type":"paragraph","content":[{"type":"text","text":"Personalmente, empecé a emprender a los 21 años, y ya llevo 10 años en este hermoso y retador camino. Mi último emprendimiento, "},{"type":"text","text":"Musiclink,","marks":[{"type":"bold"}]},{"type":"text","text":" se ha convertido en "},{"type":"text","text":"el primer marketplace online para músicos independientes en Perú","marks":[{"type":"bold"}]},{"type":"text","text":", y pronto esperamos iniciar nuestra expansión hacia el resto de Latinoamérica. Mi socio y yo iniciamos este gran proyecto en el 2018 y, hasta el momento, hemos realizado más de 180 eventos con más de 200 músicos de diversos géneros."}]},{"type":"image","attrs":{"src":"/blog/emprendimiento-un-panorama-lleno-de-resiliencia/emprendimiento-femenino-en-latinoamerica.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"En el camino, hemos tenido que vencer muchos obstáculos. Uno de ellos, tan impactante como inesperado, fue la pandemia, ante la cual debimos adaptarnos, convirtiéndonos en "},{"type":"text","text":"pioneros en la organización de eventos online","marks":[{"type":"bold"}]},{"type":"text","text":". Organizamos el "},{"type":"text","text":"primer festival online","marks":[{"type":"bold"}]},{"type":"text","text":" de talento independiente en Perú, Musiclink Fest, el cual tuvo tres ediciones, agrupando a un total de 30 talentosos artistas. De esta manera, convertimos la adversidad en una oportunidad de negocio. Actualmente, ya nos encontramos en un período de reactivación presencial, retomando eventos corporativos y privados."}]},{"type":"paragraph","content":[{"type":"text","text":"El panorama para la mujer emprendedora en Latinoamérica sigue siendo retador, pero cada vez se está avanzando más en torno a cerrar la brecha de género actual. En este camino, "},{"type":"text","text":"la sororidad es clave","marks":[{"type":"bold"}]},{"type":"text","text":", por lo que me parece genial que existan diversas comunidades de "},{"type":"text","text":"mujeres emprendedoras apoyándose entre sí para triunfar en sus negocios","marks":[{"type":"bold"}]},{"type":"text","text":". Yo misma pertenezco a varias de estas comunidades, como WeXChange o la red de mujeres empresarias de la OIT, y las invito a buscarlas y formar parte. Recuerden que juntas somos más fuertes."}]},{"type":"image","attrs":{"src":"/blog/emprendimiento-un-panorama-lleno-de-resiliencia/andrea-lizarraga.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Sobre la autora:","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Andrea Lizárraga es CEO & CoFundadora de Musiclink, la primera plataforma de booking online de músicos en Perú, ganadora de Startup Perú 2019. Apasionada de la música y los negocios. Dejó la vida corporativa después de 9 años de experiencia en áreas comerciales de empresas transnacionales para dedicarse al emprendimiento. Actualmente, también es Directora de Másters para IE Business School (Madrid), escuela top de negocios en donde se graduó con honores del International MBA, reconocido como el mejor MBA en emprendimiento a nivel mundial. Recientemente, Andrea ha sido co autora del libro libro “Emprendimiento y Liderazgo Femenino en el Perú”."}]},{"type":"paragraph","content":[{"type":"text","text":"Linkedin","marks":[{"type":"link","attrs":{"href":"https://www.linkedin.com/in/andrealizarragamichelini/"}}]},{"type":"text","text":" | "},{"type":"text","text":"Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/andreliz1290/"}}]},{"type":"text","text":" | "},{"type":"text","text":"Facebook","marks":[{"type":"link","attrs":{"href":"https://www.facebook.com/andrea.l.michelini/"}}]}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"Si quieres saber más sobre Musiclink, puedes seguirlos en las redes sociales:"}]},{"type":"paragraph","content":[{"type":"text","text":"Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/musiclinkperu/"}}]},{"type":"text","text":" | "},{"type":"text","text":"Facebook ","marks":[{"type":"link","attrs":{"href":"https://www.facebook.com/MusicLinkPeru/"}}]},{"type":"text","text":"| "},{"type":"text","text":"Linkedin","marks":[{"type":"link","attrs":{"href":"//www.linkedin.com/company/musiclinkperu/"}}]}]}]}'::jsonb, '<p>Una característica común de las <strong>mujeres emprendedoras</strong> es la resiliencia, la capacidad de adaptarse a las situaciones y seguir adelante a pesar de los obstáculos</p><p>¿El empoderamiento femenino está de moda? Este término se escucha cada vez más en distintos foros, pero lo cierto es que por más <strong>empoderadas</strong> que estemos, la brecha de género en el mundo del emprendimiento es una realidad con la que todas las mujeres emprendedoras debemos seguir lidiando en nuestro día a día.</p><p>Latinoamérica ha sido identificada como la región con <strong>mayor porcentaje de emprendimiento</strong> femenino en el mundo, principalmente con participación de mujeres de entre 45 y 64 años, según el informe del Global Entrepreneurship Monitor (GEM). Según dicho reporte, los 10 países con mayor porcentaje de mujeres emprendedoras en el mundo son Angola, Chile, Colombia, Brasil, Canadá, Estados Unidos, India, Argentina, España y Francia. Sin embargo, en todas las regiones del planeta, excepto Norteamérica, <strong>el porcentaje de mujeres que acceden a servicios financieros al iniciar su negocio es notablemente menor que el de los hombres.</strong></p><img loading="lazy" src="/blog/emprendimiento-un-panorama-lleno-de-resiliencia/emprendimiento-femenino-en-latinoamerica-2.jpg"/><p>A pesar de la dificultad que actualmente enfrentan para acceder al financiamiento formal, la proporción de unicornios (empresas privadas valoradas en más de USD 1000 millones) liderados por mujeres, se ha duplicado en los últimos 5 años. Actualmente, 21% de los unicornios en el mundo son liderados por mujeres.</p><p>Entonces, ¿qué características de las mujeres hacen que sigan sacando adelante a sus emprendimientos contra todo pronóstico? En el libro “Emprendimiento y Liderazgo Femenino en el Perú”, 13 mujeres emprendedoras cuentan la historia de sus emprendimientos, así como todos los obstáculos que tuvieron que superar para triunfar en el mundo de los negocios. <strong>Un común denominador en la experiencia de cada una de estas mujeres es la resiliencia</strong>. Como emprendedoras, han tenido que perseverar en su misión, y aprender a adaptarse a cada situación, para poder superar las dificultades y seguir adelante.</p><p>Personalmente, empecé a emprender a los 21 años, y ya llevo 10 años en este hermoso y retador camino. Mi último emprendimiento, <strong>Musiclink,</strong> se ha convertido en <strong>el primer marketplace online para músicos independientes en Perú</strong>, y pronto esperamos iniciar nuestra expansión hacia el resto de Latinoamérica. Mi socio y yo iniciamos este gran proyecto en el 2018 y, hasta el momento, hemos realizado más de 180 eventos con más de 200 músicos de diversos géneros.</p><img loading="lazy" src="/blog/emprendimiento-un-panorama-lleno-de-resiliencia/emprendimiento-femenino-en-latinoamerica.jpg"/><p>En el camino, hemos tenido que vencer muchos obstáculos. Uno de ellos, tan impactante como inesperado, fue la pandemia, ante la cual debimos adaptarnos, convirtiéndonos en <strong>pioneros en la organización de eventos online</strong>. Organizamos el <strong>primer festival online</strong> de talento independiente en Perú, Musiclink Fest, el cual tuvo tres ediciones, agrupando a un total de 30 talentosos artistas. De esta manera, convertimos la adversidad en una oportunidad de negocio. Actualmente, ya nos encontramos en un período de reactivación presencial, retomando eventos corporativos y privados.</p><p>El panorama para la mujer emprendedora en Latinoamérica sigue siendo retador, pero cada vez se está avanzando más en torno a cerrar la brecha de género actual. En este camino, <strong>la sororidad es clave</strong>, por lo que me parece genial que existan diversas comunidades de <strong>mujeres emprendedoras apoyándose entre sí para triunfar en sus negocios</strong>. Yo misma pertenezco a varias de estas comunidades, como WeXChange o la red de mujeres empresarias de la OIT, y las invito a buscarlas y formar parte. Recuerden que juntas somos más fuertes.</p><img loading="lazy" src="/blog/emprendimiento-un-panorama-lleno-de-resiliencia/andrea-lizarraga.jpeg"/><p><strong>Sobre la autora:</strong></p><p>Andrea Lizárraga es CEO &amp; CoFundadora de Musiclink, la primera plataforma de booking online de músicos en Perú, ganadora de Startup Perú 2019. Apasionada de la música y los negocios. Dejó la vida corporativa después de 9 años de experiencia en áreas comerciales de empresas transnacionales para dedicarse al emprendimiento. Actualmente, también es Directora de Másters para IE Business School (Madrid), escuela top de negocios en donde se graduó con honores del International MBA, reconocido como el mejor MBA en emprendimiento a nivel mundial. Recientemente, Andrea ha sido co autora del libro libro “Emprendimiento y Liderazgo Femenino en el Perú”.</p><p><a target="_blank" rel="noopener noreferrer" href="https://www.linkedin.com/in/andrealizarragamichelini/">Linkedin</a> | <a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/andreliz1290/">Instagram</a> | <a target="_blank" rel="noopener noreferrer" href="https://www.facebook.com/andrea.l.michelini/">Facebook</a></p><hr/><p>Si quieres saber más sobre Musiclink, puedes seguirlos en las redes sociales:</p><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/musiclinkperu/">Instagram</a> | <a target="_blank" rel="noopener noreferrer" href="https://www.facebook.com/MusicLinkPeru/">Facebook </a>| <a target="_blank" rel="noopener noreferrer" href="//www.linkedin.com/company/musiclinkperu/">Linkedin</a></p>', 3, '/blog/emprendimiento-un-panorama-lleno-de-resiliencia/emprendimiento-femenino-en-latinoamerica-3.jpg', 'Emprendimiento femenino en Latinoamérica: un panorama lleno de resiliencia', 'Mujeres x Más', '2022-03-09T15:18:10-03:00'::timestamptz),
  ('Fomentar la participación de las mujeres y niñas en la ciencia', 'fomentar-la-participacion-de-las-mujeres-y-ninas-en-la-ciencia', 'El 11 de febrero se celebra el Día Internacional de las Mujeres y las Niñas en la Ciencia, un día que nos alienta a trabajar para mejorar el acceso a la educación tecnológica y científica y fomentar la participación…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El 11 de febrero se celebra el "},{"type":"text","text":"Día Internacional de las Mujeres y las Niñas en la Ciencia","marks":[{"type":"link","attrs":{"href":"http://www.un.org/es/events/women-and-girls-in-science-day/background.shtml"}}]},{"type":"text","text":", un día que nos alienta a trabajar para mejorar el acceso a la educación tecnológica y científica y fomentar la participación de las mujeres y niñas en la ciencia."}]},{"type":"paragraph","content":[{"type":"text","text":"A pesar del progreso en la apertura de nuevas oportunidades, las mujeres y las niñas continúan estando subrepresentadas como usuarias y líderes en los campos de la ciencia, la tecnología, la ingeniería y las matemáticas (STEM)."}]},{"type":"paragraph","content":[{"type":"text","text":"Las estimaciones de la UNESCO sugieren que sólo alrededor del 35% de las personas que se matriculan en los sectores relacionados a las STEM son mujeres. La ciencia y la igualdad entre sexos también es crucial para conseguir los "},{"type":"text","text":"Objetivos de Desarrollo Sostenible","marks":[{"type":"link","attrs":{"href":"http://www.un.org/sustainabledevelopment/es/objetivos-de-desarrollo-sostenible/"}}]},{"type":"text","text":" de la ONU, y alcanzar la promesa de la "},{"type":"text","text":"Agenda 2030","marks":[{"type":"link","attrs":{"href":"http://www.un.org/sustainabledevelopment/es/la-agenda-de-desarrollo-sostenible/"}}]},{"type":"text","text":" para el desarrollo sostenible de “no dejar a nadie atrás”."}]},{"type":"image","attrs":{"src":"/blog/fomentar-la-participacion-de-las-mujeres-y-ninas-en-la-ciencia/thisisengineering-raeng-8ys04veb1tq-unsplash-1.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Sin embargo, las mujeres siguen estando insuficientemente representadas en la ciencia y la ingeniería, lo que priva a la humanidad de un catalizador vital para dar forma a un futuro mejor para las generaciones actuales y futuras."}]},{"type":"paragraph","content":[{"type":"text","text":"El Día Internacional de las Mujeres y las Niñas en la Ciencia debería celebrar sus logros y ser el desencadenante para que todas las naciones e instituciones encuentren formas de abrir realmente las puertas a este vasto conjunto de talentos. Debería comenzar con más aliento, apoyo y oportunidades en la educación inicial para que las niñas se involucren en los campos científicos y tecnológicos que definirán nuestro futuro."}]},{"type":"paragraph","content":[{"type":"text","text":"La participación plena y equitativa en la ciencia por parte de las mujeres y las niñas puede desempeñar un papel vital para garantizar la diversidad en la investigación, ampliar el grupo de investigadores talentosos y aportar nuevas perspectivas, pero sin embargo no es tenido en cuenta al momento del desarrollo e implementación de políticas que efectivamente trabajen en estos obstáculos."}]},{"type":"paragraph","content":[{"type":"text","text":"Según "},{"type":"text","text":"investigaciones","marks":[{"type":"link","attrs":{"href":"https://chicasentecnologia.org/investigacion"}}]},{"type":"text","text":" en Argentina: las carreras de Ciencia, Tecnología, Informática y Matemática cuentan solo con un 33% de inscripciones de mujeres y en carreras vinculadas a programación, el número se reduce a 16%. Si bien los estereotipos de "},{"type":"text","text":"género","marks":[{"type":"link","attrs":{"href":"/blog/igualdad-de-genero"}}]},{"type":"text","text":" se construyen a temprana edad, el interés por desarrollarse en estos ámbitos termina de definirse en la adolescencia."}]},{"type":"paragraph","content":[{"type":"text","text":"Los cambios provocados por las TIC y los beneficios se encuentran atravesados por las desigualdades existentes entre mujeres y varones, por lo que es necesario trabajar continuamente en la apertura de nuevos horizontes donde tengan lugar las expectativas de las mujeres en el mundo de las "},{"type":"text","text":"nuevas tecnologías","marks":[{"type":"link","attrs":{"href":"/blog/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Para integrar las TIC en la sociedad de forma igualitaria es necesario promover el verdadero protagonismo de estos grupos y para ello es imprescindible:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fomentar el estudio de carreras universitarias tecnológicas."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Generar aumento de posiciones en puestos de dirección en empresas tecnológicas."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Visibilizar a más mujeres y en el sector para que las infancias tengan a quien ver y admirar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Promover el uso y acceso a las herramientas informáticas fomentando su capacitación y formación en competencias digitales."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Un análisis del fenómeno de las nuevas tecnologías debe tener en cuenta estos factores, ya que son determinantes para poder entender la situación real del acceso de las mujeres y para poder trabajar en aquellas acciones positivas necesarias para disponibilizarán estas tecnologías a toda la población."}]},{"type":"paragraph","content":[{"type":"text","text":"Asesoramiento: Lic. Tamara López, Licenciada en Psicología.","marks":[{"type":"link","attrs":{"href":"/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Insertar este video en la nota:","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"¿Por qué apoyar a mujeres y niñas en ciencia y tecnología?"}]},{"type":"paragraph","content":[{"type":"text","text":"¿Por qué apoyar a mujeres y niñas en ciencia y tecnología?","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=OphYgOrdNTo&feature=youtu.be"}}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Mujeres pioneras en la ciencia"}]},{"type":"paragraph","content":[{"type":"text","text":"Las mujeres a la vanguardia de los descubrimientos científicos","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=yHnzpMAahFs&t=11s"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Otras paginas "},{"type":"text","text":"https://www.un.org/es/observances/women-and-girls-in-science-day","marks":[{"type":"link","attrs":{"href":"https://www.un.org/es/observances/women-and-girls-in-science-day"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"https://es.unesco.org/commemorations/womenandgirlinscienceday","marks":[{"type":"link","attrs":{"href":"https://es.unesco.org/commemorations/womenandgirlinscienceday"}}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Mujeres pioneras en la ciencia"}]},{"type":"paragraph","content":[{"type":"text","text":"Ver el video en YouTube","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=yHnzpMAahFs"}}]}]}]}'::jsonb, '<p>El 11 de febrero se celebra el <a target="_blank" rel="noopener noreferrer" href="http://www.un.org/es/events/women-and-girls-in-science-day/background.shtml">Día Internacional de las Mujeres y las Niñas en la Ciencia</a>, un día que nos alienta a trabajar para mejorar el acceso a la educación tecnológica y científica y fomentar la participación de las mujeres y niñas en la ciencia.</p><p>A pesar del progreso en la apertura de nuevas oportunidades, las mujeres y las niñas continúan estando subrepresentadas como usuarias y líderes en los campos de la ciencia, la tecnología, la ingeniería y las matemáticas (STEM).</p><p>Las estimaciones de la UNESCO sugieren que sólo alrededor del 35% de las personas que se matriculan en los sectores relacionados a las STEM son mujeres. La ciencia y la igualdad entre sexos también es crucial para conseguir los <a target="_blank" rel="noopener noreferrer" href="http://www.un.org/sustainabledevelopment/es/objetivos-de-desarrollo-sostenible/">Objetivos de Desarrollo Sostenible</a> de la ONU, y alcanzar la promesa de la <a target="_blank" rel="noopener noreferrer" href="http://www.un.org/sustainabledevelopment/es/la-agenda-de-desarrollo-sostenible/">Agenda 2030</a> para el desarrollo sostenible de “no dejar a nadie atrás”.</p><img loading="lazy" src="/blog/fomentar-la-participacion-de-las-mujeres-y-ninas-en-la-ciencia/thisisengineering-raeng-8ys04veb1tq-unsplash-1.jpg"/><p>Sin embargo, las mujeres siguen estando insuficientemente representadas en la ciencia y la ingeniería, lo que priva a la humanidad de un catalizador vital para dar forma a un futuro mejor para las generaciones actuales y futuras.</p><p>El Día Internacional de las Mujeres y las Niñas en la Ciencia debería celebrar sus logros y ser el desencadenante para que todas las naciones e instituciones encuentren formas de abrir realmente las puertas a este vasto conjunto de talentos. Debería comenzar con más aliento, apoyo y oportunidades en la educación inicial para que las niñas se involucren en los campos científicos y tecnológicos que definirán nuestro futuro.</p><p>La participación plena y equitativa en la ciencia por parte de las mujeres y las niñas puede desempeñar un papel vital para garantizar la diversidad en la investigación, ampliar el grupo de investigadores talentosos y aportar nuevas perspectivas, pero sin embargo no es tenido en cuenta al momento del desarrollo e implementación de políticas que efectivamente trabajen en estos obstáculos.</p><p>Según <a target="_blank" rel="noopener noreferrer" href="https://chicasentecnologia.org/investigacion">investigaciones</a> en Argentina: las carreras de Ciencia, Tecnología, Informática y Matemática cuentan solo con un 33% de inscripciones de mujeres y en carreras vinculadas a programación, el número se reduce a 16%. Si bien los estereotipos de <a href="/blog/igualdad-de-genero">género</a> se construyen a temprana edad, el interés por desarrollarse en estos ámbitos termina de definirse en la adolescencia.</p><p>Los cambios provocados por las TIC y los beneficios se encuentran atravesados por las desigualdades existentes entre mujeres y varones, por lo que es necesario trabajar continuamente en la apertura de nuevos horizontes donde tengan lugar las expectativas de las mujeres en el mundo de las <a href="/blog/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider">nuevas tecnologías</a>.</p><p>Para integrar las TIC en la sociedad de forma igualitaria es necesario promover el verdadero protagonismo de estos grupos y para ello es imprescindible:</p><ul><li><p>Fomentar el estudio de carreras universitarias tecnológicas.</p></li><li><p>Generar aumento de posiciones en puestos de dirección en empresas tecnológicas.</p></li><li><p>Visibilizar a más mujeres y en el sector para que las infancias tengan a quien ver y admirar.</p></li><li><p>Promover el uso y acceso a las herramientas informáticas fomentando su capacitación y formación en competencias digitales.</p></li></ul><p>Un análisis del fenómeno de las nuevas tecnologías debe tener en cuenta estos factores, ya que son determinantes para poder entender la situación real del acceso de las mujeres y para poder trabajar en aquellas acciones positivas necesarias para disponibilizarán estas tecnologías a toda la población.</p><p><a href="/">Asesoramiento: Lic. Tamara López, Licenciada en Psicología.</a></p><p><strong>Insertar este video en la nota:</strong></p><h3>¿Por qué apoyar a mujeres y niñas en ciencia y tecnología?</h3><p><a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v=OphYgOrdNTo&amp;feature=youtu.be">¿Por qué apoyar a mujeres y niñas en ciencia y tecnología?</a></p><h3>Mujeres pioneras en la ciencia</h3><p><a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v=yHnzpMAahFs&amp;t=11s">Las mujeres a la vanguardia de los descubrimientos científicos</a></p><p>Otras paginas <a target="_blank" rel="noopener noreferrer" href="https://www.un.org/es/observances/women-and-girls-in-science-day">https://www.un.org/es/observances/women-and-girls-in-science-day</a></p><p><a target="_blank" rel="noopener noreferrer" href="https://es.unesco.org/commemorations/womenandgirlinscienceday">https://es.unesco.org/commemorations/womenandgirlinscienceday</a></p><h3>Mujeres pioneras en la ciencia</h3><p><a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v=yHnzpMAahFs">Ver el video en YouTube</a></p>', 3, '/blog/fomentar-la-participacion-de-las-mujeres-y-ninas-en-la-ciencia/cdc-p33dqvxhwvs-unsplash.jpg', 'Fomentar la participación de las mujeres y niñas en la ciencia', 'Mujeres x Más', '2022-02-07T08:01:00-03:00'::timestamptz),
  ('Innovación digital en qué consiste y cómo aplica', 'innovacion-digital-en-que-consiste-y-como-aplica', 'Cuando hablamos de innovación digital nos referimos a un proceso de cambio del modelo de negocio o propuesta de valor a través de herramientas digitales. En esta nueva era tecnológica por la que estamos atravesando…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuando hablamos de "},{"type":"text","text":"innovación digital ","marks":[{"type":"bold"}]},{"type":"text","text":"nos referimos a un proceso de cambio del modelo de negocio o propuesta de valor a través de herramientas digitales. En esta nueva era tecnológica por la que estamos atravesando, el diseño de nuestro modelo está determinado y estrechamente relacionado con las tecnologías de la información y la comunicación."}]},{"type":"paragraph","content":[{"type":"text","text":"Al encarar un proyecto de transformación, el mismo debe responder a necesidades claramente identificadas y con impacto en la propuesta de valor de nuestro negocio y/o CIA , ya sea de cara a nuestro cliente interno o externo."}]},{"type":"paragraph","content":[{"type":"text","text":"No se trata de un mero cambio de forma sino de un análisis real del “is” y “"},{"type":"text","text":"should map","marks":[{"type":"link","attrs":{"href":"https://context.reverso.net/translation/english-spanish/map+should"}}]},{"type":"text","text":"” con enfoque estratégico; donde lo digital es el elemento táctico."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Innovación digital"}]},{"type":"paragraph","content":[{"type":"text","text":"La innovación digital también es entendida como un proceso que tiene que ver con ideas disruptivas, como el manejo acertado y eficaz de las tecnologías de las que disponemos en la actualidad y dentro del plano empresarial."}]},{"type":"paragraph","content":[{"type":"text","text":"TRANSFORMAR IMPLICA REPENSAR , RE- CREAR, REDEFINIR ROLES Y TAREAS, ASI COMO LOS CANALES QUE SE EMPLEAN.","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Innovación digital en que consiste"}]},{"type":"image","attrs":{"src":"/blog/innovacion-digital-en-que-consiste-y-como-aplica/innovacion-digital-en-que-consiste-y-como-aplica-1.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Digitalizar un producto o servicio consiste en reinventar el factor tradicional, a través de la tecnología. Se trata de implementar nuevas herramientas y mejorar la eficiencia a la hora de hacer llegar la propuesta de valor al cliente. Este proceso puede llevarte a un nuevo nivel de exigencia en la gestión de una organización, planteándote algunos retos que no tenías previstos, entre otros:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Impulsar las habilidades y conocimiento digitales del personal, esto es, digitalizar la plantilla"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rediseñar tu modelo de negocio"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Actualizar la cultura empresarial de tu organización"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cambiar las estrategias de marketing tal y como las conocemos"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Por todas estas razones, se habla tanto no sólo de la digitalización de producto o servicio, sino de la transformación digital del negocio."}]},{"type":"paragraph","content":[{"type":"text","text":"Innovación Digital por Mag. Karina G. GiustiDescarga","marks":[{"type":"link","attrs":{"href":"https://mujeresxmas.com/wp-content/uploads/2022/01/NOTA-INNOVACION-ENERO-2021.pdf"}}]}]}]}'::jsonb, '<p>Cuando hablamos de <strong>innovación digital </strong>nos referimos a un proceso de cambio del modelo de negocio o propuesta de valor a través de herramientas digitales. En esta nueva era tecnológica por la que estamos atravesando, el diseño de nuestro modelo está determinado y estrechamente relacionado con las tecnologías de la información y la comunicación.</p><p>Al encarar un proyecto de transformación, el mismo debe responder a necesidades claramente identificadas y con impacto en la propuesta de valor de nuestro negocio y/o CIA , ya sea de cara a nuestro cliente interno o externo.</p><p>No se trata de un mero cambio de forma sino de un análisis real del “is” y “<a target="_blank" rel="noopener noreferrer" href="https://context.reverso.net/translation/english-spanish/map+should">should map</a>” con enfoque estratégico; donde lo digital es el elemento táctico.</p><h3>Innovación digital</h3><p>La innovación digital también es entendida como un proceso que tiene que ver con ideas disruptivas, como el manejo acertado y eficaz de las tecnologías de las que disponemos en la actualidad y dentro del plano empresarial.</p><p><strong>TRANSFORMAR IMPLICA REPENSAR , RE- CREAR, REDEFINIR ROLES Y TAREAS, ASI COMO LOS CANALES QUE SE EMPLEAN.</strong></p><h3>Innovación digital en que consiste</h3><img loading="lazy" src="/blog/innovacion-digital-en-que-consiste-y-como-aplica/innovacion-digital-en-que-consiste-y-como-aplica-1.jpg"/><p>Digitalizar un producto o servicio consiste en reinventar el factor tradicional, a través de la tecnología. Se trata de implementar nuevas herramientas y mejorar la eficiencia a la hora de hacer llegar la propuesta de valor al cliente. Este proceso puede llevarte a un nuevo nivel de exigencia en la gestión de una organización, planteándote algunos retos que no tenías previstos, entre otros:</p><ul><li><p>Impulsar las habilidades y conocimiento digitales del personal, esto es, digitalizar la plantilla</p></li><li><p>Rediseñar tu modelo de negocio</p></li><li><p>Actualizar la cultura empresarial de tu organización</p></li><li><p>Cambiar las estrategias de marketing tal y como las conocemos</p></li></ul><p>Por todas estas razones, se habla tanto no sólo de la digitalización de producto o servicio, sino de la transformación digital del negocio.</p><p><a target="_blank" rel="noopener noreferrer" href="https://mujeresxmas.com/wp-content/uploads/2022/01/NOTA-INNOVACION-ENERO-2021.pdf">Innovación Digital por Mag. Karina G. GiustiDescarga</a></p>', 2, '/blog/innovacion-digital-en-que-consiste-y-como-aplica/innovacion-digital-en-que-consiste-y-como-aplica-2.jpg', 'Innovación digital en qué consiste y cómo aplica', 'Mujeres x Más', '2022-01-19T18:00:47-03:00'::timestamptz),
  ('Gaming', 'mujeres-y-el-gaming-posibilidades', 'Tradicionalmente el mundo del gaming, como muchas otras industrias, había estado predominantemente dominado por los varones, sin embargo, con el paso del tiempo se hace cada vez más visible el terreno ganado por el…', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Las mujeres, motores del cambio en el mundo del gaming"}]},{"type":"paragraph","content":[{"type":"text","text":"Tradicionalmente el mundo del gaming, como muchas otras industrias, había estado predominantemente dominado por los varones, sin embargo, con el paso del tiempo se hace cada vez más visible el terreno ganado por el "},{"type":"text","text":"género femenino","marks":[{"type":"link","attrs":{"href":"/blog/transversalizacion-de-la-perspectiva-de-genero-y-diversidad-en-el-ambito-laboral"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Según un estudio realizado por Mediacom, en el año 2019 el 47.9% de la totalidad de las personas entusiastas por los videojuegos en lo que refiere a Latinoamérica eran mujeres. Los resultados demuestran que debemos olvidar cualquier estereotipo o mejor dicho, deshacernos de los estereotipos que se otorgaron a los videojuegos y la figura del varón como único jugador."}]},{"type":"paragraph","content":[{"type":"text","text":"En realidad, el gaming siempre fue un fenómeno muy democrático, produce una llegada a muchos segmentos, lo que se visibiliza en los últimos años y se presenta como novedad es la participación del género femenino y su reconocimiento en la conquista de un terreno que la sociedad solo registraba como espacio de los varones."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Posibilidades laborales."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La reconversión del mercado y su oferta"}]},{"type":"paragraph","content":[{"type":"text","text":"La industria del gaming también tiene un espectro corporativo donde cada vez vemos más oportunidades que se refleja en el armado de sus equipos ."}]},{"type":"paragraph","content":[{"type":"text","text":"Las personas a cargo del desarrollo advirtieron que casi el 50% de sus consumidoras son mujeres y que por ende debían focalizar y orientar sus objetivos a poder entender cuáles son sus necesidades, intereses y pasiones. Para lograr esta conexión es elemental contar con equipos que trabajen con perspectiva de género, inclusión y temáticas relacionados con diversidad, algo que muchas compañías detectaron e incorporaron como parte de su estrategia de negocio."}]},{"type":"paragraph","content":[{"type":"text","text":"A lo largo de los años, todas aquellas mujeres que se fueron introduciendo en este campo hoy son fuente de inspiración para millones de niñas que les gusta, se divierten y desean ser parte del mundo del gaming."}]},{"type":"paragraph","content":[{"type":"text","text":"Aunque aún queda mucho camino por recorrer, sin duda la industria del gaming se está transformando, transformando un espacio cerrado en uno inclusivo, diverso y lleno oportunidades."}]},{"type":"paragraph","content":[{"type":"text","text":"Si te interesa el tema te dejamos más información en el siguiente"},{"type":"text","text":" link","marks":[{"type":"link","attrs":{"href":"https://www.trecebits.com/"}}]},{"type":"text","text":":"}]},{"type":"image","attrs":{"src":"/blog/mujeres-y-el-gaming-posibilidades/imagen-gamming.jpg","alt":null,"title":null}},{"type":"image","attrs":{"src":"/blog/mujeres-y-el-gaming-posibilidades/imagen-gamming-ii.jpg","alt":null,"title":null}},{"type":"image","attrs":{"src":"/blog/mujeres-y-el-gaming-posibilidades/imagen-gammin-i.jpg","alt":null,"title":null}}]}'::jsonb, '<h2>Las mujeres, motores del cambio en el mundo del gaming</h2><p>Tradicionalmente el mundo del gaming, como muchas otras industrias, había estado predominantemente dominado por los varones, sin embargo, con el paso del tiempo se hace cada vez más visible el terreno ganado por el <a href="/blog/transversalizacion-de-la-perspectiva-de-genero-y-diversidad-en-el-ambito-laboral">género femenino</a>.</p><p>Según un estudio realizado por Mediacom, en el año 2019 el 47.9% de la totalidad de las personas entusiastas por los videojuegos en lo que refiere a Latinoamérica eran mujeres. Los resultados demuestran que debemos olvidar cualquier estereotipo o mejor dicho, deshacernos de los estereotipos que se otorgaron a los videojuegos y la figura del varón como único jugador.</p><p>En realidad, el gaming siempre fue un fenómeno muy democrático, produce una llegada a muchos segmentos, lo que se visibiliza en los últimos años y se presenta como novedad es la participación del género femenino y su reconocimiento en la conquista de un terreno que la sociedad solo registraba como espacio de los varones.</p><h2>Posibilidades laborales.</h2><h2>La reconversión del mercado y su oferta</h2><p>La industria del gaming también tiene un espectro corporativo donde cada vez vemos más oportunidades que se refleja en el armado de sus equipos .</p><p>Las personas a cargo del desarrollo advirtieron que casi el 50% de sus consumidoras son mujeres y que por ende debían focalizar y orientar sus objetivos a poder entender cuáles son sus necesidades, intereses y pasiones. Para lograr esta conexión es elemental contar con equipos que trabajen con perspectiva de género, inclusión y temáticas relacionados con diversidad, algo que muchas compañías detectaron e incorporaron como parte de su estrategia de negocio.</p><p>A lo largo de los años, todas aquellas mujeres que se fueron introduciendo en este campo hoy son fuente de inspiración para millones de niñas que les gusta, se divierten y desean ser parte del mundo del gaming.</p><p>Aunque aún queda mucho camino por recorrer, sin duda la industria del gaming se está transformando, transformando un espacio cerrado en uno inclusivo, diverso y lleno oportunidades.</p><p>Si te interesa el tema te dejamos más información en el siguiente<a target="_blank" rel="noopener noreferrer" href="https://www.trecebits.com/"> link</a>:</p><img loading="lazy" src="/blog/mujeres-y-el-gaming-posibilidades/imagen-gamming.jpg"/><img loading="lazy" src="/blog/mujeres-y-el-gaming-posibilidades/imagen-gamming-ii.jpg"/><img loading="lazy" src="/blog/mujeres-y-el-gaming-posibilidades/imagen-gammin-i.jpg"/>', 2, '/blog/mujeres-y-el-gaming-posibilidades/gamming.jpg', 'Gaming', 'Mujeres x Más', '2021-08-28T16:40:17-03:00'::timestamptz),
  ('Como iniciarnos en el cuidado de la piel.', 'como-iniciarnos-en-el-cuidado-de-la-piel', '¿Sabías que la piel es el órgano más grande del cuerpo humano?', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"¿Sabías que la piel es el órgano más grande del cuerpo humano?"}]},{"type":"paragraph","content":[{"type":"text","text":"Es la encargada de protegernos y conectarnos con el exterior, por eso es importante cuidarla y protegerla."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Pero cómo? En este nota te cuento las principales recomendaciones que debemos tener en cuenta para que te inicies en el cuidado de tu piel en ¡tan solo cuatro pasos!."}]},{"type":"paragraph","content":[{"type":"text","text":"1) Conocerla"}]},{"type":"paragraph","content":[{"type":"text","text":"Cada piel es única, como cada una de nosotras, y cuenta una historia. Si tomamos mucho sol, si la maternidad nos dejó manchitas, si me cuido (o no), si es sensible o se banca todas, a veces tenemos algunas cicatrices, ¡las líneas de expresión!: por reír, llorar, fruncir el ceño…"}]},{"type":"paragraph","content":[{"type":"text","text":"Es clave conocerla, observarla, conectar con ella y con nosotras a la hora de mirarnos en el espejo. Nadie mejor que cada una para saber las cosas por las que ha pasado."}]},{"type":"paragraph","content":[{"type":"text","text":"La ayuda de persona profesional va a enseñarte trucos para reconocer tu tipo de piel: para lograr tener una piel sana y natural, necesitamos conocer nuestro biotipo."}]},{"type":"paragraph","content":[{"type":"text","text":"2) Diseñar nuestro plan de cuidados"}]},{"type":"paragraph","content":[{"type":"text","text":"Cada piel es única y necesita su propio plan de cuidados, saber cuáles son los productos ideales para ella, el correcto orden de aplicación y la forma correcta de hacerlo."}]},{"type":"paragraph","content":[{"type":"text","text":"3) Ponernos en acción"}]},{"type":"paragraph","content":[{"type":"text","text":"Nada más y nada menos. Dedicarnos un tiempo, hacerle lugar en nuestra rutina diaria. Por la mañana y por la noche, cada momento es fundamental. Durante la mañana, porque vamos a preparar la piel para la jornada que vendrá y por la noche, para limpiar la piel y permitirle que respire. Mientras dormimos, nuestro cuerpo se regenera y también lo hace nuestra piel."}]},{"type":"paragraph","content":[{"type":"text","text":"4) Ser constantes."}]},{"type":"paragraph","content":[{"type":"text","text":"En cada rutina o actividad que nos proponemos, el éxito, para mí lo define disfrutar de ese proceso. Pero fundamentalmente, no abandonar, siempre hay cosas que nos pasan, que hacen que interrumpamos la rutina o nos distrae. ¡No importa! Seguimos, pero por sobre todo lo disfrutamos. Una vez que nos hayamos generado el hábito, los cambios se ven enseguida. Y créeme que novas a querer volver a lo anterior."}]},{"type":"paragraph","content":[{"type":"text","text":"Más allá de estos cuatro pasos, y porque somos un todo, te dejo algunos tips más de cuidado integral:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Un buen descanso. Como te dije antes, nuestra piel necesita descansar para funcionar correctamente y regenerarse. Es recomendable dormir entre 7 y 8 horas diarias."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Realizar ejercicio físico. Cuando ejercitamos, nuestro organismo recibe mayor cantidad de nutrientes y oxígeno, que luego se ve reflejado en nuestra piel. No importa si es correr un triatlón o caminar por la plaza, lo importante es moverse."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Llevar una alimentación saludable. Mantener una dieta equilibrada y variada en general será beneficioso para tu salud en general, y por ende también para tu piel. Consumir muchas frutas y vegetales, elegir productos bajos en grasa, reducir los dulces y las harinas refinadas. No limitarnos en lo que ingerimos, pero sí tomar decisiones saludables al momento de alimentarnos. Y por supuesto, cada tanto darnos un gustito. • Hidratarnos. Fundamental tomar mínimo 2 litros de agua por día, fuera de las comidas y que sea solo agua (no gaseosas, no jugos, no infusiones). Puede parecer mucho, pero si lo pensás, son tan solo 8 vasos de agua durante el día. Distribuilos de una forma que te resulte práctica en tu jornada diaria."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"La forma en que nos miramos. El estado de nuestra piel está directamente relacionado con lo que ocurre en nuestro interior. Nuestro nivel de autoestima influye en nuestras emociones, y nuestro estado emocional, se refleja en la piel. Sentirnos bien con nosotras mismas es tan importante como todos los tips anteriores. El primer paso para querernos es conocernos y el segundo, cuidarnos, porque nadie lo puede hacer mejor que nosotras mismas."}]}]}]},{"type":"image","attrs":{"src":"/blog/como-iniciarnos-en-el-cuidado-de-la-piel/1-cuidado-de-la-piel-1.jpg","alt":null,"title":null}},{"type":"image","attrs":{"src":"/blog/como-iniciarnos-en-el-cuidado-de-la-piel/3-cuidado-de-la-piel.jpg","alt":null,"title":null}},{"type":"image","attrs":{"src":"/blog/como-iniciarnos-en-el-cuidado-de-la-piel/4-cuidado-de-la-piel.jpg","alt":null,"title":null}},{"type":"image","attrs":{"src":"/blog/como-iniciarnos-en-el-cuidado-de-la-piel/5-cuidado-de-la-piel.jpg","alt":null,"title":null}},{"type":"image","attrs":{"src":"/blog/como-iniciarnos-en-el-cuidado-de-la-piel/6-cuidado-de-la-piel.jpg","alt":null,"title":null}},{"type":"image","attrs":{"src":"/blog/como-iniciarnos-en-el-cuidado-de-la-piel/2-cuidado-de-la-piel.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Autor:","marks":[{"type":"bold"}]},{"type":"text","text":" Eugenia Grigera"}]},{"type":"paragraph","content":[{"type":"text","text":"Redes Sociales: "},{"type":"text","text":"@eugeniagrigera","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/eugeniagrigera.cosmetologia/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Link de interés:"}]},{"type":"paragraph","content":[{"type":"text","text":"https://www.eugeniagrigera.com/","marks":[{"type":"link","attrs":{"href":"https://www.eugeniagrigera.com/"}}]}]}]}'::jsonb, '<p>¿Sabías que la piel es el órgano más grande del cuerpo humano?</p><p>Es la encargada de protegernos y conectarnos con el exterior, por eso es importante cuidarla y protegerla.</p><p>¿Pero cómo? En este nota te cuento las principales recomendaciones que debemos tener en cuenta para que te inicies en el cuidado de tu piel en ¡tan solo cuatro pasos!.</p><p>1) Conocerla</p><p>Cada piel es única, como cada una de nosotras, y cuenta una historia. Si tomamos mucho sol, si la maternidad nos dejó manchitas, si me cuido (o no), si es sensible o se banca todas, a veces tenemos algunas cicatrices, ¡las líneas de expresión!: por reír, llorar, fruncir el ceño…</p><p>Es clave conocerla, observarla, conectar con ella y con nosotras a la hora de mirarnos en el espejo. Nadie mejor que cada una para saber las cosas por las que ha pasado.</p><p>La ayuda de persona profesional va a enseñarte trucos para reconocer tu tipo de piel: para lograr tener una piel sana y natural, necesitamos conocer nuestro biotipo.</p><p>2) Diseñar nuestro plan de cuidados</p><p>Cada piel es única y necesita su propio plan de cuidados, saber cuáles son los productos ideales para ella, el correcto orden de aplicación y la forma correcta de hacerlo.</p><p>3) Ponernos en acción</p><p>Nada más y nada menos. Dedicarnos un tiempo, hacerle lugar en nuestra rutina diaria. Por la mañana y por la noche, cada momento es fundamental. Durante la mañana, porque vamos a preparar la piel para la jornada que vendrá y por la noche, para limpiar la piel y permitirle que respire. Mientras dormimos, nuestro cuerpo se regenera y también lo hace nuestra piel.</p><p>4) Ser constantes.</p><p>En cada rutina o actividad que nos proponemos, el éxito, para mí lo define disfrutar de ese proceso. Pero fundamentalmente, no abandonar, siempre hay cosas que nos pasan, que hacen que interrumpamos la rutina o nos distrae. ¡No importa! Seguimos, pero por sobre todo lo disfrutamos. Una vez que nos hayamos generado el hábito, los cambios se ven enseguida. Y créeme que novas a querer volver a lo anterior.</p><p>Más allá de estos cuatro pasos, y porque somos un todo, te dejo algunos tips más de cuidado integral:</p><ul><li><p>Un buen descanso. Como te dije antes, nuestra piel necesita descansar para funcionar correctamente y regenerarse. Es recomendable dormir entre 7 y 8 horas diarias.</p></li><li><p>Realizar ejercicio físico. Cuando ejercitamos, nuestro organismo recibe mayor cantidad de nutrientes y oxígeno, que luego se ve reflejado en nuestra piel. No importa si es correr un triatlón o caminar por la plaza, lo importante es moverse.</p></li><li><p>Llevar una alimentación saludable. Mantener una dieta equilibrada y variada en general será beneficioso para tu salud en general, y por ende también para tu piel. Consumir muchas frutas y vegetales, elegir productos bajos en grasa, reducir los dulces y las harinas refinadas. No limitarnos en lo que ingerimos, pero sí tomar decisiones saludables al momento de alimentarnos. Y por supuesto, cada tanto darnos un gustito. • Hidratarnos. Fundamental tomar mínimo 2 litros de agua por día, fuera de las comidas y que sea solo agua (no gaseosas, no jugos, no infusiones). Puede parecer mucho, pero si lo pensás, son tan solo 8 vasos de agua durante el día. Distribuilos de una forma que te resulte práctica en tu jornada diaria.</p></li><li><p>La forma en que nos miramos. El estado de nuestra piel está directamente relacionado con lo que ocurre en nuestro interior. Nuestro nivel de autoestima influye en nuestras emociones, y nuestro estado emocional, se refleja en la piel. Sentirnos bien con nosotras mismas es tan importante como todos los tips anteriores. El primer paso para querernos es conocernos y el segundo, cuidarnos, porque nadie lo puede hacer mejor que nosotras mismas.</p></li></ul><img loading="lazy" src="/blog/como-iniciarnos-en-el-cuidado-de-la-piel/1-cuidado-de-la-piel-1.jpg"/><img loading="lazy" src="/blog/como-iniciarnos-en-el-cuidado-de-la-piel/3-cuidado-de-la-piel.jpg"/><img loading="lazy" src="/blog/como-iniciarnos-en-el-cuidado-de-la-piel/4-cuidado-de-la-piel.jpg"/><img loading="lazy" src="/blog/como-iniciarnos-en-el-cuidado-de-la-piel/5-cuidado-de-la-piel.jpg"/><img loading="lazy" src="/blog/como-iniciarnos-en-el-cuidado-de-la-piel/6-cuidado-de-la-piel.jpg"/><img loading="lazy" src="/blog/como-iniciarnos-en-el-cuidado-de-la-piel/2-cuidado-de-la-piel.jpg"/><p><strong>Autor:</strong> Eugenia Grigera</p><p>Redes Sociales: <a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/eugeniagrigera.cosmetologia/">@eugeniagrigera</a></p><p>Link de interés:</p><p><a target="_blank" rel="noopener noreferrer" href="https://www.eugeniagrigera.com/">https://www.eugeniagrigera.com/</a></p>', 3, '/blog/como-iniciarnos-en-el-cuidado-de-la-piel/1-cuidado-de-la-piel.jpg', 'Como iniciarnos en el cuidado de la piel.', 'Mujeres x Más', '2021-07-15T20:56:06-03:00'::timestamptz),
  ('Transversalización de la perspectiva de Género y diversidad en el ámbito laboral.', 'transversalizacion-de-la-perspectiva-de-genero-y-diversidad-en-el-ambito-laboral', 'Actualmente resulta fundamental generar culturas laborales más justas, igualitarias y libres de violencia, así como también, incorporar la perspectiva de género y de la diversidad en el diseño e implementación de las…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Actualmente resulta fundamental generar culturas laborales más justas, igualitarias y libres de violencia, así como también, incorporar la perspectiva de género y de la diversidad en el diseño e implementación de las políticas llevadas adelante por un organismo o empresa."}]},{"type":"paragraph","content":[{"type":"text","text":"Si retrocedemos en el tiempo se puede dar cuenta que la"},{"type":"text","text":" transversalización de","marks":[{"type":"bold"}]},{"type":"text","text":" la perspectiva de género como enfoque en las políticas públicas y como estrategia al interior de las instituciones para integrar las cuestiones de género en la totalidad de los programas sociales, quedó establecida como estrategia global para promover la igualdad entre los géneros, en la Plataforma de Acción adoptada en la Cuarta Conferencia Mundial de las Naciones Unidas sobre la Mujer, celebrada en Pekín en 1995 que resalta la necesidad de garantizar que la igualdad entre los géneros es un objetivo primario en todas las áreas del desarrollo social."}]},{"type":"paragraph","content":[{"type":"text","text":"Transversalizar la perspectiva de género significa, visibilizar y analizar las desigualdades entre los géneros, las relaciones de poder existentes entre los mismos, e intervenir para modificarlo. Es decir, incluir la perspectiva de género y diversidad en todas sus acciones y avanzar en la construcción de políticas capaces de transformar las estructuras desiguales existentes. En este sentido, la igualdad de género debe ser uno de los principios que guíe el diseño, la ejecución y la evaluación de todos sus programas y proyectos."}]},{"type":"paragraph","content":[{"type":"text","text":"Frente a la pregunta ¿Cómo comenzar a implementar este enfoque en espacio de trabajo? Una estrategia general recomendable es llevar el análisis de género a todas las etapas del proyecto, desde la identificación del problema, el diseño, la ejecución, el seguimiento y la evaluación. Aunque también, en algunas ocasiones, la estrategia podrá ser identificar por dónde es conveniente iniciar este proceso, pudiendo visualizar qué aspectos o dimensiones se presentan factibles de ser modificados."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Una intervención posible"}]},{"type":"paragraph","content":[{"type":"text","text":"El objetivo es poder trabajar en una estrategia metodológica que permite identificar cuáles son las diferentes "},{"type":"text","text":"dimensiones de la transversalización","marks":[{"type":"bold"},{"type":"italic"}]},{"type":"text","text":",","marks":[{"type":"italic"}]},{"type":"text","text":" ","marks":[{"type":"bold"}]},{"type":"text","text":"a través de las cuales un organismo puede iniciar, potenciar o profundizar este recorrido."}]},{"type":"paragraph","content":[{"type":"text","text":"Desde este punto de vista, se busca contribuir a la identificación de las diferentes formas, maneras y etapas de organizar este proceso de institucionalización de la perspectiva de género desde una perspectiva transversal e integral."}]},{"type":"paragraph","content":[{"type":"text","text":"Una reflexión personal y colectiva","marks":[{"type":"bold"},{"type":"italic"}]},{"type":"text","text":" ","marks":[{"type":"bold"}]},{"type":"text","text":"contribuye en tanto apela a poder reflexionar sobre las ideas previas, resistencias, deconstrucciones, necesidades e inquietudes. Es preciso poder reconocer desde qué punto partimos para pensar hacia dónde vamos apelando a la reflexión personal y colectiva. En este sentido, refiere a la importancia de iniciar y promover espacios de formación interna que den lugar a conversar sobre estos temas priorizando trabajos basados en aspectos vivenciales, así como en la experiencia."}]},{"type":"paragraph","content":[{"type":"text","text":"La posibilidad de "},{"type":"text","text":"revisar, prever, proyectar, planificar e implementar políticas que incorporen una mirada de género y diversidad ","marks":[{"type":"bold"},{"type":"italic"}]},{"type":"text","text":"da cuenta de que tales decisiones pueden tomarse en distintos niveles e instancias del desarrollo de una política a implementar."}]},{"type":"paragraph","content":[{"type":"text","text":"Esta tarea implica impulsar y promover procesos de transversalización de la perspectiva de género y diversidad, incorporar una mirada interseccional del género y visibilizar cómo el género se entrama con otras categorías (clase, etnia, orientación sexual, edad, residencia urbana o rural, etc.)."}]},{"type":"paragraph","content":[{"type":"text","text":"La "},{"type":"text","text":"organización de la cultura laboral","marks":[{"type":"bold"},{"type":"italic"}]},{"type":"text","text":" ","marks":[{"type":"bold"}]},{"type":"text","text":"apunta a desnaturalizar los guiones invisibles que van dejando marca como las regulaciones, rituales y prácticas que día a día constituyen la cultura laboral, que en diversos escenarios transmite saberes y reproducen visiones acerca del género, de lo esperable, permitido o prohibido, lo jerarquizado, opresiones, a través del lenguaje utilizado y también del lenguaje corporal, del uso de los espacios, de las formas de agrupamiento habituales, los roles, de las expectativas según el género, etc. En este sentido, incorporar la perspectiva de género en nuestros lugares de trabajo permite desnaturalizar el conjunto de estereotipos y roles que condicionan el lugar que ocupan las personas en nuestra sociedad según el género."}]},{"type":"paragraph","content":[{"type":"text","text":"Abordar lo que irrumpe","marks":[{"type":"bold"},{"type":"italic"}]},{"type":"text","text":", ","marks":[{"type":"italic"}]},{"type":"text","text":"aquello"},{"type":"text","text":" ","marks":[{"type":"italic"}]},{"type":"text","text":"que altera la dinámica cotidiana en el marco laboral. Tal alteración puede suceder por el carácter abrupto de lo sucedido o por tratarse de algo inesperado. Generalmente estos eventos alteran el cotidiano habitual de un espacio, y en ocasiones –aunque no siempre- implican algún tipo de conflicto o tensión."}]},{"type":"paragraph","content":[{"type":"text","text":"Puede ser que irrumpa una situación que implique una vulneración de derechos y allí será necesario activar un trabajo atento sobre intervenciones, abordajes, protocolos. Estos episodios se presentan como una oportunidad para abrir espacios de reflexión colectiva en los organismos, en tanto que cualquiera de las situaciones que se presenten, siempre, referirán a cuestiones estructurales propias de la sociedad y cultura a la que pertenecen las personas."}]},{"type":"paragraph","content":[{"type":"text","text":"Para finalizar, cabe mencionar la importancia de "},{"type":"text","text":"la relación del organismo con otros actores","marks":[{"type":"bold"},{"type":"italic"}]},{"type":"text","text":", entendiendo que el vínculo con otras instancias enriquece y fortalece siempre los propios abordajes. Establecer o fortalecer estos vínculos de trabajo intersectorial y con la comunidad, es también una forma que posibilita la identificación de problemáticas asociadas a la violencia estructural para revisar el propio rol de los organismos y las políticas implementadas."}]},{"type":"paragraph","content":[{"type":"text","text":"La transversalización de la perspectiva de género y diversidad no es simplemente un proceso técnico, implica un proceso político que pone en juego una redistribución de recursos y de poder, así como también el desafío de lograr un trabajo de articulación entre todas y todos los agentes que la integran."}]}]}'::jsonb, '<p>Actualmente resulta fundamental generar culturas laborales más justas, igualitarias y libres de violencia, así como también, incorporar la perspectiva de género y de la diversidad en el diseño e implementación de las políticas llevadas adelante por un organismo o empresa.</p><p>Si retrocedemos en el tiempo se puede dar cuenta que la<strong> transversalización de</strong> la perspectiva de género como enfoque en las políticas públicas y como estrategia al interior de las instituciones para integrar las cuestiones de género en la totalidad de los programas sociales, quedó establecida como estrategia global para promover la igualdad entre los géneros, en la Plataforma de Acción adoptada en la Cuarta Conferencia Mundial de las Naciones Unidas sobre la Mujer, celebrada en Pekín en 1995 que resalta la necesidad de garantizar que la igualdad entre los géneros es un objetivo primario en todas las áreas del desarrollo social.</p><p>Transversalizar la perspectiva de género significa, visibilizar y analizar las desigualdades entre los géneros, las relaciones de poder existentes entre los mismos, e intervenir para modificarlo. Es decir, incluir la perspectiva de género y diversidad en todas sus acciones y avanzar en la construcción de políticas capaces de transformar las estructuras desiguales existentes. En este sentido, la igualdad de género debe ser uno de los principios que guíe el diseño, la ejecución y la evaluación de todos sus programas y proyectos.</p><p>Frente a la pregunta ¿Cómo comenzar a implementar este enfoque en espacio de trabajo? Una estrategia general recomendable es llevar el análisis de género a todas las etapas del proyecto, desde la identificación del problema, el diseño, la ejecución, el seguimiento y la evaluación. Aunque también, en algunas ocasiones, la estrategia podrá ser identificar por dónde es conveniente iniciar este proceso, pudiendo visualizar qué aspectos o dimensiones se presentan factibles de ser modificados.</p><h2>Una intervención posible</h2><p>El objetivo es poder trabajar en una estrategia metodológica que permite identificar cuáles son las diferentes <strong><em>dimensiones de la transversalización</em></strong><em>,</em><strong> </strong>a través de las cuales un organismo puede iniciar, potenciar o profundizar este recorrido.</p><p>Desde este punto de vista, se busca contribuir a la identificación de las diferentes formas, maneras y etapas de organizar este proceso de institucionalización de la perspectiva de género desde una perspectiva transversal e integral.</p><p><strong><em>Una reflexión personal y colectiva</em></strong><strong> </strong>contribuye en tanto apela a poder reflexionar sobre las ideas previas, resistencias, deconstrucciones, necesidades e inquietudes. Es preciso poder reconocer desde qué punto partimos para pensar hacia dónde vamos apelando a la reflexión personal y colectiva. En este sentido, refiere a la importancia de iniciar y promover espacios de formación interna que den lugar a conversar sobre estos temas priorizando trabajos basados en aspectos vivenciales, así como en la experiencia.</p><p>La posibilidad de <strong><em>revisar, prever, proyectar, planificar e implementar políticas que incorporen una mirada de género y diversidad </em></strong>da cuenta de que tales decisiones pueden tomarse en distintos niveles e instancias del desarrollo de una política a implementar.</p><p>Esta tarea implica impulsar y promover procesos de transversalización de la perspectiva de género y diversidad, incorporar una mirada interseccional del género y visibilizar cómo el género se entrama con otras categorías (clase, etnia, orientación sexual, edad, residencia urbana o rural, etc.).</p><p>La <strong><em>organización de la cultura laboral</em></strong><strong> </strong>apunta a desnaturalizar los guiones invisibles que van dejando marca como las regulaciones, rituales y prácticas que día a día constituyen la cultura laboral, que en diversos escenarios transmite saberes y reproducen visiones acerca del género, de lo esperable, permitido o prohibido, lo jerarquizado, opresiones, a través del lenguaje utilizado y también del lenguaje corporal, del uso de los espacios, de las formas de agrupamiento habituales, los roles, de las expectativas según el género, etc. En este sentido, incorporar la perspectiva de género en nuestros lugares de trabajo permite desnaturalizar el conjunto de estereotipos y roles que condicionan el lugar que ocupan las personas en nuestra sociedad según el género.</p><p><strong><em>Abordar lo que irrumpe</em></strong><em>, </em>aquello<em> </em>que altera la dinámica cotidiana en el marco laboral. Tal alteración puede suceder por el carácter abrupto de lo sucedido o por tratarse de algo inesperado. Generalmente estos eventos alteran el cotidiano habitual de un espacio, y en ocasiones –aunque no siempre- implican algún tipo de conflicto o tensión.</p><p>Puede ser que irrumpa una situación que implique una vulneración de derechos y allí será necesario activar un trabajo atento sobre intervenciones, abordajes, protocolos. Estos episodios se presentan como una oportunidad para abrir espacios de reflexión colectiva en los organismos, en tanto que cualquiera de las situaciones que se presenten, siempre, referirán a cuestiones estructurales propias de la sociedad y cultura a la que pertenecen las personas.</p><p>Para finalizar, cabe mencionar la importancia de <strong><em>la relación del organismo con otros actores</em></strong>, entendiendo que el vínculo con otras instancias enriquece y fortalece siempre los propios abordajes. Establecer o fortalecer estos vínculos de trabajo intersectorial y con la comunidad, es también una forma que posibilita la identificación de problemáticas asociadas a la violencia estructural para revisar el propio rol de los organismos y las políticas implementadas.</p><p>La transversalización de la perspectiva de género y diversidad no es simplemente un proceso técnico, implica un proceso político que pone en juego una redistribución de recursos y de poder, así como también el desafío de lograr un trabajo de articulación entre todas y todos los agentes que la integran.</p>', 4, '/blog/transversalizacion-de-la-perspectiva-de-genero-y-diversidad-en-el-ambito-laboral/transversalizacion-de-la-perspectiva-de-genero.jpg', 'Transversalización de la perspectiva de Género y diversidad en el ámbito laboral.', 'Mujeres x Más', '2021-05-14T21:23:35-03:00'::timestamptz),
  ('La huella digital es el rastro que dejas al navegar en Internet.', 'administracion-huella-digital-en-internet', 'Varios son los datos que van componiendo tu HUELLA DIGITAL, entre otros:', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"En cada interacción, en cada elección, en cada “click” o “me gusta”, cuando usas una aplicación desde tu celular o tu computadora, dejas tu HUELLA. Esta sumatoria de interacciones generan tu HUELLA DIGITAL."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"COMO SE COMPONE TU HUELLA DIGITAL"}]},{"type":"paragraph","content":[{"type":"text","text":"Varios son los datos que van componiendo tu HUELLA DIGITAL, entre otros:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Datos públicos: ","marks":[{"type":"bold"}]},{"type":"text","text":"Son los datos de la obra social, cuit o cuil, declaraciones de impuestos, domicilios en las facturas de servicios, resúmenes de tarjetas de crédito, cargos, becas, resultados de sorteos, resoluciones judiciales."}]}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Datos publicados por otros:","marks":[{"type":"bold"}]},{"type":"text","text":" Son fotos, posteos de amigos, familiares, clubes o espacios de pertenencia en redes sociales."}]}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Datos que generás vos:","marks":[{"type":"bold"}]},{"type":"text","text":" Posteos, comentarios, fotos en redes sociales y foros. Formularios que completaste, contenidos que compartiste en plataformas como tu currículum, perfiles en redes de contactos u otros contenidos como listas de reproducción y videos favoritos."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"COMO SE ALMACENAN LOS DATOS DE MI HUELLA"}]},{"type":"paragraph","content":[{"type":"text","text":"Los datos se recopilan a través de las “cookies”."}]},{"type":"paragraph","content":[{"type":"text","text":"Las “cookies” son una cadena de letras y números, sin ningún significado intrínseco que un sitio web envía a su navegador web."}]},{"type":"image","attrs":{"src":"/blog/administracion-huella-digital-en-internet/mujeres-por-mas2.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Esta información permite a los proveedores de servicios de Internet vincular todas las acciones realizadas por un usuario y convertirlas en un hilo conectado."}]},{"type":"paragraph","content":[{"type":"text","text":"Las cookies son necesarias para aumentar la usabilidad de Internet. También pueden ayudar a que las transacciones individuales sean más seguras."}]},{"type":"paragraph","content":[{"type":"text","text":"No podemos navegar sin cookies. Este es el motivo por el cual hay cookies por todas partes."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"COMO ADMINISTRO MI HUELLA DIGITAL"}]},{"type":"paragraph","content":[{"type":"text","text":"Todos los sitios y APP´s deben avisar a los usuarios que tipo de datos recolectará en su servicio."}]},{"type":"paragraph","content":[{"type":"text","text":"La aceptación de estas condiciones definirá el tipo de permisos que como usuario autorices. La ley de tratamiento de datos personales es la que otorga el marco legal para el tratamiento de estos con seguridad. Para ello cada país propicia un marco normativo de acuerdo con su legislación."}]},{"type":"paragraph","content":[{"type":"text","text":"Algunos tips para tener en cuenta:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configura la privacidad de tus redes sociales para que no se exponga toda tu información personal."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navega de incógnito"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configura el Do not Track"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configura las alertas de Google para que no existan datos personales innecesarios en la web. Podes ver cómo hacerlo en este tutorial de Con vos en la Web"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Denuncia aquellas páginas que exponen información personal sin tu consentimiento."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Links de interés","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ley de protección de datos personales","marks":[{"type":"link","attrs":{"href":"http://servicios.infoleg.gob.ar/infolegInternet/anexos/60000-64999/64790/norma.htm"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Como proteger tu información personal","marks":[{"type":"link","attrs":{"href":"https://www.consumidor.ftc.gov/articulos/s0272-como-proteger-su-informacion-personal"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"https://www.internetsociety.org","marks":[{"type":"link","attrs":{"href":"https://www.internetsociety.org/"}}]}]}]}]}]}'::jsonb, '<h2>En cada interacción, en cada elección, en cada “click” o “me gusta”, cuando usas una aplicación desde tu celular o tu computadora, dejas tu HUELLA. Esta sumatoria de interacciones generan tu HUELLA DIGITAL.</h2><h3>COMO SE COMPONE TU HUELLA DIGITAL</h3><p>Varios son los datos que van componiendo tu HUELLA DIGITAL, entre otros:</p><ul><li><p><strong>Datos públicos: </strong>Son los datos de la obra social, cuit o cuil, declaraciones de impuestos, domicilios en las facturas de servicios, resúmenes de tarjetas de crédito, cargos, becas, resultados de sorteos, resoluciones judiciales.</p></li></ul><ul><li><p><strong>Datos publicados por otros:</strong> Son fotos, posteos de amigos, familiares, clubes o espacios de pertenencia en redes sociales.</p></li></ul><ul><li><p><strong>Datos que generás vos:</strong> Posteos, comentarios, fotos en redes sociales y foros. Formularios que completaste, contenidos que compartiste en plataformas como tu currículum, perfiles en redes de contactos u otros contenidos como listas de reproducción y videos favoritos.</p></li></ul><h3>COMO SE ALMACENAN LOS DATOS DE MI HUELLA</h3><p>Los datos se recopilan a través de las “cookies”.</p><p>Las “cookies” son una cadena de letras y números, sin ningún significado intrínseco que un sitio web envía a su navegador web.</p><img loading="lazy" src="/blog/administracion-huella-digital-en-internet/mujeres-por-mas2.jpg"/><p>Esta información permite a los proveedores de servicios de Internet vincular todas las acciones realizadas por un usuario y convertirlas en un hilo conectado.</p><p>Las cookies son necesarias para aumentar la usabilidad de Internet. También pueden ayudar a que las transacciones individuales sean más seguras.</p><p>No podemos navegar sin cookies. Este es el motivo por el cual hay cookies por todas partes.</p><h3>COMO ADMINISTRO MI HUELLA DIGITAL</h3><p>Todos los sitios y APP´s deben avisar a los usuarios que tipo de datos recolectará en su servicio.</p><p>La aceptación de estas condiciones definirá el tipo de permisos que como usuario autorices. La ley de tratamiento de datos personales es la que otorga el marco legal para el tratamiento de estos con seguridad. Para ello cada país propicia un marco normativo de acuerdo con su legislación.</p><p><strong>Algunos tips para tener en cuenta:</strong></p><ul><li><p>Configura la privacidad de tus redes sociales para que no se exponga toda tu información personal.</p></li><li><p>Navega de incógnito</p></li><li><p>Configura el Do not Track</p></li><li><p>Configura las alertas de Google para que no existan datos personales innecesarios en la web. Podes ver cómo hacerlo en este tutorial de Con vos en la Web</p></li><li><p>Denuncia aquellas páginas que exponen información personal sin tu consentimiento.</p></li></ul><p><strong>Links de interés</strong></p><ul><li><p><a target="_blank" rel="noopener noreferrer" href="http://servicios.infoleg.gob.ar/infolegInternet/anexos/60000-64999/64790/norma.htm">Ley de protección de datos personales</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.consumidor.ftc.gov/articulos/s0272-como-proteger-su-informacion-personal">Como proteger tu información personal</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.internetsociety.org/">https://www.internetsociety.org</a></p></li></ul>', 2, '/blog/administracion-huella-digital-en-internet/la-huella-digital-es-el-rastro-que-dejas-al-navegar-en-internet-.jpg', 'La huella digital es el rastro que dejas al navegar en Internet.', 'Mujeres x Más', '2021-04-14T14:45:51-03:00'::timestamptz),
  ('Impuesto Rosa – ¿Qué es? ¿Y cómo nos afecta?', 'impuesto-rosa-en-argentina', 'Un relevamiento realizado por Focus Market muestra que estos conceptos registraron un incremento de 10,8 % si se considera una canasta de productos de higiene personal y perfumería de consumo femenino contra los…', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"El impuesto ROSA es el que resulta de la aplicación de sobrecostos en los productos de consumo femeninos."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Las mujeres pagan en promedio un 11% más que los varones por los mismos productos."}]},{"type":"paragraph","content":[{"type":"text","text":"Un relevamiento realizado por Focus Market muestra que estos conceptos registraron un incremento de 10,8 % si se considera una canasta de productos de higiene personal y perfumería de consumo femenino contra los mismos de consumo masculino (ej. rasuradoras, perfumes, etc). La brecha registró una baja en los últimos dos años pero aún sigue siendo significativa.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Sólo por tener una presentación destinada al universo femenino, las mujeres pagan casi 11% más que los varones por los mismos productos, según un informe de la consultora Focus Market. Este recargo, que no se fundamenta en las características del producto sino en su marketing, es conocido como el “impuesto rosa” y si bien se redujo en los últimos años, se mantiene sobre todo en productos de higiene personal y perfumería."}]},{"type":"image","attrs":{"src":"/blog/impuesto-rosa-en-argentina/impuesto-rosa-en-argentina.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"De acuerdo con un relevamiento realizado por Focus Market en 515 puntos de venta de todo el país sobre 14 productos pertenecientes a cinco categorías diferentes, este concepto marcó una diferencia de 10,8 % en 2021."}]},{"type":"paragraph","content":[{"type":"text","text":"El seguimiento fue realizado con los mismos productos que se consideraron en las ediciones anteriores y de la serie se desprende que la brecha se redujo en los últimos años. En 2018 el sobreprecio registrado fue de 13,7%, bajó a 11,3% en 2019, luego escaló a 12,3% en 2020 y se ubicó en 10,8% en la medición de este año."}]},{"type":"paragraph","content":[{"type":"text","text":"Del informe se desprende que la colonia Mujercitas es 11% más cara que la opción masculina Pibes, de igual contenido. El mismo sobreprecio exhiben las máquinas de afeitar Ultragrip de Gillette por tres unidades, y la diferencia es de 12% en el caso de las afeitadoras Gillette Prestobarba 3. El “impuesto rosa” llega al 20% en el caso del perfume United Dreams Live Free, que tiene presentaciones femenina y masculina."}]},{"type":"paragraph","content":[{"type":"text","text":"A diferencia de lo registrado en 2020, el relevamiento de este año no muestra diferencia en el precio del medicamento Actron (que se ofrece en una presentación destinada a mujeres, para dolores menstruales) ni tampoco en el caso del desodorante Dove en envase roll on. El desodorante Nivea Spray Stress Protect es el único en el que la versión destinada a las consumidoras es incluso más barata que la destinada a los varones (-12%)."}]},{"type":"paragraph","content":[{"type":"text","text":"Según el informe, se comenzó a hablar del “impuesto rosa” en 1992, a partir de un informe del Departamento de Asuntos del Consumidor de Nueva York, en el que se mostraba cómo la misma faja tenía un precio distinto según a quién se ofrecía. El texto define a este concepto como el sobreprecio de un producto o servicio sólo por estar dirigido al público femenino a través de diseños que parten de estereotipos de género."}]}]}'::jsonb, '<h2>El impuesto ROSA es el que resulta de la aplicación de sobrecostos en los productos de consumo femeninos.</h2><h3>Las mujeres pagan en promedio un 11% más que los varones por los mismos productos.</h3><p><em>Un relevamiento realizado por Focus Market muestra que estos conceptos registraron un incremento de 10,8 % si se considera una canasta de productos de higiene personal y perfumería de consumo femenino contra los mismos de consumo masculino (ej. rasuradoras, perfumes, etc). La brecha registró una baja en los últimos dos años pero aún sigue siendo significativa.</em></p><p>Sólo por tener una presentación destinada al universo femenino, las mujeres pagan casi 11% más que los varones por los mismos productos, según un informe de la consultora Focus Market. Este recargo, que no se fundamenta en las características del producto sino en su marketing, es conocido como el “impuesto rosa” y si bien se redujo en los últimos años, se mantiene sobre todo en productos de higiene personal y perfumería.</p><img loading="lazy" src="/blog/impuesto-rosa-en-argentina/impuesto-rosa-en-argentina.png"/><p>De acuerdo con un relevamiento realizado por Focus Market en 515 puntos de venta de todo el país sobre 14 productos pertenecientes a cinco categorías diferentes, este concepto marcó una diferencia de 10,8 % en 2021.</p><p>El seguimiento fue realizado con los mismos productos que se consideraron en las ediciones anteriores y de la serie se desprende que la brecha se redujo en los últimos años. En 2018 el sobreprecio registrado fue de 13,7%, bajó a 11,3% en 2019, luego escaló a 12,3% en 2020 y se ubicó en 10,8% en la medición de este año.</p><p>Del informe se desprende que la colonia Mujercitas es 11% más cara que la opción masculina Pibes, de igual contenido. El mismo sobreprecio exhiben las máquinas de afeitar Ultragrip de Gillette por tres unidades, y la diferencia es de 12% en el caso de las afeitadoras Gillette Prestobarba 3. El “impuesto rosa” llega al 20% en el caso del perfume United Dreams Live Free, que tiene presentaciones femenina y masculina.</p><p>A diferencia de lo registrado en 2020, el relevamiento de este año no muestra diferencia en el precio del medicamento Actron (que se ofrece en una presentación destinada a mujeres, para dolores menstruales) ni tampoco en el caso del desodorante Dove en envase roll on. El desodorante Nivea Spray Stress Protect es el único en el que la versión destinada a las consumidoras es incluso más barata que la destinada a los varones (-12%).</p><p>Según el informe, se comenzó a hablar del “impuesto rosa” en 1992, a partir de un informe del Departamento de Asuntos del Consumidor de Nueva York, en el que se mostraba cómo la misma faja tenía un precio distinto según a quién se ofrecía. El texto define a este concepto como el sobreprecio de un producto o servicio sólo por estar dirigido al público femenino a través de diseños que parten de estereotipos de género.</p>', 2, '/blog/impuesto-rosa-en-argentina/mujeres-pagan-mas-por-los-productos-que-los-hombres.jpg', 'Impuesto Rosa – ¿Qué es? ¿Y cómo nos afecta?', 'Mujeres x Más', '2021-04-01T11:06:00-03:00'::timestamptz),
  ('ENEAGRAMA – Una guía para acercarnos a nuestro interior', 'significado-de-un-eneagrama-explicacion', 'Eneagrama en griego significa literalmente nueve líneas. En geometría, un eneagrama es una estrella de nueve puntas.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"¿Qué ES EL ENEAGRAMA?"}]},{"type":"paragraph","content":[{"type":"text","text":"Eneagrama en griego significa literalmente nueve líneas. En geometría, un eneagrama es una estrella de nueve puntas."}]},{"type":"paragraph","content":[{"type":"text","text":"El eneagrama en Psicología es una propuesta de autoconocimiento, un mapa del comportamiento humano, un sistema dinámico de crecimiento personal."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"La importancia del autoconocimiento"}]},{"type":"paragraph","content":[{"type":"text","text":"Desde la antigüedad se habla de la importancia del conocerse."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"¿Por qué es tan importante saber cómo soy?"}]},{"type":"paragraph","content":[{"type":"text","text":"Porque no vemos el mundo como ES sino COMO SOMOS"}]},{"type":"paragraph","content":[{"type":"text","text":"Cada uno percibe la realidad a través de un filtro y con el "},{"type":"text","text":"Eneagrama","marks":[{"type":"bold"}]},{"type":"text","text":" detectamos con mayor claridad los distintos tipos de filtro."}]},{"type":"paragraph","content":[{"type":"text","text":"El"},{"type":"text","text":" Eneagrama","marks":[{"type":"bold"}]},{"type":"text","text":" ayuda no sólo a saber cómo soy, sino que invita a descubrir cómo puedo llegar a ser. Y para eso ofrece caminos que ayudan a darse cuenta del “piloto automático” con el cual nos acostumbramos a vivir y reaccionar, y así poder elegir cómo responder a las circunstancias sabiendo que con cada respuesta vamos creando la vida que tenemos."}]},{"type":"paragraph","content":[{"type":"text","text":"La grandeza del Eneagrama reside en su profundidad y sencillez a la vez. Es un idioma actitudinal ya que ayuda a comprender las actitudes de las personas, mejorando de esa manera la forma en que nos vinculamos."}]},{"type":"image","attrs":{"src":"/blog/significado-de-un-eneagrama-explicacion/formas-de-eneagrama-2.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"El Eneagrama (enea=9, grama=dibujo) habla de 9 formas básicas de ser, 9 maneras de funcionar y estar en el mundo. Cada una de estas 9 tipologías es una compleja interrelación de cualidades, limitaciones, motivaciones, miedos, estrategias para sentirse seguro, desafíos, prioridades al percibir, creencias, maneras de vincularse con los demás, formas de relacionarse con el cuerpo, maneras de manifestar sentimientos, emociones preferidas y muchos otros aspectos."}]},{"type":"paragraph","content":[{"type":"text","text":"Cada persona tiene estas 9 facetas dentro suyo, pero siente más familiaridad con una de ellas. Eso ayuda a saber cuáles son los dones que caracterizan a la persona, pero también adonde armó sus principales defensas obstaculizando su crecimiento."}]},{"type":"paragraph","content":[{"type":"text","text":"Conocer la tipología predominante es recién el punto de partida de un viaje hacia nuestro interior. Un viaje en el cual se va descubriendo el verdadero ser y vamos soltando todo aquello que cubre nuestra esencia, a la vez que vamos despertando todos los atributos presentes en nosotros."}]},{"type":"paragraph","content":[{"type":"text","text":"Al conocerme más, puedo decidir mejor, realizarme y sentirme plena, aceptarme y cuidarme, valorarme y ocupar mi lugar."}]},{"type":"paragraph","content":[{"type":"text","text":"Se trata de saber quién uno es y despertar la confianza para animarse a serlo."}]},{"type":"paragraph","content":[{"type":"text","text":"AUTOR:","marks":[{"type":"bold"}]},{"type":"text","text":" Josefina Majdalani"}]},{"type":"paragraph","content":[{"type":"text","text":"Querés conocer mas sobre ENEAGRAMA"}]},{"type":"paragraph","content":[{"type":"text","text":"Registrate","marks":[{"type":"link","attrs":{"href":"/registro"}}]},{"type":"text","text":" en "},{"type":"text","text":"www.mujeresxmas.com","marks":[{"type":"link","attrs":{"href":"/"}}]},{"type":"text","text":" y recibirás información de nuestra próximas actividades"}]}]}'::jsonb, '<h2>¿Qué ES EL ENEAGRAMA?</h2><p>Eneagrama en griego significa literalmente nueve líneas. En geometría, un eneagrama es una estrella de nueve puntas.</p><p>El eneagrama en Psicología es una propuesta de autoconocimiento, un mapa del comportamiento humano, un sistema dinámico de crecimiento personal.</p><h3>La importancia del autoconocimiento</h3><p>Desde la antigüedad se habla de la importancia del conocerse.</p><h3>¿Por qué es tan importante saber cómo soy?</h3><p>Porque no vemos el mundo como ES sino COMO SOMOS</p><p>Cada uno percibe la realidad a través de un filtro y con el <strong>Eneagrama</strong> detectamos con mayor claridad los distintos tipos de filtro.</p><p>El<strong> Eneagrama</strong> ayuda no sólo a saber cómo soy, sino que invita a descubrir cómo puedo llegar a ser. Y para eso ofrece caminos que ayudan a darse cuenta del “piloto automático” con el cual nos acostumbramos a vivir y reaccionar, y así poder elegir cómo responder a las circunstancias sabiendo que con cada respuesta vamos creando la vida que tenemos.</p><p>La grandeza del Eneagrama reside en su profundidad y sencillez a la vez. Es un idioma actitudinal ya que ayuda a comprender las actitudes de las personas, mejorando de esa manera la forma en que nos vinculamos.</p><img loading="lazy" src="/blog/significado-de-un-eneagrama-explicacion/formas-de-eneagrama-2.jpeg"/><p>El Eneagrama (enea=9, grama=dibujo) habla de 9 formas básicas de ser, 9 maneras de funcionar y estar en el mundo. Cada una de estas 9 tipologías es una compleja interrelación de cualidades, limitaciones, motivaciones, miedos, estrategias para sentirse seguro, desafíos, prioridades al percibir, creencias, maneras de vincularse con los demás, formas de relacionarse con el cuerpo, maneras de manifestar sentimientos, emociones preferidas y muchos otros aspectos.</p><p>Cada persona tiene estas 9 facetas dentro suyo, pero siente más familiaridad con una de ellas. Eso ayuda a saber cuáles son los dones que caracterizan a la persona, pero también adonde armó sus principales defensas obstaculizando su crecimiento.</p><p>Conocer la tipología predominante es recién el punto de partida de un viaje hacia nuestro interior. Un viaje en el cual se va descubriendo el verdadero ser y vamos soltando todo aquello que cubre nuestra esencia, a la vez que vamos despertando todos los atributos presentes en nosotros.</p><p>Al conocerme más, puedo decidir mejor, realizarme y sentirme plena, aceptarme y cuidarme, valorarme y ocupar mi lugar.</p><p>Se trata de saber quién uno es y despertar la confianza para animarse a serlo.</p><p><strong>AUTOR:</strong> Josefina Majdalani</p><p>Querés conocer mas sobre ENEAGRAMA</p><p><a href="/registro">Registrate</a> en <a href="/">www.mujeresxmas.com</a> y recibirás información de nuestra próximas actividades</p>', 2, '/blog/significado-de-un-eneagrama-explicacion/que-es-un-eneagrama.png', 'ENEAGRAMA – Una guía para acercarnos a nuestro interior', 'Mujeres x Más', '2021-03-05T15:40:20-03:00'::timestamptz),
  ('Venta Directa: ¿cómo se aplica en mi negocio?', 'emprendimientos-online-venta-directa', 'Según la definición de la WFDSA (World Federation of Direct Selling Asociations), la venta directa es un canal de distribución y comercialización de productos y servicios directamente a los consumidores.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"¿Qué es LA VENTA DIRECTA?"}]},{"type":"paragraph","content":[{"type":"text","text":"Según la definición de la WFDSA (World Federation of Direct Selling Asociations), la venta directa es un canal de distribución y comercialización de productos y servicios directamente a los consumidores."}]},{"type":"paragraph","content":[{"type":"text","text":"Esto implica que el producto / servicio se ofrece sin intermediacion alguna, por lo tanto la relacion con el cliente final es DIRECTA."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Cuáles son sus caracteristicas?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"La revendedora de manera independiente compra productos/ servicios a una o varias empresas que elija para luego revenderlos a consumidores finales"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"El contacto es directo entre la revendedora y su cliente"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Apoya su oferta y venta de los productos en un catalogo , material de soporte o demostracion en vivo"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Puede ser de uno o más niveles"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"EMPRENDEDORA Y VENTA DIRECTA"}]},{"type":"paragraph","content":[{"type":"text","text":"Muchas veces consideramos la venta directa como la acción por medio de la cual nos ofrecen productos de marcas de cosmética, cocina y otros servicios (ej. Avon, Essen, Amway). Estas empresas desarrollan venta directa en el modelo multinivel, sin embargo existen otros modelos."}]},{"type":"paragraph","content":[{"type":"text","text":"Todas nosotras podemos aplicar y de hecho lo hacemos, un modelo de venta directa para nuestros productos. Una emprendedora que ofrece sus servicios / productos en la localidad en la que reside y realiza una muestra de estos, características, condiciones, ventajas, etc a un tercero (posible cliente), esta realizando una VENTA DIRECTA."}]},{"type":"paragraph","content":[{"type":"text","text":"Le elección o no de este formato estará determinada por el volumen a comercializar, el alcance, la distribución, los costos y el precio final. Tal vez la venta indirecta será la opción o también la directa."}]},{"type":"paragraph","content":[{"type":"text","text":"En tanto , por otro lado, la posibilidad de integrar una red de venta directa multinivel nos permite acceder a una mayor oferta de productos ya que son producidos por terceros, no asumir ese costo de producción y crecer a partir de la intermediación en el canal. Esto nos demandará capacitación para la generación de potenciales compradores, su seguimiento y fidelización para que nuestros ingresos crezcan."}]},{"type":"paragraph","content":[{"type":"text","text":"Todas las opciones deben ser analizadas al momento de emprender y para ello, desde MUJERESXMAS queremos acompañarte y brindarte información precisa."}]},{"type":"paragraph","content":[{"type":"text","text":"Ingresá a "},{"type":"text","text":"www.mujeresxmas","marks":[{"type":"link","attrs":{"href":"/"}}]},{"type":"text","text":", resgistrate y conocé mas sobre venta directa"}]}]}'::jsonb, '<h2>¿Qué es LA VENTA DIRECTA?</h2><p>Según la definición de la WFDSA (World Federation of Direct Selling Asociations), la venta directa es un canal de distribución y comercialización de productos y servicios directamente a los consumidores.</p><p>Esto implica que el producto / servicio se ofrece sin intermediacion alguna, por lo tanto la relacion con el cliente final es DIRECTA.</p><p>¿Cuáles son sus caracteristicas?</p><ul><li><p>La revendedora de manera independiente compra productos/ servicios a una o varias empresas que elija para luego revenderlos a consumidores finales</p></li><li><p>El contacto es directo entre la revendedora y su cliente</p></li><li><p>Apoya su oferta y venta de los productos en un catalogo , material de soporte o demostracion en vivo</p></li><li><p>Puede ser de uno o más niveles</p></li></ul><h3>EMPRENDEDORA Y VENTA DIRECTA</h3><p>Muchas veces consideramos la venta directa como la acción por medio de la cual nos ofrecen productos de marcas de cosmética, cocina y otros servicios (ej. Avon, Essen, Amway). Estas empresas desarrollan venta directa en el modelo multinivel, sin embargo existen otros modelos.</p><p>Todas nosotras podemos aplicar y de hecho lo hacemos, un modelo de venta directa para nuestros productos. Una emprendedora que ofrece sus servicios / productos en la localidad en la que reside y realiza una muestra de estos, características, condiciones, ventajas, etc a un tercero (posible cliente), esta realizando una VENTA DIRECTA.</p><p>Le elección o no de este formato estará determinada por el volumen a comercializar, el alcance, la distribución, los costos y el precio final. Tal vez la venta indirecta será la opción o también la directa.</p><p>En tanto , por otro lado, la posibilidad de integrar una red de venta directa multinivel nos permite acceder a una mayor oferta de productos ya que son producidos por terceros, no asumir ese costo de producción y crecer a partir de la intermediación en el canal. Esto nos demandará capacitación para la generación de potenciales compradores, su seguimiento y fidelización para que nuestros ingresos crezcan.</p><p>Todas las opciones deben ser analizadas al momento de emprender y para ello, desde MUJERESXMAS queremos acompañarte y brindarte información precisa.</p><p>Ingresá a <a href="/">www.mujeresxmas</a>, resgistrate y conocé mas sobre venta directa</p>', 2, '/blog/emprendimientos-online-venta-directa/venda-directa.jpg', 'Venta Directa: ¿cómo se aplica en mi negocio?', 'Mujeres x Más', '2021-02-12T20:27:14-03:00'::timestamptz),
  ('¿Igualdad o equidad de género?', 'igualdad-de-genero', 'La igualdad de género es un concepto cada vez más presente en nuestras vidas. Los medios de comunicación, comentarios en grupos de trabajo y sociales, contactos en las redes y hasta en una charla con nuestros hijos o…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"La igualdad de género es un concepto cada vez más presente en nuestras vidas. Los medios de comunicación, comentarios en grupos de trabajo y sociales, contactos en las redes y hasta en una charla con nuestros hijos o familias son espacios de dialogo sobre este eje."}]},{"type":"paragraph","content":[{"type":"text","text":"Pero alguna vez te preguntaste ¿Qué significa exactamente? ¿Por qué se sigue reivindicando la igualdad de género si todas las leyes reconocen los mismos derechos a hombres y mujeres? ¿Qué diferencia hay entre igualdad y equidad?"}]},{"type":"paragraph","content":[{"type":"text","text":"Hoy queremos acercarte herramientas y definiciones que te ayuden a responder a estos interrogantes."}]},{"type":"paragraph","content":[{"type":"text","text":"Según Naciones Unidas, la igualdad de género se refiere a “la igualdad de derechos, responsabilidades y oportunidades de las mujeres y los hombres, y las niñas y los niños”. Por lo tanto, el sexo biológico nunca será un determinante para los derechos, oportunidades y responsabilidades que podamos tener a lo largo de la vida."},{"type":"hardBreak"},{"type":"text","text":"La igualdad de género constituye un principio jurídico universal, mientras que la equidad de género introduce además un componente ético y el concepto de la compensación de condiciones, para asegurar una igualdad real."}]},{"type":"image","attrs":{"src":"/blog/igualdad-de-genero/portada-audio2.png","alt":null,"title":null}},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"MARCO INTERNACIONAL PARA LA IGUALDAD DE GENERO"}]},{"type":"paragraph","content":[{"type":"text","text":"Aunque las cuestiones de género llevan años en la agenda internacional, es un hecho que las mujeres y las niñas, sufren discriminación y todo tipo de violencia por el simple hecho de haber nacido mujer. El informe de la OCDE “Perseguir la igualdad de género: una batalla cuesta arriba” , deja expuesta esta situación cuando asegura que ningún país en el mundo, ni siquiera aquellos más igualitarios, ha alcanzado aún la igualdad."}]},{"type":"paragraph","content":[{"type":"text","text":"Por su lado la ONU incorpora en el marco de los Objetivos de Desarrollo Sostenible 2030, lo siguiente: Objetivo número 5 “lograr la igualdad entre los géneros y empoderar a todas las mujeres y niñas”."}]},{"type":"paragraph","content":[{"type":"text","text":"El Foro Económico Mundial (WEF – 2017) asegura que para que se registre el cierre de la brecha existente se requerirán al menos 100 años ."}]},{"type":"paragraph","content":[{"type":"text","text":"INDICADORES"}]},{"type":"paragraph","content":[{"type":"text","text":"Existen cinco (5) indicadores fundamentales para medir la brecha de genero existente en una sociedad:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Participación política","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"type":"text","text":"La participación política de las mujeres es una de las asignaturas pendientes en todo el mundo. Actualmente el país con mayor igualdad de representación de ambos sexos en su Parlamento es Ruanda, con un 64% de mujeres diputadas; le sigue Bolivia, uno de los países donde Ayuda en Acción trabaja, con más del 52% de mujeres diputadas."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Acceso a la educación","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"type":"text","text":"Un tercio de los países en desarrollo aún no han logrado paridad de género en el acceso a la enseñanza primaria, pese al avance que se dio gracias a los Objetivos del Milenio (2000-2015)."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Acceso al mercado de trabajo y desigualdad salarial","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"type":"text","text":"Según Naciones Unidas, existe una diferencia salarial del 24% entre mujeres y hombres en todo el mundo. El Informe del Foro Económico Mundial reconoce que, si hablamos de igualdad de género en el ámbito laboral, si continúa la tendencia actual, llegaremos a conseguirla en el año 2234."}]},{"type":"paragraph","content":[{"type":"text","text":"4. Violencia en cualquiera de sus formas","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"type":"text","text":"La violencia en cualquiera de sus formas alcanza un porcentaje alarmante. Las cifras que proporciona Naciones Unidas hablan de que el 35% de mujeres en todo el mundo han sufrido violencia física y/o sexual por parte de sus parejas."}]},{"type":"paragraph","content":[{"type":"text","text":"5. Marco normativo – legislación","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"type":"text","text":"Hasta 2016, aún había 52 países en el mundo en el que la igualdad de derechos y deberes entre hombres y mujeres no estaban reconocidos en sus Constituciones. La existencia de un marco jurídico es fundamental para poder trabajar en la condena de estas prácticas y favorecer la equidad e igualdad de género"}]},{"type":"paragraph","content":[{"type":"text","text":"¿COMO PODEMOS COLABORAR PARA ACHICAR ESTA BRECHA?"}]},{"type":"paragraph","content":[{"type":"text","text":"Desde la iniciativa "},{"type":"text","text":"MUJERESXMAS","marks":[{"type":"bold"}]},{"type":"text","text":", trabajamos en la generación de acciones que contribuyan al empoderamiento económico de las mujeres como vector para el desarrollo profesional y personal, co-creando programas de alto impacto en conjunto con actores del mundo público, privado y tercer sector, nacionales e internacionales, que garanticen el respeto de los Derechos Humanos y la igualdad de oportunidades entre varones y mujeres."},{"type":"hardBreak"},{"type":"text","text":"Trabajar en políticas de inclusión para que las mujeres accedan o completen su educación, se conviertan en emprendedoras que generen ingresos para sus familias, reciban los tratamientos médicos que necesitan, conozcan y ejerzan sus derechos."}]},{"type":"paragraph","content":[{"type":"text","text":"Si sos mujer, podés trabajar por la igualdad de género implicándote directamente en asociaciones y organizaciones que trabajan por la igualdad entre hombres y mujeres en todos los ámbitos de la vida."},{"type":"hardBreak"},{"type":"text","text":"Si te desempeñas en puestos de responsabilidad pública, podés trabajar en políticas que fomenten la igualdad y la inclusión. Si tu trabajo se relaciona con la educación, es el lugar indicado para la transmisión de valores que se relacionan con la libertad, igualdad e inclusión."},{"type":"hardBreak"},{"type":"text","text":"Conseguir que exista igualdad de género no es una tarea imposible, pero requiere de la implicación de toda la ciudadanía. Seas quien seas, podés sumarte para que muchas mujeres y niñas dejen de ser invisibles."}]},{"type":"paragraph","content":[{"type":"text","text":"Te invitamos a ingresar al siguiente link donde El Foro Económico Mundial (WEF) posee notas de interés relacionadas con la temática:"}]},{"type":"paragraph","content":[{"type":"text","text":"https://es.weforum.org/agenda/archive/gender-parity","marks":[{"type":"link","attrs":{"href":"https://es.weforum.org/agenda/archive/gender-parity"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Asesoramiento: Lic. Tamara López, Licenciada en Psicología.","marks":[{"type":"link","attrs":{"href":"/"}}]}]}]}'::jsonb, '<p>La igualdad de género es un concepto cada vez más presente en nuestras vidas. Los medios de comunicación, comentarios en grupos de trabajo y sociales, contactos en las redes y hasta en una charla con nuestros hijos o familias son espacios de dialogo sobre este eje.</p><p>Pero alguna vez te preguntaste ¿Qué significa exactamente? ¿Por qué se sigue reivindicando la igualdad de género si todas las leyes reconocen los mismos derechos a hombres y mujeres? ¿Qué diferencia hay entre igualdad y equidad?</p><p>Hoy queremos acercarte herramientas y definiciones que te ayuden a responder a estos interrogantes.</p><p>Según Naciones Unidas, la igualdad de género se refiere a “la igualdad de derechos, responsabilidades y oportunidades de las mujeres y los hombres, y las niñas y los niños”. Por lo tanto, el sexo biológico nunca será un determinante para los derechos, oportunidades y responsabilidades que podamos tener a lo largo de la vida.<br/>La igualdad de género constituye un principio jurídico universal, mientras que la equidad de género introduce además un componente ético y el concepto de la compensación de condiciones, para asegurar una igualdad real.</p><img loading="lazy" src="/blog/igualdad-de-genero/portada-audio2.png"/><h3>MARCO INTERNACIONAL PARA LA IGUALDAD DE GENERO</h3><p>Aunque las cuestiones de género llevan años en la agenda internacional, es un hecho que las mujeres y las niñas, sufren discriminación y todo tipo de violencia por el simple hecho de haber nacido mujer. El informe de la OCDE “Perseguir la igualdad de género: una batalla cuesta arriba” , deja expuesta esta situación cuando asegura que ningún país en el mundo, ni siquiera aquellos más igualitarios, ha alcanzado aún la igualdad.</p><p>Por su lado la ONU incorpora en el marco de los Objetivos de Desarrollo Sostenible 2030, lo siguiente: Objetivo número 5 “lograr la igualdad entre los géneros y empoderar a todas las mujeres y niñas”.</p><p>El Foro Económico Mundial (WEF – 2017) asegura que para que se registre el cierre de la brecha existente se requerirán al menos 100 años .</p><p>INDICADORES</p><p>Existen cinco (5) indicadores fundamentales para medir la brecha de genero existente en una sociedad:</p><p><strong>1. Participación política</strong><br/>La participación política de las mujeres es una de las asignaturas pendientes en todo el mundo. Actualmente el país con mayor igualdad de representación de ambos sexos en su Parlamento es Ruanda, con un 64% de mujeres diputadas; le sigue Bolivia, uno de los países donde Ayuda en Acción trabaja, con más del 52% de mujeres diputadas.</p><p><strong>2. Acceso a la educación</strong><br/>Un tercio de los países en desarrollo aún no han logrado paridad de género en el acceso a la enseñanza primaria, pese al avance que se dio gracias a los Objetivos del Milenio (2000-2015).</p><p><strong>3. Acceso al mercado de trabajo y desigualdad salarial</strong><br/>Según Naciones Unidas, existe una diferencia salarial del 24% entre mujeres y hombres en todo el mundo. El Informe del Foro Económico Mundial reconoce que, si hablamos de igualdad de género en el ámbito laboral, si continúa la tendencia actual, llegaremos a conseguirla en el año 2234.</p><p><strong>4. Violencia en cualquiera de sus formas</strong><br/>La violencia en cualquiera de sus formas alcanza un porcentaje alarmante. Las cifras que proporciona Naciones Unidas hablan de que el 35% de mujeres en todo el mundo han sufrido violencia física y/o sexual por parte de sus parejas.</p><p><strong>5. Marco normativo – legislación</strong><br/>Hasta 2016, aún había 52 países en el mundo en el que la igualdad de derechos y deberes entre hombres y mujeres no estaban reconocidos en sus Constituciones. La existencia de un marco jurídico es fundamental para poder trabajar en la condena de estas prácticas y favorecer la equidad e igualdad de género</p><p>¿COMO PODEMOS COLABORAR PARA ACHICAR ESTA BRECHA?</p><p>Desde la iniciativa <strong>MUJERESXMAS</strong>, trabajamos en la generación de acciones que contribuyan al empoderamiento económico de las mujeres como vector para el desarrollo profesional y personal, co-creando programas de alto impacto en conjunto con actores del mundo público, privado y tercer sector, nacionales e internacionales, que garanticen el respeto de los Derechos Humanos y la igualdad de oportunidades entre varones y mujeres.<br/>Trabajar en políticas de inclusión para que las mujeres accedan o completen su educación, se conviertan en emprendedoras que generen ingresos para sus familias, reciban los tratamientos médicos que necesitan, conozcan y ejerzan sus derechos.</p><p>Si sos mujer, podés trabajar por la igualdad de género implicándote directamente en asociaciones y organizaciones que trabajan por la igualdad entre hombres y mujeres en todos los ámbitos de la vida.<br/>Si te desempeñas en puestos de responsabilidad pública, podés trabajar en políticas que fomenten la igualdad y la inclusión. Si tu trabajo se relaciona con la educación, es el lugar indicado para la transmisión de valores que se relacionan con la libertad, igualdad e inclusión.<br/>Conseguir que exista igualdad de género no es una tarea imposible, pero requiere de la implicación de toda la ciudadanía. Seas quien seas, podés sumarte para que muchas mujeres y niñas dejen de ser invisibles.</p><p>Te invitamos a ingresar al siguiente link donde El Foro Económico Mundial (WEF) posee notas de interés relacionadas con la temática:</p><p><a target="_blank" rel="noopener noreferrer" href="https://es.weforum.org/agenda/archive/gender-parity">https://es.weforum.org/agenda/archive/gender-parity</a></p><p><a href="/">Asesoramiento: Lic. Tamara López, Licenciada en Psicología.</a></p>', 4, '/blog/igualdad-de-genero/exsxmyqxqvf3pjeudyu62acq5i.jpg', '¿Igualdad o equidad de género?', 'Mujeres x Más', '2020-10-11T15:51:38-03:00'::timestamptz),
  ('Guía de género para empresas: Hacia la paridad', 'guia-de-genero-para-empresas-hacia-la-paridad', 'La Red de Empresas por la Diversidad (R.E.D) a través de una iniciativa colectiva conformada por organizaciones empresariales, académicas y civiles, de la Escuela de Negocios de la Universidad Torcuato Di Tella nos…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"La Red de Empresas por la Diversidad ","marks":[{"type":"bold"}]},{"type":"text","text":"(R.E.D) a través de una iniciativa colectiva conformada "},{"type":"text","text":"por","marks":[{"type":"italic"}]},{"type":"text","text":" organizaciones empresariales, académicas y civiles, de la Escuela de "},{"type":"text","text":"Negocios","marks":[{"type":"italic"}]},{"type":"text","text":" de la Universidad Torcuato Di Tella nos invita a conocer una guía de género para empresas planteando un enfoque de igualdad de género y promoción de tanto nuevas feminidades como masculinidades."}]},{"type":"paragraph","content":[{"type":"text","text":"El objetivo de esta guía es proveer una herramienta que le permita a las empresas conocer las ventajas de trabajar este tema; proveer una perspectiva de género para cada proceso de recursos humanos; dilucidar las principales barreras a las cuales se enfrentan las mujeres en el ámbito corporativo; proponer una serie de prácticas de igualdad de género y desarrollo de carrera tanto para las grandes empresas como para las pequeñas y medianas empresas."}]},{"type":"paragraph","content":[{"type":"text","text":"A medida que nos adentramos en sus diferentes párrafos descubrimos la necesidad de trabajar en base a la construcción de una cultura organizacional con perspectiva de género. Las organizaciones empresariales son actores sociales que pueden desempeñar un rol fundamental en la construcción de igualdad, trabajando desde sus “micro sociedades” entendiendo que las organizaciones funcionan bajo ciertos órdenes sociales, con sistemas de gobernanza, con jerarquías, con distribución de responsabilidades y creación de oportunidades, que dan espacio para diseñar e instaurar nuevas reglas de juego de estos sistemas, que pueden servir como modelo inspirador para la sociedad en su conjunto. Para hacer esta significativa contribución desde el ámbito empresarial, es necesario instalar una nueva cultura organizacional."}]},{"type":"paragraph","content":[{"type":"text","text":"El respeto por la igualdad de género y el principio de tolerancia cero a todas las formas de violencia y discriminación deberían constituirse en un valor organizacional y, por lo tanto, uno de los pilares de la cultura de la empresa. Es fundamental que el código de ética, las políticas y los procedimientos adopten una perspectiva de género para asegurar ambientes de trabajo equitativos y que brinden igualdad de oportunidades. Para ello, es fundamental que se incluya dentro del código de ética una cláusula, en caso de no contar con la misma, que explicite el compromiso con la igualdad de género y la no discriminación, para mantener espacios de trabajo libres de acoso y violencia."}]},{"type":"paragraph","content":[{"type":"text","text":"El compromiso con la equidad de género puede institucionalizarse como una política específica, o ser parte de una política más amplia de equidad de oportunidades en el empleo para la inclusión de diferentes poblaciones. Este compromiso explícito con la igualdad de género debiera ser comunicado tanto interna como externamente, sostenidamente en el tiempo, incluyendo la cadena de valor y la comunidad corporativa. Incluso, generaría mayor impacto crear un lema o eslogan, a través del cual la compañía pusiera de manifiesto su compromiso."}]},{"type":"paragraph","content":[{"type":"text","text":"Agenda estratégica y dimensiones de la cultura.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Para que el cambio cultural suceda, es fundamental, por un lado, incluir la diversidad de género y la igualdad de oportunidades en la agenda estratégica de la organización, y, por otro lado, que se trabaje con perspectiva de género en las dimensiones que generan cultura, que se desarrollan a continuación, de manera de promover este cambio. Por otra parte, se debe adoptar la perspectiva de género de forma transversal a todas las áreas o procesos, y las acciones deben ser sostenidas a través del tiempo para que el cambio se haga efectivo."}]},{"type":"paragraph","content":[{"type":"text","text":"Se identifican cuatro dimensiones que generan cultura, por las cuales se incluye o excluye a las mujeres, y por las cuales se fomenta la paridad y la igualdad de oportunidades, o la desigualdad de género en el interior de la organización:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Las prácticas formales de trabajo y relación entre los miembros de una organización, basadas en un conjunto generalmente escrito de reglas, procedimientos y estructuras, que tienen efecto real en el empoderamiento o desestima de las mujeres, tales como la visibilización y el fomento de las nuevas masculinidades, y las parentalidades corresponsables."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Las prácticas informales, que refieren a la interacción cotidiana y no están explicitadas en las reglas y normas de una organización, que tienen como efecto real la buena convivencia en la diversidad o bien puede dar lugar a la descalificación de la autoridad femenina, la violencia o acoso, entre otros hábitos que obstaculizan el bienestar y desarrollo de las mujeres."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Los símbolos e imágenes utilizados, que pueden reforzar los modelos mentales, así como los roles y estereotipos de género, o bien transmitir mensajes a favor de la diversidad e igualdad de género."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"En general, los cambios culturales generan tensiones y resistencias, por eso, es importante transversalizar la perspectiva de género en todas las dimensiones que generan cultura, para que operen de forma sistémica y cada posibilidad de resistencia sea rápidamente desarmada por alguna de las dimensiones operantes."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Se debe romper con la idea de que las cuestiones de género son temas que conciernen solamente a las mujeres. La responsabilidad del cambio cultural recae casi exclusivamente en ellas, cuando para lograrlo es igual de importante el trabajo con los varones. En este sentido, se debe trabajar activamente en potenciar la participación de los varones en todos los espacios y actividades provistas por la compañía, donde se reflexione y se trabaje sobre la masculinidad, la feminidad y la igualdad de género, la corresponsabilidad en las tareas domésticas y en las del cuidado, la violencia, para romper el statu quo y emprender el camino hacia la igualdad de oportunidades en las organizaciones."}]},{"type":"paragraph","content":[{"type":"text","text":"“Comunicación con perspectiva de género”.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"El lenguaje juega un rol fundamental en la construcción de la cultura y de las identidades; a través del lenguaje, se construyen imágenes de las personas y grupos sociales, y se transmiten y refuerzan los estereotipos y roles de género, reproduciendo las relaciones asimétricas e inequitativas que se dan en la sociedad. El lenguaje, tal como se vive en la actualidad, contribuye a la reproducción del paradigma patriarcal heteronormativo excluyente y, por ende, cada persona puede reproducir expresiones discriminatorias, estereotipadas o estigmatizantes, no solo en el uso del lenguaje, sino también a través de las relaciones sociales, que se manifiesta a través del lenguaje no verbal y las actitudes. En las organizaciones, se puede implementar una serie de medidas para adoptar una comunicación audiovisual y un uso del lenguaje —oral y escrito— con perspectiva de género, que promueva un trato igualitario y respetuoso de la dignidad de las mujeres y los varones. Es importante mencionar que su uso dependerá del tipo de formato que adquiera la comunicación. Se debe prestar atención a que el lenguaje visibilice los géneros y la diversidad de género a lo largo de todos los documentos, sin que se vaya diluyendo a medida que transcurre la lectura o el discurso."}]},{"type":"paragraph","content":[{"type":"text","text":"Hacia la paridad.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"La paridad de género es el objetivo final, hacia donde se alinean los esfuerzos y se emplazan los componentes de la estrategia de género. Una estrategia explícita para lograr la paridad es fijar un target u objetivo que puede ser tanto en toda la pirámide organizacional como en algún escalafón jerárquico o área, como se explicó con anterioridad. Este target fuerza la paridad de modo acelerado, a diferencia del resto de los componentes de la estrategia, los cuales promueven la paridad de una forma más orgánica. Estos no son excluyentes entre sí, por el contario, cuando se fija un target es fundamental que se acompañe del resto de los componentes de la estrategia que se describen a continuación, ya que es de ese modo que se alcanza una paridad efectiva."}]},{"type":"paragraph","content":[{"type":"text","text":"Los desafíos pendientes y reflexiones finales.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Más allá del grado de avance en el que se encuentren actualmente las empresas respecto a estos temas, es necesario contar con equipos de liderazgo diversos y capaces de generar perspectivas distintas para enfrentar los complejos problemas que se presentan en el contexto empresarial actual. Para esto hay que trabajar en el desarrollo de equipos diversos. En este sentido, se celebran las iniciativas de diversidad implementadas, que acompañan el contexto histórico, consolidando el proceso de cambio cultural, que ya no puede ser ignorado por quienes gestionan las organizaciones, ya que lograr la paridad de género en los espacios de trabajo no solo es la opción más justa, sino también la más beneficiosa para el negocio."}]},{"type":"paragraph","content":[{"type":"text","text":"El principal desafío de las empresas radica en romper con el statu quo, basado en las relaciones de poder asimétricas que existen entre los géneros, que han asegurado a los varones el monopolio del poder, dejando en desventaja al género femenino. La igualdad existirá solo cuando los niveles de poder e influencia estén igualmente distribuidos."}]},{"type":"paragraph","content":[{"type":"text","text":"Las empresas como verdaderas promotoras de la paridad de género.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"La paridad de género implica un cambio cultural que no es un resultado que se pueda esperar a través de una acción puntual y concreta, precisamente por la necesidad de modificar comportamientos anclados en factores imperceptibles o invisibles, como sesgos inconscientes, estereotipos y normas sociales, lo que demanda un trabajo profundo y sostenido. Como se ha desarrollado en esta guía, la paridad de género supone una serie de beneficios para el desarrollo de los países, las organizaciones y las sociedades en general. En este sentido, la R.E.D. Invita a las empresas a emprender el recorrido de la paridad de género con conciencia de la incidencia que tienen, con el espíritu de un verdadero actor de cambio."}]},{"type":"paragraph","content":[{"type":"text","text":"Para acceder a la guía completa están invitadas a ingresar al siguiente link:"}]},{"type":"paragraph","content":[{"type":"text","text":"R.E.D. Di Tella (2017). Guía de genero para empresas. Hacia la paridad","marks":[{"type":"link","attrs":{"href":"https://mujeresxmas.com/wp-content/uploads/2020/09/R.E.D.-Di-Tella-2017.-Guía-de-genero-para-empresas.-Hacia-la-paridad.pdf"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Agradecemos a "},{"type":"text","text":"Sonia Agnese","marks":[{"type":"bold"}]},{"type":"text","text":" por su trabajo y colaboración."}]}]}'::jsonb, '<p><strong>La Red de Empresas por la Diversidad </strong>(R.E.D) a través de una iniciativa colectiva conformada <em>por</em> organizaciones empresariales, académicas y civiles, de la Escuela de <em>Negocios</em> de la Universidad Torcuato Di Tella nos invita a conocer una guía de género para empresas planteando un enfoque de igualdad de género y promoción de tanto nuevas feminidades como masculinidades.</p><p>El objetivo de esta guía es proveer una herramienta que le permita a las empresas conocer las ventajas de trabajar este tema; proveer una perspectiva de género para cada proceso de recursos humanos; dilucidar las principales barreras a las cuales se enfrentan las mujeres en el ámbito corporativo; proponer una serie de prácticas de igualdad de género y desarrollo de carrera tanto para las grandes empresas como para las pequeñas y medianas empresas.</p><p>A medida que nos adentramos en sus diferentes párrafos descubrimos la necesidad de trabajar en base a la construcción de una cultura organizacional con perspectiva de género. Las organizaciones empresariales son actores sociales que pueden desempeñar un rol fundamental en la construcción de igualdad, trabajando desde sus “micro sociedades” entendiendo que las organizaciones funcionan bajo ciertos órdenes sociales, con sistemas de gobernanza, con jerarquías, con distribución de responsabilidades y creación de oportunidades, que dan espacio para diseñar e instaurar nuevas reglas de juego de estos sistemas, que pueden servir como modelo inspirador para la sociedad en su conjunto. Para hacer esta significativa contribución desde el ámbito empresarial, es necesario instalar una nueva cultura organizacional.</p><p>El respeto por la igualdad de género y el principio de tolerancia cero a todas las formas de violencia y discriminación deberían constituirse en un valor organizacional y, por lo tanto, uno de los pilares de la cultura de la empresa. Es fundamental que el código de ética, las políticas y los procedimientos adopten una perspectiva de género para asegurar ambientes de trabajo equitativos y que brinden igualdad de oportunidades. Para ello, es fundamental que se incluya dentro del código de ética una cláusula, en caso de no contar con la misma, que explicite el compromiso con la igualdad de género y la no discriminación, para mantener espacios de trabajo libres de acoso y violencia.</p><p>El compromiso con la equidad de género puede institucionalizarse como una política específica, o ser parte de una política más amplia de equidad de oportunidades en el empleo para la inclusión de diferentes poblaciones. Este compromiso explícito con la igualdad de género debiera ser comunicado tanto interna como externamente, sostenidamente en el tiempo, incluyendo la cadena de valor y la comunidad corporativa. Incluso, generaría mayor impacto crear un lema o eslogan, a través del cual la compañía pusiera de manifiesto su compromiso.</p><p><strong>Agenda estratégica y dimensiones de la cultura.</strong></p><p>Para que el cambio cultural suceda, es fundamental, por un lado, incluir la diversidad de género y la igualdad de oportunidades en la agenda estratégica de la organización, y, por otro lado, que se trabaje con perspectiva de género en las dimensiones que generan cultura, que se desarrollan a continuación, de manera de promover este cambio. Por otra parte, se debe adoptar la perspectiva de género de forma transversal a todas las áreas o procesos, y las acciones deben ser sostenidas a través del tiempo para que el cambio se haga efectivo.</p><p>Se identifican cuatro dimensiones que generan cultura, por las cuales se incluye o excluye a las mujeres, y por las cuales se fomenta la paridad y la igualdad de oportunidades, o la desigualdad de género en el interior de la organización:</p><ul><li><p>Las prácticas formales de trabajo y relación entre los miembros de una organización, basadas en un conjunto generalmente escrito de reglas, procedimientos y estructuras, que tienen efecto real en el empoderamiento o desestima de las mujeres, tales como la visibilización y el fomento de las nuevas masculinidades, y las parentalidades corresponsables.</p></li><li><p>Las prácticas informales, que refieren a la interacción cotidiana y no están explicitadas en las reglas y normas de una organización, que tienen como efecto real la buena convivencia en la diversidad o bien puede dar lugar a la descalificación de la autoridad femenina, la violencia o acoso, entre otros hábitos que obstaculizan el bienestar y desarrollo de las mujeres.</p></li><li><p>Los símbolos e imágenes utilizados, que pueden reforzar los modelos mentales, así como los roles y estereotipos de género, o bien transmitir mensajes a favor de la diversidad e igualdad de género.</p></li><li><p>En general, los cambios culturales generan tensiones y resistencias, por eso, es importante transversalizar la perspectiva de género en todas las dimensiones que generan cultura, para que operen de forma sistémica y cada posibilidad de resistencia sea rápidamente desarmada por alguna de las dimensiones operantes.</p></li></ul><p>Se debe romper con la idea de que las cuestiones de género son temas que conciernen solamente a las mujeres. La responsabilidad del cambio cultural recae casi exclusivamente en ellas, cuando para lograrlo es igual de importante el trabajo con los varones. En este sentido, se debe trabajar activamente en potenciar la participación de los varones en todos los espacios y actividades provistas por la compañía, donde se reflexione y se trabaje sobre la masculinidad, la feminidad y la igualdad de género, la corresponsabilidad en las tareas domésticas y en las del cuidado, la violencia, para romper el statu quo y emprender el camino hacia la igualdad de oportunidades en las organizaciones.</p><p><strong>“Comunicación con perspectiva de género”.</strong></p><p>El lenguaje juega un rol fundamental en la construcción de la cultura y de las identidades; a través del lenguaje, se construyen imágenes de las personas y grupos sociales, y se transmiten y refuerzan los estereotipos y roles de género, reproduciendo las relaciones asimétricas e inequitativas que se dan en la sociedad. El lenguaje, tal como se vive en la actualidad, contribuye a la reproducción del paradigma patriarcal heteronormativo excluyente y, por ende, cada persona puede reproducir expresiones discriminatorias, estereotipadas o estigmatizantes, no solo en el uso del lenguaje, sino también a través de las relaciones sociales, que se manifiesta a través del lenguaje no verbal y las actitudes. En las organizaciones, se puede implementar una serie de medidas para adoptar una comunicación audiovisual y un uso del lenguaje —oral y escrito— con perspectiva de género, que promueva un trato igualitario y respetuoso de la dignidad de las mujeres y los varones. Es importante mencionar que su uso dependerá del tipo de formato que adquiera la comunicación. Se debe prestar atención a que el lenguaje visibilice los géneros y la diversidad de género a lo largo de todos los documentos, sin que se vaya diluyendo a medida que transcurre la lectura o el discurso.</p><p><strong>Hacia la paridad.</strong></p><p>La paridad de género es el objetivo final, hacia donde se alinean los esfuerzos y se emplazan los componentes de la estrategia de género. Una estrategia explícita para lograr la paridad es fijar un target u objetivo que puede ser tanto en toda la pirámide organizacional como en algún escalafón jerárquico o área, como se explicó con anterioridad. Este target fuerza la paridad de modo acelerado, a diferencia del resto de los componentes de la estrategia, los cuales promueven la paridad de una forma más orgánica. Estos no son excluyentes entre sí, por el contario, cuando se fija un target es fundamental que se acompañe del resto de los componentes de la estrategia que se describen a continuación, ya que es de ese modo que se alcanza una paridad efectiva.</p><p><strong>Los desafíos pendientes y reflexiones finales.</strong></p><p>Más allá del grado de avance en el que se encuentren actualmente las empresas respecto a estos temas, es necesario contar con equipos de liderazgo diversos y capaces de generar perspectivas distintas para enfrentar los complejos problemas que se presentan en el contexto empresarial actual. Para esto hay que trabajar en el desarrollo de equipos diversos. En este sentido, se celebran las iniciativas de diversidad implementadas, que acompañan el contexto histórico, consolidando el proceso de cambio cultural, que ya no puede ser ignorado por quienes gestionan las organizaciones, ya que lograr la paridad de género en los espacios de trabajo no solo es la opción más justa, sino también la más beneficiosa para el negocio.</p><p>El principal desafío de las empresas radica en romper con el statu quo, basado en las relaciones de poder asimétricas que existen entre los géneros, que han asegurado a los varones el monopolio del poder, dejando en desventaja al género femenino. La igualdad existirá solo cuando los niveles de poder e influencia estén igualmente distribuidos.</p><p><strong>Las empresas como verdaderas promotoras de la paridad de género.</strong></p><p>La paridad de género implica un cambio cultural que no es un resultado que se pueda esperar a través de una acción puntual y concreta, precisamente por la necesidad de modificar comportamientos anclados en factores imperceptibles o invisibles, como sesgos inconscientes, estereotipos y normas sociales, lo que demanda un trabajo profundo y sostenido. Como se ha desarrollado en esta guía, la paridad de género supone una serie de beneficios para el desarrollo de los países, las organizaciones y las sociedades en general. En este sentido, la R.E.D. Invita a las empresas a emprender el recorrido de la paridad de género con conciencia de la incidencia que tienen, con el espíritu de un verdadero actor de cambio.</p><p>Para acceder a la guía completa están invitadas a ingresar al siguiente link:</p><p><a target="_blank" rel="noopener noreferrer" href="https://mujeresxmas.com/wp-content/uploads/2020/09/R.E.D.-Di-Tella-2017.-Guía-de-genero-para-empresas.-Hacia-la-paridad.pdf">R.E.D. Di Tella (2017). Guía de genero para empresas. Hacia la paridad</a></p><p>Agradecemos a <strong>Sonia Agnese</strong> por su trabajo y colaboración.</p>', 8, '/blog/guia-de-genero-para-empresas-hacia-la-paridad/red-2017-02-pdf-1.jpg', 'Guía de género para empresas: Hacia la paridad', 'Mujeres x Más', '2020-09-14T21:30:09-03:00'::timestamptz),
  ('Inclusión financiera: ¿Qué es en realidad y cómo nos afecta como mujeres?', 'inclusion-financiera-mujeres', 'Mucho se habla en la actualidad de la inclusión financiera pero la verdad es que poco se conoce de la realidad de este concepto.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"¿Qué es la inclusión financiera?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Mucho se habla en la actualidad de la inclusión financiera pero la verdad es que poco se conoce de la realidad de este concepto."}]},{"type":"paragraph","content":[{"type":"text","text":"Una de las definiciones más completas es la que formuló la "},{"type":"text","text":"Organización para la Cooperación y el Desarrollo Económico","marks":[{"type":"bold"},{"type":"link","attrs":{"href":"https://es.wikipedia.org/wiki/Organizaci%C3%B3n_para_la_Cooperaci%C3%B3n_y_el_Desarrollo_Econ%C3%B3micos"}}]},{"type":"text","text":" (OCDE), ","marks":[{"type":"bold"}]},{"type":"text","text":"para quien la inclusión financiera es:"}]},{"type":"paragraph","content":[{"type":"text","text":"“El proceso de promoción de un acceso asequible, oportuno y adecuado a una amplia gama de servicios y productos financieros regulados y la ampliación de su uso hacia todos los segmentos de la sociedad mediante la aplicación de enfoques innovadores hechos a la medida, incluyendo actividades de sensibilización y educación financiera con el objetivo de promover tanto el bienestar financiero como la inclusión económica y social”.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Como podemos observar esta definición es MULTIDIMENSIONAL, ya que involucra tanto la oferta de la demanda de servicios y conceptos novedosos como:"}]},{"type":"paragraph","content":[{"type":"text","text":"Acceso:","marks":[{"type":"bold"}]},{"type":"text","text":" Grado en el que consumidores nuevos o desatendidos pueden obtener productos o servicios financieros a un precio asequible."}]},{"type":"paragraph","content":[{"type":"text","text":"Uso:","marks":[{"type":"bold"}]},{"type":"text","text":" Regularidad y frecuencia de utilización de servicios financieros de forma pertinente."}]},{"type":"paragraph","content":[{"type":"text","text":"Calidad:","marks":[{"type":"bold"}]},{"type":"text","text":" Grado de satisfacción de las necesidades de los clientes con servicios ofrecidos por los mercados."}]},{"type":"paragraph","content":[{"type":"text","text":"Bienestar financiero: ","marks":[{"type":"bold"}]},{"type":"text","text":"Adecuado manejo y control de la estabilidad financiera, logro de objetivos financieros y de generación de ahorros para eventualidades."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"¿Cómo nos beneficia la inclusión financiera?"}]},{"type":"paragraph","content":[{"type":"text","text":"Podemos enumerar algunos de los principales beneficios del sistema de inclusión financiera:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Contribuir a la formalización laboral, y así hacer efectivos derechos como salud y seguridad social.","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Afirmar el derecho del trabajador a elegir dónde y cómo cobrar por los servicios que comercialice o desarrolle.","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Propiciar la equidad.","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mejorar la seguridad de ciudadanos y comerciantes para sus transacciones.","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Propiciar la transparencia y el control.","marks":[{"type":"bold"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"¿Qué es un servicio financiero?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Los servicios financieros son el conjunto de servicios prestados por un grupo de entidades financieras que operan en el país o en jurisdicciones, como los bancos, las cooperativas de crédito, aseguradoras, mutualidades de previsión, agencias y sociedades de bolsa, etc."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Cómo podemos alcanzar una mayor inclusión financiera?","marks":[{"type":"bold"}]}]},{"type":"image","attrs":{"src":"/blog/inclusion-financiera-mujeres/grafico-11.jpg","alt":"inclusion financiera","title":null}},{"type":"paragraph","content":[{"type":"text","text":"inclusion financiera","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Asesoramiento: "},{"type":"text","text":"Karina G. Giusti, Mag. en Dirección de Empresas.","marks":[{"type":"link","attrs":{"href":"/"}}]}]}]}'::jsonb, '<p><strong>¿Qué es la inclusión financiera?</strong></p><p>Mucho se habla en la actualidad de la inclusión financiera pero la verdad es que poco se conoce de la realidad de este concepto.</p><p>Una de las definiciones más completas es la que formuló la <a target="_blank" rel="noopener noreferrer" href="https://es.wikipedia.org/wiki/Organizaci%C3%B3n_para_la_Cooperaci%C3%B3n_y_el_Desarrollo_Econ%C3%B3micos"><strong>Organización para la Cooperación y el Desarrollo Económico</strong></a><strong> (OCDE), </strong>para quien la inclusión financiera es:</p><p><em>“El proceso de promoción de un acceso asequible, oportuno y adecuado a una amplia gama de servicios y productos financieros regulados y la ampliación de su uso hacia todos los segmentos de la sociedad mediante la aplicación de enfoques innovadores hechos a la medida, incluyendo actividades de sensibilización y educación financiera con el objetivo de promover tanto el bienestar financiero como la inclusión económica y social”.</em></p><p>Como podemos observar esta definición es MULTIDIMENSIONAL, ya que involucra tanto la oferta de la demanda de servicios y conceptos novedosos como:</p><p><strong>Acceso:</strong> Grado en el que consumidores nuevos o desatendidos pueden obtener productos o servicios financieros a un precio asequible.</p><p><strong>Uso:</strong> Regularidad y frecuencia de utilización de servicios financieros de forma pertinente.</p><p><strong>Calidad:</strong> Grado de satisfacción de las necesidades de los clientes con servicios ofrecidos por los mercados.</p><p><strong>Bienestar financiero: </strong>Adecuado manejo y control de la estabilidad financiera, logro de objetivos financieros y de generación de ahorros para eventualidades.</p><h2>¿Cómo nos beneficia la inclusión financiera?</h2><p>Podemos enumerar algunos de los principales beneficios del sistema de inclusión financiera:</p><ul><li><p><strong>Contribuir a la formalización laboral, y así hacer efectivos derechos como salud y seguridad social.</strong></p></li><li><p><strong>Afirmar el derecho del trabajador a elegir dónde y cómo cobrar por los servicios que comercialice o desarrolle.</strong></p></li><li><p><strong>Propiciar la equidad.</strong></p></li><li><p><strong>Mejorar la seguridad de ciudadanos y comerciantes para sus transacciones.</strong></p></li><li><p><strong>Propiciar la transparencia y el control.</strong></p></li></ul><p><strong>¿Qué es un servicio financiero?</strong></p><p>Los servicios financieros son el conjunto de servicios prestados por un grupo de entidades financieras que operan en el país o en jurisdicciones, como los bancos, las cooperativas de crédito, aseguradoras, mutualidades de previsión, agencias y sociedades de bolsa, etc.</p><p><strong>¿Cómo podemos alcanzar una mayor inclusión financiera?</strong></p><img loading="lazy" src="/blog/inclusion-financiera-mujeres/grafico-11.jpg" alt="inclusion financiera"/><p><em>inclusion financiera</em></p><p>Asesoramiento: <a href="/">Karina G. Giusti, Mag. en Dirección de Empresas.</a></p>', 2, '/blog/inclusion-financiera-mujeres/imagen-if.png', 'inclusion financiera', 'Mujeres x Más', '2020-07-27T09:21:04-03:00'::timestamptz),
  ('Home office en tiempos de COVID-19', 'home-office-en-tiempos-de-covid-19', 'La pandemia ha obligado a que muchos países decreten cuarentena total y obligatoria para evitar la propagación del COVID-19. En nuestro país ya son varios los días de confinamiento y esto ha llevado a que muchas…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficios de realizar elongación diaria.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"La pandemia ha obligado a que muchos países decreten cuarentena total y obligatoria para"},{"type":"text","text":" evitar la propagación del ","marks":[{"type":"bold"}]},{"type":"text","text":"COVID-19","marks":[{"type":"bold"},{"type":"link","attrs":{"href":"https://covid19.who.int/"}}]},{"type":"text","text":".","marks":[{"type":"bold"}]},{"type":"text","text":" En nuestro país ya son varios los días de confinamiento y esto ha llevado a que muchas empresas establezcan como "},{"type":"text","text":"nueva modalidad laboral el Teletrabajo","marks":[{"type":"bold"}]},{"type":"text","text":" o también llamado “home office”."}]},{"type":"paragraph","content":[{"type":"text","text":"El teletrabajo o home office hoy en día es una nueva realidad para muchas de nosotras y también desconocida por no saber cómo lidiar con el trabajo, la vida personal y familiar en un mismo espacio. Por lo menos un ambiente de la casa ha pasado a ser una especie de oficina, la cual no está debidamente acondicionada para llevar adelante una rutina laboral de varias horas."}]},{"type":"paragraph","content":[{"type":"text","text":"Resulta inevitable que ante la falta de una silla ergonómica un escritorio de apoyo y otros elementos necesarios para realizar el trabajo diario empiecen a aparecer dolores de espalda, columna cervical y columna lumbar. Es por eso, que a continuación compartimos una serie de beneficios de realizar una elongación diaria que lleve entre diez y quince minutos "},{"type":"text","text":"para poder mantener la rutina laboral de una manera que no termine siendo dañina para nuestras articulaciones.","marks":[{"type":"bold"}]}]},{"type":"image","attrs":{"src":"/blog/home-office-en-tiempos-de-covid-19/home-office-en-tiempos-de-covid-19.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Beneficios de realizar elongación de forma diaria.","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mejora la Circulación Sanguínea, lo que nos permite estar más despiertos mentalmente."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Se previenen Lesiones a futuro."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mayor oxigenación a nivel físico y mental."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nos permite una conexión más profunda con nuestro cuerpo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Se evita la formación de contracturas musculares."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Disminuye el estrés."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Incrementa el rango articular definiendo de forma correcta nuestra postura diaria."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Se relajan y se lubrican las articulaciones."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aumento de energía."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Facilita el descanso."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Es muy "},{"type":"text","text":"importante","marks":[{"type":"bold"}]},{"type":"text","text":" que cada 30 minutos de la jornada de trabajo modifiquemos nuestra postura, parándonos, realizando movimientos circulares de hombros, movimientos suaves de la columna cervical, elongar miembros inferiores o simplemente pararse para preparar un café o ir en busca de un vaso con agua."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Asesoramiento: Virginia Moyano – Profesora de Fitness "},{"type":"text","text":"@moyano.virginia","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/moyano.virginia/"}}]},{"type":"text","text":" / @mi.fitness"}]}]}'::jsonb, '<p><strong>Beneficios de realizar elongación diaria.</strong></p><p>La pandemia ha obligado a que muchos países decreten cuarentena total y obligatoria para<strong> evitar la propagación del </strong><a target="_blank" rel="noopener noreferrer" href="https://covid19.who.int/"><strong>COVID-19</strong></a><strong>.</strong> En nuestro país ya son varios los días de confinamiento y esto ha llevado a que muchas empresas establezcan como <strong>nueva modalidad laboral el Teletrabajo</strong> o también llamado “home office”.</p><p>El teletrabajo o home office hoy en día es una nueva realidad para muchas de nosotras y también desconocida por no saber cómo lidiar con el trabajo, la vida personal y familiar en un mismo espacio. Por lo menos un ambiente de la casa ha pasado a ser una especie de oficina, la cual no está debidamente acondicionada para llevar adelante una rutina laboral de varias horas.</p><p>Resulta inevitable que ante la falta de una silla ergonómica un escritorio de apoyo y otros elementos necesarios para realizar el trabajo diario empiecen a aparecer dolores de espalda, columna cervical y columna lumbar. Es por eso, que a continuación compartimos una serie de beneficios de realizar una elongación diaria que lleve entre diez y quince minutos <strong>para poder mantener la rutina laboral de una manera que no termine siendo dañina para nuestras articulaciones.</strong></p><img loading="lazy" src="/blog/home-office-en-tiempos-de-covid-19/home-office-en-tiempos-de-covid-19.jpg"/><p><strong>Beneficios de realizar elongación de forma diaria.</strong></p><ul><li><p>Mejora la Circulación Sanguínea, lo que nos permite estar más despiertos mentalmente.</p></li><li><p>Se previenen Lesiones a futuro.</p></li><li><p>Mayor oxigenación a nivel físico y mental.</p></li><li><p>Nos permite una conexión más profunda con nuestro cuerpo.</p></li><li><p>Se evita la formación de contracturas musculares.</p></li><li><p>Disminuye el estrés.</p></li><li><p>Incrementa el rango articular definiendo de forma correcta nuestra postura diaria.</p></li><li><p>Se relajan y se lubrican las articulaciones.</p></li><li><p>Aumento de energía.</p></li><li><p>Facilita el descanso.</p></li></ul><p>Es muy <strong>importante</strong> que cada 30 minutos de la jornada de trabajo modifiquemos nuestra postura, parándonos, realizando movimientos circulares de hombros, movimientos suaves de la columna cervical, elongar miembros inferiores o simplemente pararse para preparar un café o ir en busca de un vaso con agua.</p><h3>Asesoramiento: Virginia Moyano – Profesora de Fitness <a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/moyano.virginia/">@moyano.virginia</a> / @mi.fitness</h3>', 2, '/blog/home-office-en-tiempos-de-covid-19/foto.jpg', 'Home office en tiempos de COVID-19', 'Mujeres x Más', '2020-07-13T13:17:36-03:00'::timestamptz),
  ('Coaching ontológico: Qué es y cómo puede ayudarte a potenciar tus actividades', 'coaching-ontologico-que-es-y-como-puede-ayudarte-a-potenciar-tus-actividades', 'El coaching ontológico es una disciplina orientada a transformar el tipo de observador que somos de la realidad, con el objetivo de ampliar nuestras posibilidades y capacidad de acción.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El "},{"type":"text","text":"coaching ontológico","marks":[{"type":"bold"}]},{"type":"text","text":" es una disciplina orientada a transformar el tipo de observador que somos de la realidad, con el objetivo de ampliar nuestras posibilidades y capacidad de acción."}]},{"type":"paragraph","content":[{"type":"text","text":"En inglés coaching significa entrenamiento. Y la palabra ontología refiere al estudio del ser (“onto” significa ente, ser). En otras palabras, el coaching ontológico te da herramientas para transformarte en un ser que comienza a observar el mundo de una forma en que encuentres más oportunidades."}]},{"type":"paragraph","content":[{"type":"text","text":"Para lograrlo propone un proceso de aprendizaje para descubrir recursos y definir acciones que te permitan alcanzar tus objetivos. En ese proceso el coach cumple el rol de facilitador de aprendizaje."}]},{"type":"image","attrs":{"src":"/blog/coaching-ontologico-que-es-y-como-puede-ayudarte-a-potenciar-tus-actividades/tjaime.jpg","alt":null,"title":null}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"¿Para que sirve el coaching ontológico?"}]},{"type":"paragraph","content":[{"type":"text","text":"El coaching ontológico puede aplicarse tanto para iniciar cambios personales como para potenciar tu vida laboral. Te dará herramientas para:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alcanzar tus objetivos, tomar decisiones y pasar a la acción."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Desarrollar tu inteligencia emocional"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Observar las creencias que limitan tu efectividad y bienestar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adquirir competencias conversacionales que te abran posibilidades."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Desarrollar tu capacidad de adaptación a los cambios de manera eficaz."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Estar predispuesto al aprendizaje constante."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Construir vínculos productivos con tu entorno (equipo y colaboradores)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conectar con tu pasión."}]}]}]}]}'::jsonb, '<p>El <strong>coaching ontológico</strong> es una disciplina orientada a transformar el tipo de observador que somos de la realidad, con el objetivo de ampliar nuestras posibilidades y capacidad de acción.</p><p>En inglés coaching significa entrenamiento. Y la palabra ontología refiere al estudio del ser (“onto” significa ente, ser). En otras palabras, el coaching ontológico te da herramientas para transformarte en un ser que comienza a observar el mundo de una forma en que encuentres más oportunidades.</p><p>Para lograrlo propone un proceso de aprendizaje para descubrir recursos y definir acciones que te permitan alcanzar tus objetivos. En ese proceso el coach cumple el rol de facilitador de aprendizaje.</p><img loading="lazy" src="/blog/coaching-ontologico-que-es-y-como-puede-ayudarte-a-potenciar-tus-actividades/tjaime.jpg"/><h2>¿Para que sirve el coaching ontológico?</h2><p>El coaching ontológico puede aplicarse tanto para iniciar cambios personales como para potenciar tu vida laboral. Te dará herramientas para:</p><ul><li><p>Alcanzar tus objetivos, tomar decisiones y pasar a la acción.</p></li><li><p>Desarrollar tu inteligencia emocional</p></li><li><p>Observar las creencias que limitan tu efectividad y bienestar.</p></li><li><p>Adquirir competencias conversacionales que te abran posibilidades.</p></li><li><p>Desarrollar tu capacidad de adaptación a los cambios de manera eficaz.</p></li><li><p>Estar predispuesto al aprendizaje constante.</p></li><li><p>Construir vínculos productivos con tu entorno (equipo y colaboradores)</p></li><li><p>Conectar con tu pasión.</p></li></ul>', 1, '/blog/coaching-ontologico-que-es-y-como-puede-ayudarte-a-potenciar-tus-actividades/tamarajaime.jpg', 'Lic. Tamara Jaime', 'Mujeres x Más', '2020-06-01T12:30:44-03:00'::timestamptz),
  ('Consejos para promover el bienestar emocional frente al COVID-19 y la cuarentena.', 'consejos-parar-promover-el-bienestar-emocional-frente-al-covid-19-y-la-cuarentena', 'Recomendaciones generales basadas en medidas simples que pueden ser efectivas para reforzar nuestro ánimo, regular nuestras emociones y cuidar nuestras relaciones con nuestro entorno familiar.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recomendaciones generales basadas en medidas simples que pueden ser efectivas para"},{"type":"text","text":" reforzar nuestro ánimo, regular nuestras emociones y cuidar nuestras relaciones","marks":[{"type":"bold"}]},{"type":"text","text":" con nuestro entorno familiar."}]},{"type":"paragraph","content":[{"type":"text","text":"Tu salud emocional es clave para cuidarte mejor y cuidar a los demás","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuidá tu cuerpo: ","marks":[{"type":"bold"}]},{"type":"text","text":"Intentá hacer ejercicio y comer lo más sano posible. La actividad física genera innumerables beneficios para tu salud física y mental. Buscá un espacio para relajarte, meditar o estirar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hacé cosas que te gusten:","marks":[{"type":"bold"}]},{"type":"text","text":" Mantené tu mente activa y estimulada. Las actividades gratificantes mejoran el estado de ánimo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Potenciá tu resilencia:","marks":[{"type":"bold"}]},{"type":"text","text":" Es normal sentir malestar en este contexto. Intentá descubrir la mejor manera de transitar esta situación y salir fortalecida de ella."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuidá tu entorno: ","marks":[{"type":"bold"}]},{"type":"text","text":"Podés modificar espacios para que sean funcionales. El control del ambiente es un recurso que sirve para regular nuestros estados internos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Intentá establecer algunas rutinas:","marks":[{"type":"bold"}]},{"type":"text","text":" ellas sostienen nuestro ánimo y ayudan a cumplir las tareas necesarias. Es importante crear rutinas de trabajo y de espacios personales separados."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conectate con quienes más querés: ","marks":[{"type":"bold"}]},{"type":"text","text":"Una manera de regular nuestras emociones es a través del contacto con nuestros seres queridos, hablar de cómo nos sentimos y escuchar a nuestros seres queridos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filtrá la información: ","marks":[{"type":"bold"}]},{"type":"text","text":"Escuchar demasiadas noticias puede generar ansiedad, es recomendable acortar el tiempo de exposición frente a tanta información."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No suspendas tu tratamiento:","marks":[{"type":"bold"}]},{"type":"text","text":" Si te encontrás bajo algún tratamiento médico o psicológico no es recomendable suspenderlo, podés hacer una consulta si el malestar aumenta o aparecen nuevos síntomas, ya que sentir malestar o preocupación es común en estas situaciones."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pedí ayuda: ","marks":[{"type":"bold"}]},{"type":"text","text":"Si presentás síntomas de "},{"type":"text","text":"ansiedad o depresión","marks":[{"type":"bold"}]},{"type":"text","text":" es recomendable recurrir a un familiar o especialista. También hay líneas de ayuda y atención online."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Números de urgencias:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":" Emergencias: 107 (SAME) / Violencia de género: 144 / Consumos problemáticos: 141."}]}]}'::jsonb, '<p>Recomendaciones generales basadas en medidas simples que pueden ser efectivas para<strong> reforzar nuestro ánimo, regular nuestras emociones y cuidar nuestras relaciones</strong> con nuestro entorno familiar.</p><p><strong>Tu salud emocional es clave para cuidarte mejor y cuidar a los demás</strong></p><ul><li><p><strong>Cuidá tu cuerpo: </strong>Intentá hacer ejercicio y comer lo más sano posible. La actividad física genera innumerables beneficios para tu salud física y mental. Buscá un espacio para relajarte, meditar o estirar.</p></li><li><p><strong>Hacé cosas que te gusten:</strong> Mantené tu mente activa y estimulada. Las actividades gratificantes mejoran el estado de ánimo.</p></li><li><p><strong>Potenciá tu resilencia:</strong> Es normal sentir malestar en este contexto. Intentá descubrir la mejor manera de transitar esta situación y salir fortalecida de ella.</p></li><li><p><strong>Cuidá tu entorno: </strong>Podés modificar espacios para que sean funcionales. El control del ambiente es un recurso que sirve para regular nuestros estados internos.</p></li><li><p><strong>Intentá establecer algunas rutinas:</strong> ellas sostienen nuestro ánimo y ayudan a cumplir las tareas necesarias. Es importante crear rutinas de trabajo y de espacios personales separados.</p></li><li><p><strong>Conectate con quienes más querés: </strong>Una manera de regular nuestras emociones es a través del contacto con nuestros seres queridos, hablar de cómo nos sentimos y escuchar a nuestros seres queridos.</p></li><li><p><strong>Filtrá la información: </strong>Escuchar demasiadas noticias puede generar ansiedad, es recomendable acortar el tiempo de exposición frente a tanta información.</p></li><li><p><strong>No suspendas tu tratamiento:</strong> Si te encontrás bajo algún tratamiento médico o psicológico no es recomendable suspenderlo, podés hacer una consulta si el malestar aumenta o aparecen nuevos síntomas, ya que sentir malestar o preocupación es común en estas situaciones.</p></li><li><p><strong>Pedí ayuda: </strong>Si presentás síntomas de <strong>ansiedad o depresión</strong> es recomendable recurrir a un familiar o especialista. También hay líneas de ayuda y atención online.</p></li></ul><p><strong>Números de urgencias:</strong> <br/> Emergencias: 107 (SAME) / Violencia de género: 144 / Consumos problemáticos: 141.</p>', 1, '/blog/consejos-parar-promover-el-bienestar-emocional-frente-al-covid-19-y-la-cuarentena/yoga.jpg', 'Mujer haciendo yoga en el balcón', 'Mujeres x Más', '2020-05-29T12:38:40-03:00'::timestamptz),
  ('Como proteger tus datos personales', 'seguridad-e-internet-como-proteger-tus-datos-personales', 'Esta nueva realidad nos forzó directa o indirectamente a volcarnos a los canales digitales para comunicarnos, trabajar, vender, y hacer transacciones a través de los diferentes canales digitales.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Esta nueva realidad nos forzó directa o indirectamente a volcarnos a los canales digitales para comunicarnos, trabajar, vender, y hacer transacciones a través de los diferentes canales digitales."}]},{"type":"paragraph","content":[{"type":"text","text":"Muchos de ellos cuentan hoy con un marco legal que protege nuestros datos, pero no es una realidad existente en el 100% de los casos. Tu información debe ser valiosa para voy y no debe ser comercializada por terceros sin tu conformidad expresa."}]},{"type":"paragraph","content":[{"type":"text","text":"Exponemos nuestra información personal en forma constante sin evaluar críticamente sus consecuencias."}]},{"type":"paragraph","content":[{"type":"text","text":"En este material queremos aportar información para que tu privacidad sea respetada y no seas objeto de los efectos negativos del mal uso de la tecnología y sus canales."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Cuáles son las principales amenazas? ¿Cómo podes protegerte?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Phishing"}]},{"type":"paragraph","content":[{"type":"text","text":"Es cuando los "},{"type":"text","text":"ciberdelincuentes ","marks":[{"type":"link","attrs":{"href":"https://es.wikipedia.org/wiki/Ciberataque"}}]},{"type":"text","text":"utilizan mensajes de correo electrónico con información falsa para engañar y robar datos personales, de tarjetas de crédito, claves y números de cuenta y otros datos personales relevantes para futuras transacciones ilegales."}]},{"type":"paragraph","content":[{"type":"text","text":"Como protegerte:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NO ingreses información en forma directa a través de links en mensajes o correos electrónicos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Verifica que los sitios en los que ingreses información sean SITIOS SEGUROS (en la dirección comience con “HTTPS” debe aparecer el icono de un candado)"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Malware"}]},{"type":"paragraph","content":[{"type":"text","text":"O PROGRAMA MALIGNO /// Los códigos maliciosos como virus o troyanos pueden infectar tu dispositivo, dañarlo, robar tu información o"},{"type":"hardBreak"},{"type":"text","text":"eliminarla."}]},{"type":"paragraph","content":[{"type":"text","text":"Cómo protegerte:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Utiliza soluciones como antivirus (solo de tiendas oficiales)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NO habilites permisos que no resulten necesarios para el fin de la aplicación que desees operar"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No abras archivos adjuntos desde un correo que no conozcas."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Buenas prácticas para proteger tus datos personales y operar con seguridad"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Protegé todos tus dispositivos mediante el bloqueo con una contraseña o patrón."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Utilizá alguna solución de seguridad o antivirus, siempre actualizada en su última versión."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Intentá mantenerte informado acerca de nuevos engaños, amenazas y noticias falsas que se vayan descubriendo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Elegí contraseñas fuertes que mezclen números, letras y caracteres especiales (*, #, ?). No las compartas ni las escribas a la vista de nadie."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuidá los vínculos y los peligros en el mundo digital, tal como lo hacés en el mundo físico, recordando que del otro lado de la pantalla siempre hay una persona."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Almacená claves en el navegador solo si tenés un antivirus instalado y si sos la única persona con acceso al dispositivo. Si es un dispositivo público, no es una práctica aconsejable."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ante alguna acción irregular detectada es fundamental contactar a la entidad que aparece referenciada en la acción para que puedan intervenir y prevenir fraudes y/o ciberdelitos."}]}]}'::jsonb, '<p>Esta nueva realidad nos forzó directa o indirectamente a volcarnos a los canales digitales para comunicarnos, trabajar, vender, y hacer transacciones a través de los diferentes canales digitales.</p><p>Muchos de ellos cuentan hoy con un marco legal que protege nuestros datos, pero no es una realidad existente en el 100% de los casos. Tu información debe ser valiosa para voy y no debe ser comercializada por terceros sin tu conformidad expresa.</p><p>Exponemos nuestra información personal en forma constante sin evaluar críticamente sus consecuencias.</p><p>En este material queremos aportar información para que tu privacidad sea respetada y no seas objeto de los efectos negativos del mal uso de la tecnología y sus canales.</p><p><strong>¿Cuáles son las principales amenazas? ¿Cómo podes protegerte?</strong></p><p>Phishing</p><p>Es cuando los <a target="_blank" rel="noopener noreferrer" href="https://es.wikipedia.org/wiki/Ciberataque">ciberdelincuentes </a>utilizan mensajes de correo electrónico con información falsa para engañar y robar datos personales, de tarjetas de crédito, claves y números de cuenta y otros datos personales relevantes para futuras transacciones ilegales.</p><p><strong>Como protegerte:</strong></p><ul><li><p>NO ingreses información en forma directa a través de links en mensajes o correos electrónicos.</p></li><li><p>Verifica que los sitios en los que ingreses información sean SITIOS SEGUROS (en la dirección comience con “HTTPS” debe aparecer el icono de un candado)</p></li></ul><p>Malware</p><p>O PROGRAMA MALIGNO /// Los códigos maliciosos como virus o troyanos pueden infectar tu dispositivo, dañarlo, robar tu información o<br/>eliminarla.</p><p><strong>Cómo protegerte:</strong></p><ul><li><p>Utiliza soluciones como antivirus (solo de tiendas oficiales).</p></li><li><p>NO habilites permisos que no resulten necesarios para el fin de la aplicación que desees operar</p></li><li><p>No abras archivos adjuntos desde un correo que no conozcas.</p></li></ul><h3>Buenas prácticas para proteger tus datos personales y operar con seguridad</h3><ul><li><p>Protegé todos tus dispositivos mediante el bloqueo con una contraseña o patrón.</p></li><li><p>Utilizá alguna solución de seguridad o antivirus, siempre actualizada en su última versión.</p></li><li><p>Intentá mantenerte informado acerca de nuevos engaños, amenazas y noticias falsas que se vayan descubriendo.</p></li><li><p>Elegí contraseñas fuertes que mezclen números, letras y caracteres especiales (*, #, ?). No las compartas ni las escribas a la vista de nadie.</p></li><li><p>Cuidá los vínculos y los peligros en el mundo digital, tal como lo hacés en el mundo físico, recordando que del otro lado de la pantalla siempre hay una persona.</p></li><li><p>Almacená claves en el navegador solo si tenés un antivirus instalado y si sos la única persona con acceso al dispositivo. Si es un dispositivo público, no es una práctica aconsejable.</p></li></ul><p>Ante alguna acción irregular detectada es fundamental contactar a la entidad que aparece referenciada en la acción para que puedan intervenir y prevenir fraudes y/o ciberdelitos.</p>', 2, '/blog/seguridad-e-internet-como-proteger-tus-datos-personales/ima-seg.jpg', 'Seguridad en internet', 'Mujeres x Más', '2020-05-19T16:50:37-03:00'::timestamptz),
  ('Cáncer de mama: ¿Cómo podemos prevenirlo?', 'cancer-de-mama-como-podemos-prevenirlo', 'El cáncer de mama es una de las principales causas de muerte en nuestro país y la forma de sobrevivir a esta enfermedad es solo uno: LA DETECCION TEMPRANA. Esta detección permite aplicar un tratamiento especializado…', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El cáncer de mama es una de las principales causas de muerte en nuestro país y la forma de sobrevivir a esta enfermedad es solo uno: LA DETECCION TEMPRANA. Esta detección permite aplicar un tratamiento especializado y oportuno, de ahí la importancia de campañas para concientizar a la población."}]},{"type":"paragraph","content":[{"type":"text","text":"Varios países de América Latina y el Caribe presentan algunas de las tasas más elevadas en cuanto a riesgo de fallecer por cáncer de mama, hecho que señala las iniquidades existentes en la región en términos de salud, señala la "},{"type":"text","text":"OMS","marks":[{"type":"link","attrs":{"href":"https://es.wikipedia.org/wiki/Organizaci%C3%B3n_Mundial_de_la_Salud"}}]},{"type":"hardBreak"},{"type":"text","text":"(Organización Mundial de la Salud)."},{"type":"hardBreak"},{"type":"text","text":"El diagnóstico temprano, unido a los avances en el tratamiento, han permitido mejorar los resultados y aumentar la supervivencia."}]},{"type":"paragraph","content":[{"type":"text","text":"Aunque las causas del cáncer de mama todavía son en gran medida desconocidas, existen ciertos factores a tener en cuenta que has sido identificados como factores de riego:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Historia familiar de enfermedad"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"La primera menstruación a edad muy temprana"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tener un primer hijo a una edad tardía"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"El uso exagerado de hormonas"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Obesidad y/o consumo excesivo de alcohol"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"La detección temprana, unida a un diagnóstico y tratamiento adecuados, son las mejores herramientas disponibles en la actualidad para evitar las muertes por cáncer de mama."},{"type":"hardBreak"},{"type":"text","text":" Ante cualquier duda se debe acudir al centro de salud más próximo al domicilio o a su médico de cabecera."}]},{"type":"image","attrs":{"src":"/blog/cancer-de-mama-como-podemos-prevenirlo/autoexploacion.jpg","alt":"Autoexplórate.","title":null}}]}'::jsonb, '<p>El cáncer de mama es una de las principales causas de muerte en nuestro país y la forma de sobrevivir a esta enfermedad es solo uno: LA DETECCION TEMPRANA. Esta detección permite aplicar un tratamiento especializado y oportuno, de ahí la importancia de campañas para concientizar a la población.</p><p>Varios países de América Latina y el Caribe presentan algunas de las tasas más elevadas en cuanto a riesgo de fallecer por cáncer de mama, hecho que señala las iniquidades existentes en la región en términos de salud, señala la <a target="_blank" rel="noopener noreferrer" href="https://es.wikipedia.org/wiki/Organizaci%C3%B3n_Mundial_de_la_Salud">OMS</a><br/>(Organización Mundial de la Salud).<br/>El diagnóstico temprano, unido a los avances en el tratamiento, han permitido mejorar los resultados y aumentar la supervivencia.</p><p>Aunque las causas del cáncer de mama todavía son en gran medida desconocidas, existen ciertos factores a tener en cuenta que has sido identificados como factores de riego:</p><ul><li><p>Historia familiar de enfermedad</p></li><li><p>La primera menstruación a edad muy temprana</p></li><li><p>Tener un primer hijo a una edad tardía</p></li><li><p>El uso exagerado de hormonas</p></li><li><p>Obesidad y/o consumo excesivo de alcohol</p></li></ul><p>La detección temprana, unida a un diagnóstico y tratamiento adecuados, son las mejores herramientas disponibles en la actualidad para evitar las muertes por cáncer de mama.<br/> Ante cualquier duda se debe acudir al centro de salud más próximo al domicilio o a su médico de cabecera.</p><img loading="lazy" src="/blog/cancer-de-mama-como-podemos-prevenirlo/autoexploacion.jpg" alt="Autoexplórate."/>', 1, '/blog/cancer-de-mama-como-podemos-prevenirlo/prevencion2.png', 'Prevención del cáncer de mama', 'Mujeres x Más', '2020-05-18T18:57:33-03:00'::timestamptz)
